INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2, '003da23c-6b31-4b91-b1e0-c30811a14ea5', 'L2023:6901', NULL, NULL, 'Område med fossil åkermark', 'Fornlämning', 'Hör till fäbod med belägg före år 1850. Har till synes ej förändrats sedan storskifteskarta från år 1824.', 'Område med fossil åkermark ca 100 x 45-70 m (NNV-SSÖ) bestående av minst 1 fossil åker och minst 6 röjningsrösen. Fossil åker, oregelbunden, ca 35-85 m l (NNV-SSÖ) och 24-40 m br. Avgränsas i S av terasskant, ca 0,4 m h och hak i NNV, intill 0,3 m dj. Utmed V och SV sidan är utkastad röjningssten i slänt. Röjningsrösena är mestadels ovala, 1-8 x 1-4 m st och 0,3-0,8 m h, belägna främst utmed dess ytterkant.', 'S sluttande stenig moränmark. Skogsmark (avverkningsyta, barrskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Åverkan', 'Ej undersökt', 'Synlig ovan mark', 60.8305508, 15.4855768, 526402.4, 6744011.3, 526348, 6743961, 526452, 6744061, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.4855397,60.8309958],[15.4858029,60.8308576],[15.4863232,60.8304897],[15.4863383,60.8304091],[15.4864838,60.8303094],[15.4864174,60.830182],[15.4861394,60.8301685],[15.4859201,60.8301029],[15.4856131,60.8301801],[15.4854024,60.8302745],[15.485263,60.8304255],[15.4848811,60.8304953],[15.4847337,60.8304798],[15.4845953,60.830662],[15.4848523,60.8307205],[15.4847376,60.8308127],[15.4850011,60.830902],[15.4855397,60.8309958]]]}', 0, 5, '2023-11-09T15:56:25.922+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', 'b2aa88b1ab729591d3a9b1d220a7376d');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (12, '00cf79f4-da17-470f-b048-7a2bb9a736b2', 'L2001:1692', 'Bjursås 32:1', 'bjursås 32:1', 'Hyttområde', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Hyttområde, 370x30-60 m st (Ö-V), bestående av 1 omschaktat slaggvarp, (plats förslaggvarp) och 1 slaggförekomst.Området är beläget vid och under en stor industrianläggning. (Sågmyra yllefabrik) 1896-1976, vilken byggts över en bred, numera vidgad och uppdämd å (VNV-ÖSÖ). Intill ochSÖ om S delen av tegelbyggnad är:Slaggvarpet, som 1967 var ca 30x15 m st (Ö-V), 1994, 20x5 m st (N-S). Restenbortfördes vid uppförande av byggnad.Bruna, platta slaggstycken, 0.05-0.1 m st. Blandat med grus och omschaktat. Ursprungligplats(?)Längs stränderna av dammen V om varpet är:Slaggförekomsten, ett 300 m l område (Ö-V).Vid ån fanns en järnhytta under 1500-1600-talen. I början av 1820-talet upptäcktes iSågens by en koppargruva med inslag av nickel, och en kopparhyttaanlades på 1830-talet, lades ned och återupptogs 1845 som koppar- och nickelverk till 1880-talet.Vid en åbro VNV därom låg 1967 två meterstora metallsmältor. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', NULL, NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7120311, 15.2920906, 515940.7, 6730748.2, 515762, 6730693, 516110, 6730801, 0, 'GeometryCollection', '{"type":"GeometryCollection","geometries":[{"type":"Point","coordinates":[15.2951789,60.7115374]},{"type":"LineString","coordinates":[[15.2945445,60.7119869],[15.2939572,60.7120507],[15.293682,60.71208],[15.2933994,60.7121147],[15.2931497,60.7121441],[15.2928857,60.7121609],[15.2926616,60.7121994],[15.2924671,60.7122183]]},{"type":"LineString","coordinates":[[15.2945071,60.7118252],[15.2942683,60.7118619],[15.2940701,60.7118843],[15.2938794,60.7118996],[15.2936813,60.7119149],[15.2935531,60.7119179],[15.2933919,60.7119172],[15.2932346,60.7119058],[15.2930668,60.7118727],[15.2929243,60.7118523],[15.292804,60.7118213],[15.2926504,60.7118045],[15.2923279,60.711812],[15.2919943,60.7118339],[15.2914437,60.7118979],[15.2910616,60.7119626],[15.2908965,60.711978],[15.2906467,60.7120182],[15.2903272,60.7120598],[15.2901287,60.712102],[15.2898081,60.7122047],[15.2896533,60.7122597],[15.2894542,60.7123342],[15.2893068,60.7123802],[15.2890568,60.7124312],[15.2888357,60.7125038]]}]}', 0, 30, '2018-10-01T09:40:44+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'ebddf2d3953b3409c5b9d5e9f19f5c0b');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (13, '00df093d-1ac8-42d7-910f-2e46e66e8440', 'L2023:5695', NULL, NULL, 'Husgrund, historisk tid', 'Fornlämning', 'Delvis överlagrad av äldre väg/stig synlig på storskifteskarta från år 1827 samt röjningsröse vilket antyder att husgrunden är äldre än så.
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (20, '0131de2e-30b9-48e6-80af-ec28a333a848', 'L2001:2133', 'Bjursås 36:1', 'bjursås 36:1', 'Bro', 'Ingen antikvarisk bedömning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Valvbro, förstörd och borttagen(?). Enligt inventeringen 1967 varbron 7 m l (NNV-SSÖ), 5 m br och 1.5 m h med ett spann. Byggd av tuktade gråstenar. Vägbanan överbron används ej längre.1994 fanns inga spår av bron. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', NULL, 'Omedelbart ÖNÖ om ny bro och väg.', NULL, NULL, 'Bekräftad i fält', 'Förstörd', 'Okänd', 'Synlig ovan mark', 60.7184134, 15.4577567, 524976.9, 6731510.6, 524976, 6731510, 524977, 6731511, 0, 'Point', '{"type":"Point","coordinates":[15.4577567,60.7184134]}', 0, 20, '2018-10-01T09:43:12+02:00', 'Riksantikvarieämbetet', '2026-11-17', '49b10a4c4d06921e9bfc78308966d9fc');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (22, '01569137-b1d2-4c3f-b437-01b2f0ebdd94', 'L2001:2161', 'Bjursås 50:2', 'bjursås 50:2', 'Fäbod', 'Ingen antikvarisk bedömning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', '1) Fäbodlämning, 65x50 m st (N-S), bestående av 1 (-2) husgrunder, 1 ruin och 1brunn samt en raserad ladugård (N-S) med timmer och tegeltak.Stuggrunden, i V, är 7x5 m st (N-S) med spisröse vid mitten av V långsidan.2) Fäbodlämning, uppgift om, med en markerad stuga på karta från 1912, ej återfunnengrund 1994 och troligen bortschaktad vid vägbygge.Saknar äldre belägg. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Svagt Ö-sluttande morän- och sedimentmark. Skogsmark (igenväxandegläntor i högblandskog).', 'Stuggrunden är 17 m Ö om körväg (N-S).', NULL, NULL, 'Uppgift om lämning, ej bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7078439, 15.4489909, 524506.6, 6730330.1, 524506, 6730330, 524507, 6730331, 0, 'Point', '{"type":"Point","coordinates":[15.4489909,60.7078439]}', 0, 30, '2018-10-01T09:43:23+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'ccd90bf084b2f476b289d1125b8ced84');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (26, '018792b2-d340-4fb0-a185-17b34007887b', 'L2000:8503', 'Stora Kopparberg 264:1', 'stora kopparberg 264:1', 'Bytomt/gårdstomt', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', NULL, NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6731639, 15.5630193, 530763.5, 6726515.5, 530763, 6726515, 530764, 6726516, 0, 'Point', '{"type":"Point","coordinates":[15.5630193,60.6731639]}', 0, 30, '2018-10-01T11:08:15+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'd5dc9997428c962d4ec2736ac3e6d6bc');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (29, '01bc6cdf-73d9-48cf-b5a0-bcd7a87b22d0', 'L2023:5945', NULL, NULL, 'Gruvhål', 'Fornlämning', 'Uppgift om gruvdrift i området från 1500-talet fram till mitten av 1800-talet.  Äldre tiders bruk och varaktigt övergiven.', 'Gruvhål, bestående av 1jordrymning, rektangulär, ca 3 x 2,5 m (NV-SÖ) och 0,5 m dj till vattenyta. Vattenfylld. Omgiven av en vall, 1,5-2 m br och 0,2-0,4 m h.', 'Kuperad moränmark. Barrskog (avverkningsyta)', NULL, NULL, NULL, 'Bekräftad i fält', 'Åverkan', 'Ej undersökt', 'Synlig ovan mark', 60.7321365, 15.3559835, 519415.5, 6733004.7, 519415, 6733004, 519416, 6733005, 0, 'Point', '{"type":"Point","coordinates":[15.3559835,60.7321365]}', 0, 25, '2023-10-20T09:00:40.006+02:00', 'Länsstyrelsen Dalarna', '2026-11-17', 'a6cd1cd115cc6bc455345a55007572f8');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (38, '027f9b79-21fa-4a74-b771-9783f232e87d', 'L2023:6656', NULL, NULL, 'Bytomt/gårdstomt', 'Ingen antikvarisk bedömning', NULL, 'Uppgift om gårdstomt, ca 40 x 30 m (ÖNÖ-VSV) enligt utsträckning på storskifteskarta från år 1819. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (63, '03fe8a55-860d-412e-9e39-ba488f9ca52b', 'L2000:1942', 'Leksand 892:1', 'leksand 892:1', 'Uppfordringsanläggning', 'Fornlämning', 'Järnmalmsfyndigheten vid Sörskogsgruvorna, till vilken denna hjulgrav tillhör, ska ha upptäckts år 1842 (tillkommit före år 1850).  Brytningen ska ha utförts genom krutsprängning (forna tiders bruk). Gruvan lades ned år 1873 (varaktigt övergiven).', 'Hjulgrav, 15x5 m (NÖ-SV) och intill 0.6 m h. Dubbla väggar i kallmur av 0.2-1 m st stenar och block. Själva graven är 10 x 1,7m och intill 2 m dj. 10 m N om hjulgraven är två dumphögar invid diket som lett bort vattnet från platsen. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (71, '04b13476-5016-4669-9247-38a1222a6f91', 'L2001:1977', 'Bjursås 89:1', 'bjursås 89:1', 'Område med fossil åkermark', 'Fornlämning', NULL, 'Område med fossil åker, 30x30 m st, bestående av 1 kullformig åkerteg samt 2 stenmurar.Den kullformiga åkertegen, är 20x20 m st med grusig jordmån.Murarna, omger åkertegen i S och delvis V och Ö, är 27 respektive12 m l, 2-3 m br och intill1.9 m h, bestående av 0.2-1 m st stenar och block i kallmur.Skiss i inventeringshandlingarna. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'S-sluttning av bergs- och moränhöjd. Blockrik terräng. Skogsmark(blandskog).', NULL, 'Enligt traditionen ska jorden ha burits upp från Rällsjöbo till denna potatisåker. Platsenkallas räknehälla, därför att man kunde räkna kyrktorn härifrån.Sagesman Claes Frisk, ca 60 år, Rällsjöbo.', 'Räknehällan', 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7693892, 15.3015003, 516424.9, 6737139, 516409, 6737119, 516441, 6737157, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.3015398,60.7692147],[15.3016247,60.7692321],[15.3017105,60.7692817],[15.3017746,60.7693477],[15.301795,60.7694193],[15.3017673,60.769477],[15.301717,60.7695168],[15.3015745,60.7695393],[15.3014316,60.7695474],[15.3013025,60.7695214],[15.3012278,60.7694734],[15.3012188,60.7694143],[15.3012208,60.7693514],[15.3012737,60.7692775],[15.3013827,60.7692391],[15.3014961,60.7692258],[15.3015398,60.7692147]]]}', 0, 10, '2018-10-01T09:42:19+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'df819e1e481e17ff8a86a0813579fb2b');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (76, '0508a46f-a001-4310-95c9-7994b84b6cde', 'L2023:6354', NULL, NULL, 'Dammvall', 'Fornlämning', 'Redovisad på karta från år 1819', 'Dammvall, ca 13 m l (NNÖ-SSV) , 1,5-3 m br och 0,4- m h av stenar, överväxt. I vattnet syns en stock som går tvärs över vattendraget. inget synligt på motsatta sidan där det är gräsmatta på tomt.', 'Svag dalsänka i kuperad moränmark. Skogsmark (lövskog) i öppen småbruten bymiljö.', NULL, NULL, NULL, 'Bekräftad i fält', 'Åverkan', 'Ej undersökt', 'Synlig ovan mark', 60.7753427, 15.4034329, 521973.8, 6737831.9, 521973, 6737826, 521975, 6737837, 0, 'LineString', '{"type":"LineString","coordinates":[[15.4034201,60.7752983],[15.4034457,60.7753871]]}', 0, 15, '2023-10-31T15:06:16.125+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', '3708570350be6eb7bc5559c25e8d8ef2');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (85, '0599bfdc-6172-42e5-a9a2-1394267704c7', 'L2001:954', 'Bjursås 84:1', 'bjursås 84:1', 'Fäbod', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fäbod, ej övergiven. Ej avgränsad.Skiss i inventeringshandlingarna. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', NULL, NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.77974, 15.4952132, 526969.1, 6738355.9, 526969, 6738355, 526970, 6738356, 0, 'Point', '{"type":"Point","coordinates":[15.4952132,60.77974]}', 0, 30, '2018-10-01T09:36:32+02:00', 'Riksantikvarieämbetet', '2026-11-17', '86d4e2ffd704b8738647a9cc842c5573');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (93, '05e2d2d1-8753-4150-9f96-7491684267d3', 'L2001:1265', 'Bjursås 65:1', 'bjursås 65:1', 'Färdväg', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fäbodstig, i sin nuvarande iakttagbara utsträckning ca 1000 m l (NÖ-SV). I NV är ca 100m av stigen använd som skogsmaskinväg. Bitvis, särskilt N halvan,är stigen mycketvälbevarad. Stigen passerar RAÄ-nr 64, Näs-mors vilsten, på sin väg från Bjursås viaFjällgrycksbo mot Dubblarbo och Baggbo fäbodar. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', NULL, NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7800421, 15.5365005, 529217.3, 6738407.2, 528859, 6738189, 529472, 6738722, 0, 'LineString', '{"type":"LineString","coordinates":[[15.5412082,60.7828444],[15.5408799,60.7826095],[15.5405799,60.7823297],[15.5404305,60.7820561],[15.5404163,60.7817531],[15.5404138,60.7814841],[15.5404383,60.7812687],[15.5404669,60.7810766],[15.5405759,60.7808661],[15.5402425,60.7807299],[15.5394909,60.7806016],[15.5389416,60.7804918],[15.5386742,60.7803516],[15.5384007,60.7802671],[15.5380647,60.7801758],[15.5374748,60.7800536],[15.5367656,60.7800111],[15.5363237,60.7799473],[15.5359366,60.7798652],[15.5355759,60.7798207],[15.5352251,60.7797223],[15.5350239,60.7795889],[15.5348809,60.7794319],[15.5346365,60.7793347],[15.534435,60.7791887],[15.5340762,60.7790599],[15.5335555,60.778914],[15.5329899,60.7787325],[15.5326603,60.7785981],[15.5322539,60.7784767],[15.5319864,60.7783329],[15.5316022,60.7782167],[15.5311228,60.7781119],[15.5307273,60.7781464],[15.5303844,60.7782399],[15.5301046,60.7783617],[15.5298978,60.7784651]]}', 0, 25, '2018-10-01T09:38:14+02:00', 'Riksantikvarieämbetet', '2026-11-17', '4cc0633467e1297ea4772748da8027bc');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (95, '060196a9-de7e-4bf8-b498-a49500d594ae', 'L1998:173', 'Stora Kopparberg 559', 'stora kopparberg 559', 'Gränsmärke', 'Övrig kulturhistorisk lämning', NULL, 'Gränsröse, oval, 1,4x1,1 m st och 0,5 m h, kallmurat av mestadels flata stenar, 0,2-0,4 m st.
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (98, '064b33ca-6e8c-4793-a0b1-4054894eb886', 'L2001:953', 'Bjursås 83:1', 'bjursås 83:1', 'Fäbod', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fäbod, ej övergiven. Ej avgränsad. Markeringen avser en godtyckligt vald plats inomfäbodstället Gammals fäbodar.S om markeringen, inom ett ca 500x100-400 m st (NÖ-SV) område, finns talrika terrasserade,fossila åkrar samt röjningsrösen. Dessa lämningar stämmer i huvudsak med storskifteskartansuppgifter.Enligt Forsslund (Bjursås, Ål s. 42) är Gammals den översta klaseni Björsbgerg och ejfäbodställe. Kallas dock fäbodar på storskifteskartan. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', NULL, NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7864394, 15.4790802, 526085.1, 6739095.6, 526085, 6739095, 526086, 6739096, 0, 'Point', '{"type":"Point","coordinates":[15.4790802,60.7864394]}', 0, 30, '2018-10-01T09:36:32+02:00', 'Riksantikvarieämbetet', '2026-11-17', '225548e148883e23a7e31c8038a7caca');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (122, '07673439-b11d-478f-b5ac-09941af22297', 'L1998:2289', 'Stora Kopparberg 579', 'stora kopparberg 579', 'Fossil åker', 'Fornlämning', NULL, 'Fossil åker, rektangulär, ca 62x37 m (NÖ-SV), bestående av två odlingsytor, inbördes åtskilda av ett murliknande röjningsröse ca 30 m l (NÖ-SV), 4 m br och intill 1 m h. Odlingsytorna avgränsas mot omgivande mark av hak i NV och NÖ samt av vägbank i SV (RAÄ dnr 321-4220-2009).', 'Flack moränmark. Skogsmark, tät blandskog.', 'I SÖ gränsar odlingsytan till tomtmark.', NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Delundersökt', 'Synlig ovan mark', 60.6680179, 15.5428325, 529665.2, 6725933.1, 529632, 6725900, 529694, 6725970, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5422372,60.6679854],[15.5426164,60.6677237],[15.5428035,60.6677998],[15.5429227,60.667853],[15.5433497,60.6680446],[15.5430981,60.6683449],[15.542587,60.6680798],[15.5422372,60.6679854]]]}', 0, 10, '2018-10-01T12:18:49+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'f730d0218db2b7676f98a6c6e4c36957');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (128, '0810451e-a72a-43bd-9aa3-77d56b01885b', 'L2023:7060', NULL, NULL, 'Kolningsanläggning', 'Övrig kulturhistorisk lämning', NULL, 'Kolbotten efter resmila, rund, 11 m diam och 0,3-1 m h med ojämn yta.', 'Fot av S sluttande moränmark invid myrmark, våtmarker. Skogsmark (barrskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Grov skada', 'Ej undersökt', 'Synlig ovan mark', 60.8215255, 15.4485994, 524398.8, 6742991.7, 524398, 6742991, 524399, 6742992, 0, 'Point', '{"type":"Point","coordinates":[15.4485994,60.8215255]}', 0, 25, '2023-11-11T17:57:41.977+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', '0665be70585af8bcd6c06d7b259911a5');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (133, '08771fed-6bcb-414d-81b5-aeb5a71e371e', 'L2023:6861', NULL, NULL, 'Bytomt/gårdstomt', 'Fornlämning', 'Andersbo omnämns som nybygge 1563. 1588 fanns en hemmansägare. 1639 fanns sex hemmansägare. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (136, '08be3bd7-f92a-45d9-9d87-73413b92797b', 'L2001:2230', 'Bjursås 97:1', 'bjursås 97:1', 'Gruvområde', 'Fornlämning', NULL, 'Gruvområde, 40x30 m st (N-S), bestående av 3 gruvhål och 1 malmtorg(?).Gruvhålen, är 5-7x3 m st och 1-1.5 m dj till vattenyta. Skrotstenrunt kanterna.Malmtorg(?) i S, på en 9 m diam och 1 m h skrotstensplan, bestående av 5-6 malmhögar, 1-2 mdiam och 0.5 m h. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'SÖ-sluttning av bergs- och moränhöjd. Skogmark (blandskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7779686, 15.3005108, 516366.7, 6738094.4, 516351, 6738075, 516381, 6738111, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.3007154,60.7780661],[15.3006624,60.7781177],[15.3005267,60.7781166],[15.3003694,60.7781045],[15.3002652,60.7780408],[15.3002386,60.7779563],[15.300303,60.7778923],[15.3004193,60.7778144],[15.300559,60.777803],[15.3007182,60.7778689],[15.3007737,60.7779662],[15.3007154,60.7780661]]]}', 0, 10, '2018-10-01T09:43:46+02:00', 'Riksantikvarieämbetet', '2026-11-17', '9f7efab38aa15623f19a9e8739e64907');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (142, '0907ef41-c4ca-4731-a080-57413930f573', 'L2000:9194', 'Stora Kopparberg 215:1', 'stora kopparberg 215:1', 'Bytomt/gårdstomt', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', NULL, NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.654177, 15.5576216, 530486.5, 6724398.3, 530486, 6724398, 530487, 6724399, 0, 'Point', '{"type":"Point","coordinates":[15.5576216,60.654177]}', 0, 30, '2018-10-01T11:11:41+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'f2871a1392239dc4671dba7f09307970');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (162, '0a2423ff-305a-48d6-a9a4-b4e99da7c9db', 'L2023:7061', NULL, NULL, 'Kolningsanläggning', 'Övrig kulturhistorisk lämning', NULL, 'Kolbotten efter liggmila, kvadratisk, 8,5 x 8,5 m st (NÖ-SV) och 0,2-0,8 m h, med flack yta. Stybbdiken förekommer, ca 0,5-1,5 m br och 0,3-0,4 m dj.', 'SSV-sluttande moränmark. Skogsmark (blandskog, övervägande barr).', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.8224169, 15.4494018, 524441.7, 6743091.3, 524441, 6743091, 524442, 6743092, 0, 'Point', '{"type":"Point","coordinates":[15.4494018,60.8224169]}', 0, 25, '2023-11-11T18:00:39.674+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', 'ce5202e46c43ff71dbeff70a01274b0b');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (164, '0a3d3f66-f40b-445a-ab0b-232e83206f8b', 'L2023:6350', NULL, NULL, 'Småindustriområde', 'Fornlämning', 'På  karta från år 1828 är två kvarnsymboler redovisade på denna plats.', 'Småindustriområde 60 x 25 m (N-S) bestående av minst 2 husgrunder och 1 dammvall. I N är en husgrund, rektangulär, 8 x 5 m (NNV-SSÖ) bestående av kallmurade brutna stenar, ca 0,3-1 m st. I mitten av husgrunden är ett dike, ca 1 m br och 0,8 m dj. En bit nedströms ligger ytterligare en husgrund, rektangulär, 10 x 5 m (NNV-SSÖ) och 1,5 m h av kallmurade brutna stenar. En dammvall går genom husgrunden. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (168, '0a56ff50-9f0b-4898-9183-e35046e8e6ba', 'L2001:2079', 'Bjursås 56:3', 'bjursås 56:3', 'Övrigt', 'Övrig kulturhistorisk lämning', NULL, '1) Fäbodlämning, 480x50-200 m st (Ö-V).  Utsträckning enligt LMV-karta från1822-24. Centralt i området är ett område, 50x20 m st (N-S), med rester efter en källargrund. Iområdets V del, eller inom nr 2, är en källargrund samt en senareuppförd stuga ochekonomibyggnad.10 m N om nr 1 är:2) Fäbodlämning, 70x30 m st (VNV-ÖSÖ).  Utsträckning enligt LMV-karta från1822-24.Delar av fäboden ligger i Leksands socken (RAÄ-nr 456).Vid ombeskrivning och omnumrering (för ADB) kan ej uttolkas huruvida 1 källargrund, 1 stugaoch 1 ekonomibyggnad ligger inom nr 1 eller nr 2. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'S-sluttande blockrik moränmark. Skogsmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.8668865, 15.5949744, 532314, 6748107.3, 532294, 6748086, 532333, 6748127, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5951224,60.8670172],[15.5950969,60.8670371],[15.5949019,60.8670637],[15.5947734,60.8670438],[15.5946268,60.8669844],[15.5946274,60.8668876],[15.5947565,60.866809],[15.5949887,60.8667126],[15.5951541,60.8667021],[15.5953042,60.866783],[15.5953186,60.8668421],[15.5952704,60.8669066],[15.5951338,60.8669995],[15.5951224,60.8670172]]]}', 0, 10, '2018-10-01T09:42:55+02:00', 'Riksantikvarieämbetet', '2026-11-17', '6b8ddb9493ceac245582c9fd1b931d64');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (188, '0c568165-65c4-4872-8cbd-ee65cc105bcd', 'L2001:2047', 'Bjursås 54:1', 'bjursås 54:1', 'Fäbod', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', '1) Fäbodlämning, 1050x50-400 m st (Ö-V). Utsträckning enligt LMV-karta från 1808.I områdets centrala och V del är två bebyggelseområden, varav detNÖ består av 2 stugor, 4ekonomibyggnader, 2 jordkällare samt 4 grunder efter ekonomibyggnader. 150 m SV om dettaär ett område med 4 stugor, 7 uthus och 1 grund efter ekonomibyggnader.Runt dessa områden är stenröjda ytor, odlingsrösen, stengärdesgårdar, åkerhak ochterrasskanter.Området används idag som fritidsbostäder. Någon byggnad är nyligenhitflyttad från  annanplats.30 m S om nr 1 är:2) Fäbodlämning, 140-170x30-120 m st (Ö-V). Utsträckning enligt LMV-karta från 1808,troligen bestående av rester efter 2 ekonomibyggnader.Vid omnumrering med därtill ändrad beskrivning för ADB, framkom inte klart huruvida derester som anges under nr 2 ligger där, eller inom nr 1.Namn enligt ekonomiska kartan. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'S-sluttning av berg. Skogsmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7723599, 15.5473092, 529813, 6737556.5, 529254, 6737334, 530297, 6737751, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.541729,60.7721083],[15.5416123,60.7719164],[15.5414697,60.7717818],[15.5412608,60.7717136],[15.5408973,60.7717528],[15.540512,60.77177