INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (198, '0d029dfb-99a7-4c1e-bdec-4efbc09cc690', 'L2001:2046', 'Bjursås 53:1', 'bjursås 53:1', 'Fäbod', 'Fornlämning', NULL, 'Fäbodlämning, 250x250 m st, bestående av 5 stugrester med spismursrösen, 5 grunderefter ekonomibgyggnader och i områdets Ö del, 1 kvarstående ekonomibyggnad, fördelade påtre bebyggelseområden i fäbodens S halva. Dessutom finns stenröjdaytor, ett 30-talröjningsrösen, 4-10 m diam och 0.3-1 m h, 1 stengärdesgård, diken,terrasskanter ochåkerhak.Välbevarat område. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'S-sluttning av bergshöjd. Skogsmark (blandskog). F.d. vallområde.', NULL, NULL, 'Baggfäbodarna', 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.8067789, 15.5523612, 530056, 6741392.3, 529931, 6741255, 530177, 6741494, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5510719,60.8059513],[15.5511446,60.8059186],[15.5513158,60.8058584],[15.5515664,60.8057368],[15.5517948,60.8056081],[15.5520323,60.8055564],[15.5522649,60.8056071],[15.5525801,60.8057398],[15.5527698,60.8058391],[15.5530304,60.805834],[15.5532351,60.8057933],[15.5534274,60.8058478],[15.553782,60.8059336],[15.5540314,60.806081],[15.5540073,60.8063053],[15.5540469,60.8064306],[15.5542132,60.8066323],[15.5543276,60.8068128],[15.5544534,60.8070111],[15.5545794,60.8072167],[15.5545139,60.8074],[15.5542426,60.807581],[15.5538469,60.8076228],[15.5532959,60.8076206],[15.5529118,60.8076893],[15.5521464,60.8076256],[15.5512167,60.8076078],[15.5503542,60.8076326],[15.5500798,60.8075212],[15.5500826,60.8073257],[15.550171,60.8070184],[15.5504735,60.8067584],[15.5507944,60.8064964],[15.5509129,60.8062213],[15.5510397,60.8059892],[15.5510719,60.8059513]]]}', 0, 10, '2018-10-01T09:42:41+02:00', 'Riksantikvarieämbetet', '2026-11-17', '5767dfbd68ff1b700c724f8b5253e15f');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (207, '0dbea599-8648-4f3d-9a37-7a73b96a8e8b', 'L2024:1228', NULL, NULL, 'Fångstgrop', 'Fornlämning', NULL, 'Fångstgrop, rund, 1,5 m diam och 0,3 m dj, omgiven av en vall, 1-2 m br och intill 0,4 m h. Vid provstick framkom ett 0,03 m tj blekjordsskikt. Bevuxen med gran.', 'O-sluttande moränmark vid bäck.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.8535522, 15.4781079, 525977.7, 6746570.2, 525977, 6746570, 525978, 6746571, 0, 'Point', '{"type":"Point","coordinates":[15.4781079,60.8535522]}', 0, 30, '2024-04-15T17:48:21.978+02:00', 'länsstyrelsen', '2026-11-17', '878a577ad725895a83c7fcde05dd3dec');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (228, '0f221da0-a8dc-4f2c-9302-c08ac9e9daaf', 'L2001:1572', 'Bjursås 76:1', 'bjursås 76:1', 'Boplats', 'Fornlämning', NULL, 'Boplats, minst 35x10 m st (Ö-V), indikerad främst av ett intill 15 m l och 0.5 m tj lager avskärvig och skörbränd sten, varibland påträffades 3 avslag av vitkvarts samt ett antalfragmentariska skifferbitar och en knacksten(?), 6-7 cm st. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Strandplan av sand och trädbevuxen stormvall mot S i N änden av sjö.', '20 m S om åkerhörn.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Ej synlig ovan mark', 60.7319139, 15.2712286, 514793.1, 6732957.8, 514772, 6732947, 514812, 6732966, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.2714254,60.7318234],[15.2715467,60.731837],[15.2715672,60.7319194],[15.2714656,60.7319542],[15.2712791,60.7319698],[15.2710852,60.7319818],[15.2709717,60.7319843],[15.2708905,60.7319633],[15.2708565,60.7319259],[15.2709066,60.7318807],[15.271064,60.7318743],[15.271207,60.7318769],[15.2713201,60.73186],[15.2714254,60.7318234]]]}', 0, 10, '2018-10-01T09:39:59+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'c6751682cb4d3cc2a9a219bc53d55624');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (259, '10f48ba7-7ab7-4ccd-b182-28ff2fe86836', 'L1999:5417', 'Ål 209:1', 'ål 209:1', 'Fäbod', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', NULL, NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6919139, 15.2899756, 515835.2, 6728507.1, 515764, 6728403, 515898, 6728613, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.2907066,60.6919966],[15.2903874,60.692241],[15.2901451,60.6924805],[15.2898817,60.6926696],[15.2896232,60.6927941],[15.2893804,60.6928648],[15.2891719,60.6928531],[15.2889058,60.6927909],[15.2887104,60.6926644],[15.2886835,60.692535],[15.2888402,60.692376],[15.2889825,60.6921971],[15.2892646,60.691983],[15.2895244,60.6917885],[15.2896667,60.6916114],[15.2897691,60.6914163],[15.2898089,60.6912405],[15.2898446,60.6910899],[15.2900034,60.6910117],[15.2902529,60.6909805],[15.2906256,60.6910162],[15.2909181,60.6910354],[15.2911126,60.6912068],[15.2910838,60.6913826],[15.2910619,60.6915835],[15.2909377,60.6917679],[15.2907066,60.6919966]]]}', 0, 10, '2018-10-01T11:47:28+02:00', 'Riksantikvarieämbetet', '2026-11-17', '33f14d317971bdd7219b15362e00adc7');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (269, '12025f20-7c47-43b3-b7a4-557f08d03f9c', 'L2001:2092', 'Bjursås 85:5', 'bjursås 85:5', 'Fäbod', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', '1) Fäbodlämning, 70x70 m (NNÖ-SSV), bestående av minst 5 husgrunder. Dessa är 8x4 ?4x4 m st och intill 0.6 m h. Tre har spisrösen. I områdets S del är ett källdrag.2) Fäbodlämning, 230x230 m st (N-S), bestående av 15 husgrunder, 3åkertegar och 4röjningsrösen.Husgrunderna, är 3-9x3-6 m st och 0.2-1 m h. Två har spisrösen.Åkertegarna, är bandformiga, 15-20x30-50 m st. En avgränsas i SÖ av en intill 2 m hterrassering, en annan i SV av en 3 m br och 1.5 m h stenvall.Röjningsrösena, är 4 m diam och intill 1 m h.3) Fäbodlämning, 140x80 m (NÖ-SV), bestående av 8 husgrunder samt1 ruin.Husgrunderna, är 4-7x4-6 m st och 0.2-0.3 m h. Två har spisrösen.Ruinen, är 4x4 m st, med upp till 8 bevarade stockvarv.Inom nr 2 är:4) Gruvområde, bestående av 1 gruvhål, 1 skärpning och 1 skrotstenshög.Gruvhålet, är 3x3 m st och 1.5 m dj till vattenyta.Skrotstenshögen, belägen omedelbart S om gruvhålet. är 10x7 m st och 1.5 m h.Skärpningen, är 3x2 m st och 2 m dj.5) Fäbodområde, ca 700x60-440 m st (NNV-SSÖ). Inom området, som även går in i Leksandssocken, ligger 3 bebyggelseområden (nr 2-3 samt Leksand RAÄ-nr 977), varav ett (nr 2) äveninnehåller ett gruvområde. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'SV-sluttning av bergs- och moränhöjd. Skogsmark (blandskog och hyggen).', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.8295028, 15.4972482, 527037.9, 6743899.3, 526783, 6743620, 527283, 6744243, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.4943782,60.8323361],[15.4939947,60.8322033],[15.4937345,60.8321644],[15.4934236,60.8320822],[15.4932338,60.8320149],[15.4931949,60.8319322],[15.4931031,60.8317378],[15.4930698,60.8315599],[15.4931094,60.8314092],[15.4931812,60.8313072],[15.4932746,60.8312286],[15.4933767,60.8310818],[15.4934909,60.8310697],[15.4936969,60.8310581],[15.4941165,60.8310312],[15.4944118,60.8309661],[15.4946153,60.8308988],[15.4947826,60.830799],[15.4949127,60.8307259],[15.494913,60.830708],[15.4946007,60.830703],[15.494211,60.8307048],[15.493844,60.8306762],[15.4934956,60.8306334],[15.4932102,60.8305639],[15.492827,60.8304239],[15.4925868,60.8302989],[15.4925954,60.8302343],[15.4927967,60.8300879],[15.4930233,60.8299614],[15.4931829,60.829691],[15.4934195,60.8294317],[15.4935745,60.8292079],[15.4937633,60.8289447],[15.493899,60.8287694],[15.4941164,60.8285495],[15.4948522,60.8287054],[15.4949585,60.8285263],[15.4950798,60.8283347],[15.4953308,60.8280898],[15.4955592,60.8278699],[15.4958177,60.8276125],[15.4960154,60.8274607],[15.4961533,60.8273644],[15.4962983,60.827277],[15.4965774,60.8272855],[15.4969119,60.8272852],[15.4972275,60.8273117],[15.4974876,60.8273542],[15.497748,60.8273841],[15.4979863,60.8274175],[15.4981624,60.8274326],[15.4984049,60.8274355],[15.4987984,60.8274265],[15.4990893,60.8273936],[15.4995799,60.8273042],[15.5000707,60.8272005],[15.5004246,60.8271428],[15.5009187,60.827057],[15.5013134,60.8269815],[15.5014491,60.827],[15.501448,60.8270575],[15.5014083,60.8272118],[15.5012948,60.8273801],[15.5011992,60.8275754],[15.501167,60.8277243],[15.5011324,60.8278049],[15.5012601,60.8278558],[15.5014128,60.8279409],[15.501543,60.8280564],[15.5015817,60.8281445],[15.501723,60.8284487],[15.5016925,60.8286981],[15.501574,60.8289382],[15.5015044,60.8291193],[15.5014309,60.8293147],[15.5013388,60.8295172],[15.5012325,60.8296945],[15.5011389,60.8297857],[15.5013361,60.829853],[15.5015072,60.8299436],[15.5015382,60.8300533],[15.5015236,60.8302382],[15.5013033,60.8304222],[15.5011655,60.8305131],[15.5009732,60.8305751],[15.5008071,60.8306121],[15.5006786,60.8306061],[15.5004849,60.8305442],[15.5002667,60.8304229],[15.5000699,60.8303341],[15.4997997,60.8304299],[15.4995041,60.8305147],[15.4992747,60.8305909],[15.4990608,60.8306313],[15.4988474,60.8306393],[15.4986307,60.8306294],[15.4983518,60.8306048],[15.4979602,60.8305186],[15.497715,60.8304619],[15.4974945,60.8306495],[15.4972399,60.8308943],[15.4969196,60.8311138],[15.4967022,60.8313301],[15.4964195,60.8315084],[15.4961094,60.8317692],[15.4960116,60.8318855],[15.4959102,60.8319964],[15.4958451,60.8321326],[15.4957465,60.8322884],[15.4956786,60.8323815],[15.4956253,60.8324746],[15.4951011,60.8325908],[15.4947069,60.8324436],[15.4943782,60.8323361]]]}', 0, 10, '2018-10-01T09:42:58+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'a3d8fcb84a291e7e758b2baeffe3b391');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (278, '13125312-0805-4cb5-b980-1eb35d0c9676', 'L1998:167', 'Stora Kopparberg 553', 'stora kopparberg 553', 'Kolningsanläggning', 'Övrig kulturhistorisk lämning', NULL, 'Kolbotten, obestämd, ca 10x8 m (NV-SÖ), med gropig yta. I SÖ och SV är en svag vall, 1,5 m br och 0,2 m h. I SÖ och NV är stybbgropar, 4x2 m st och 0,4 m dj. (RAÄ dnr 326-214-2005)', 'SÖ-sluttande moränmark med blockinslag. Skogsmark (tall och hygge).', '4 m NNV om stig och i hyggeskant.', NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6330634, 15.5498384, 530080.6, 6722043.2, 530080, 6722043, 530081, 6722044, 0, 'Point', '{"type":"Point","coordinates":[15.5498384,60.6330634]}', 0, 30, '2018-10-01T12:09:31+02:00', 'Riksantikvarieämbetet', '2026-11-17', '0be433606c28ae9289ee2b1e08203a40');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (286, '137914be-4213-4ddc-a00d-e8d761cb96f5', 'L2024:405', NULL, NULL, 'Kolningsanläggning', 'Övrig kulturhistorisk lämning', NULL, 'Kolbotten, rund, 14 m diam och intill 0,5 m h med kring kanterna gropar. Bevuxen med granar, granar och björkar.', 'Förhöjning i moränmark SV om bäck.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7277233, 15.2895177, 515792.6, 6732495.4, 515792, 6732495, 515793, 6732496, 0, 'Point', '{"type":"Point","coordinates":[15.2895177,60.7277233]}', 0, 30, '2024-02-08T16:49:18.118+01:00', 'länsstyrelsen', '2026-11-17', 'd9a5742c046818cf56cf1d34e25074b8');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (294, '141f112a-d107-4d4b-8d5d-b0109c6481ad', 'L2023:6352', NULL, NULL, 'Kvarn', 'Fornlämning', 'Redovisad på kartor från år 1819, 1827 samt 1828.', 'Kvarnlämning, inom ett område av ca 30 x 5-25 m (NNV-SSÖ), bestående av 1 dammvall och 1 kvarngrund 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (295, '1422965a-16c6-4ca0-a7ff-63579b2f2968', 'L2023:6275', NULL, NULL, 'Färdväg', 'Fornlämning', 'Del av färdväg synlig på karta från år 1819.', 'Färdväg bestående av vägbank, ca 25 m l (N-S), 3 m br och intill 0,4 m h av 0,1-0,6 m st stenar, övertorvade. Stenarna delvis synliga utmed V sidan. Går över ett blötare parti av terrängen.', 'Småkuperad moränmark. Skogsmark (blandskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7507828, 15.3378303, 518414.8, 6735076.3, 518413, 6735064, 518416, 6735088, 0, 'LineString', '{"type":"LineString","coordinates":[[15.3378362,60.7506777],[15.3378247,60.750884],[15.3378165,60.7508839]]}', 0, 20, '2023-10-30T11:06:44.578+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', '091f9a1031a2082a73165d900c2f5635');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (296, '14319a29-209f-4355-91df-e6b3884fc7a0', 'L2000:8907', 'Stora Kopparberg 83:1', 'stora kopparberg 83:1', 'Brott/täkt', 'Övrig kulturhistorisk lämning', NULL, 'Område med kalkbrytning, ca 60x20 m (ÖNÖ-VSV), bestående av 1 kalkbrott, ett par skärpningar och smärre skrotstensvarp. Kalkbrottet är avlångt, ca 10x3-4 m (VNV-ÖSÖ) och ca 1,5-2 m dj till vattenytan. Omkring brottet är smärre varp av delvis kalkhaltig sten. I områdets ÖNÖ del är ett par skärpningar.
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (300, '14916af3-d4ef-406a-87a4-77455e01224f', 'L2024:795', NULL, NULL, 'Färdväg', 'Fornlämning', 'Del av gamla färdvägen mellan Finnbo och Marnäs.', 'Färdväg, 100 m l, 1,2 m br och intill 0,3 m  h, delvis uppbyggd vägbank, delvis eroderad stig. Ska enligt uppgift av ortsbor i Finnbo ha använts vid transporter mellan Sörskogs gruvor, Finnbo och Marnäs. Använd både av malmforor och för andra kommunikationer.', 'Kuperad moränmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.8351737, 15.5398347, 529348.3, 6744549.2, 529309, 6744521, 529390, 6744572, 0, 'LineString', '{"type":"LineString","coordinates":[[15.5405601,60.8353675],[15.5405887,60.8353723],[15.5402971,60.8353342],[15.5398233,60.8352355],[15.5397321,60.8351683],[15.5395571,60.8350362],[15.5391683,60.8349316],[15.53911,60.8349239]]}', 0, 25, '2024-03-15T11:48:23.103+01:00', 'länsstyrelsen', '2026-11-17', '9e501aeb7f237be8eab74ad99b1b0a5a');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (301, '149ff34b-d908-4d90-bd22-16bc44ae91ae', 'L1998:2531', 'Stora Kopparberg 596', 'stora kopparberg 596', 'Fossil åker', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fossil åker, oregelbunden, ca 40x8-15 m (NV-SÖ) st. Avgränsad mot omgivande mark av ett svagt hak i NÖ och vägbank i SV. Lämningen tangerar en odlingsyta på 1690 års karta (RAÄ dnr 321-4220-2009).', 'Flack sank moränmark. Skogsmark, tät blandskog.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6689985, 15.5408454, 529555.7, 6726041.4, 529535, 6726026, 529569, 6726052, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5407774,60.6690789],[15.5404697,60.6690937],[15.5410296,60.6688639],[15.5410812,60.6689437],[15.54101,60.6690272],[15.5407774,60.6690789]]]}', 0, 10, '2018-10-01T12:19:54+02:00', 'Riksantikvarieämbetet', '2026-11-17', '25374f48d1c86673fe8220de8f840457');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (311, '15702aaa-9279-49ff-a87b-66ada7baf03c', 'L2023:7052', NULL, NULL, 'Husgrund, historisk tid', 'Fornlämning', 'Ger ett ålderdomligt intryck. Kan möjligen kopplas till intilliggande gruvområde, alternativt äldre fäbodbruk eller gårdstomt. Ej med på storskifteskarta från år 1819 eller nyare studerade kartor.  Ligger inom Sörskogsgruvornas utmål. Äldsta skriftliga belägg för Sörskog är från år 1574.', 'Husgrund, kvadratisk, 5 x 5 m (NV-SÖ) och 0,3-0,6 m h. Spisröse  i NÖ hörnet, 1,5 x 1m och 0,4 m h. Övertorvad.', 'Småkuperad moränmark. Skogsmark (blandskog, avverkningsyta).', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.813234, 15.411367, 522379.5, 6742054.9, 522379, 6742054, 522380, 6742055, 0, 'Point', '{"type":"Point","coordinates":[15.411367,60.813234]}', 0, 25, '2023-11-11T16:51:05.646+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', 'ae8549fe03e5e6dbd970d5f4f0337357');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (320, '1635325a-aa02-4cbf-9402-a69a056b6154', 'L2001:1015', 'Bjursås 127:3', 'bjursås 127:3', 'Fäbod', 'Ingen antikvarisk bedömning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', '1) Fäbodlämning, 40x35 m st (NÖ-SV), bestående av 2 husgrunder, varav en stuggrundmed spisröse och en källargrund.70 m NÖ om nr 1 är:2) Fäbodlämning, 145x25-50 m st (NÖ-SV), bestående av 10 husgrunder, fördelade på tvåklungor med 5 i SV och 5 i NÖ. I SV finns två stuggrunder med spisröse. I NÖ är enstuggrund med spisröse och källargrop samt ytterligare en källargrund.5 m SÖ om NÖ delen av nr 2 och SÖ om väg är:3) Fäbodlämningar, uppgift om, där det år 1811 fanns 4 byggnader inom ett ca 70x20 m stområde (NÖ-SV), utan spår 1994. Grunderna är åtminstone delvis troligen förstörda elleröverlagrade i samband med vägbygge.Ca 65 m Ö om NÖ delen av nr 2 är:4) Fäbodlämningar, uppgift om, där det år 1811 fanns 1 byggnad, troligen en stuga och därförtroligen finns flera husgrunder. Ej eftersökta 1994.110 m NV om nr 4 är:5) Fäbodlämning, uppgift om, markerad med en stuga 1912 och två byggnader påEkonomiska kartan. Ej på kartan 1811.År 1811 markeras vid nr 1 en byggnad och vid nr 2 endast två byggnader, en i SVoch en iNÖ, trots att 10 grunder konstaterades.Uggelåsens fäbodar markeras på en karta år 1811, fäboden omtalas som gammal avForsslund. Namnet och två stugor markeras NV om vägen på Generalstabskartan 1912. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Krön av moränrygg (NÖ-SV) mellan mosse och tjärn. Skogsmark (högbarrskog. I NÖdelen av nr 2 är hög blandskog intill igenväxande åker).', 'Nr 2 är intill och NV om väg.', NULL, NULL, 'Uppgift om lämning, ej bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7186897, 15.4309063, 523511.6, 6731531.5, 523478, 6731507, 523541, 6731559, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.4312593,60.7186593],[15.4313798,60.7187437],[15.431438,60.7188209],[15.4314268,60.7188801],[15.4313717,60.7189159],[15.4312581,60.7189266],[15.431035,60.7188511],[15.4307754,60.7187773],[15.4305853,60.7187072],[15.4304244,60.7186407],[15.4302893,60.7185598],[15.4303738,60.7185133],[15.4304765,60.7184739],[15.4305863,60.7184847],[15.4307729,60.718519],[15.430985,60.7185819],[15.4311715,60.7186323],[15.4312593,60.7186593]]]}', 0, 10, '2018-10-01T09:36:54+02:00', 'Riksantikvarieämbetet', '2026-11-17', '139424a737772d5f66f288ee2a20443e');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (322, '1647f272-fe91-49aa-bb3e-850ab3a37278', 'L2001:2147', 'Bjursås 86:1', 'bjursås 86:1', 'Bytomt/gårdstomt', 'Fornlämning', 'Gården belagd på karta från 1819 (akt U3-8:1).', 'Gårdstomt, 30 x 31 m (N-S), bestående av grundstenar efter ett boningshus. Gårdstomten belagd på karta från 1819 (U3-8:1).', NULL, NULL, 'Enligt traditionen i byn, ska den första inbyggaren ha varit en finsk kvinna, Finn-Gertrud,vars man var ute i krig. En annan finsk kvinna, Sturna Karin, skaha slagit sig ner påSturnaberget, se RAÄ-nr 943 i Leksands socken.Uppgift från bl.a. Ulla Ollsson, Bacjenalus, ca 70 år.Skiss i inventeringshandlingarna.', NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.8352259, 15.5273175, 528667.8, 6744549.5, 528651, 6744532, 528683, 6744565, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5270279,60.8353608],[15.5275947,60.8353586],[15.5275733,60.8350698],[15.5270487,60.8351085],[15.5270279,60.8353608]]]}', 0, 10, '2024-03-13T17:22:03.709+01:00', 'länsstyrelsen', '2026-11-17', '9b4a46b6e9fcddaac0abe5e3f94b2133');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (324, '166d34c5-9e66-4677-a8f5-c99408f5fd38', 'L2000:8912', 'Stora Kopparberg 165:1', 'stora kopparberg 165:1', 'Gränsmärke', 'Fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fredmilsröse, kvadratiskt, 2x2 m (NV-SÖ) och 0,3 m h, av stenar, 0,2-0,4 m. Visare, 0,5 m l (NÖ-SV), 0,4 m br och 0,1 m tj. Beväxt med mossa.', 'Svagt NNV-sluttande moränmark. Skogsmark (granskog).', '55 m ÖSÖ om ängshörn, 32 m NÖ om ängskant samt 30 m ÖNÖ om mindre ängshörn.', 'Fredsmilen kring Kopparbergs gruva.', 'Gullbergsröset', 'Bekräftad i fält', 'Åverkan', 'Ej undersökt', 'Synlig ovan mark', 60.6867113, 15.5285879, 528870, 6728008.8, 528870, 6728008, 528871, 6728009, 0, 'Point', '{"type":"Point","coordinates":[15.5285879,60.6867113]}', 0, 15, '2018-10-01T11:10:17+02:00', 'Riksantikvarieämbetet', '2026-11-17', '7cd11ed14b5a4b40226ca985139507bc');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (335, '174efc85-b475-4b64-b074-5ab066249a34', 'L2001:2194', 'Bjursås 5:1', 'bjursås 5:1', 'Vägmärke', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Kilometerstolpe, ej återfunnen.Beskriven vid inventeringen 1967: av gråsten, 0.4 m h, 0.5 m br vid basen och 0.2 m tj.På S sidan är texten:29.Anger avståndet i km från Leksand.Ej återfunnen 1994. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Måttligt S-sluttande moränmark. Skogsmark.', '15 m NNV om vägkant i kurva och omedelbart N om gammal väg.', NULL, NULL, 'Uppgift om lämning, ej bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7277823, 15.4000267, 521820.6, 6732533.6, 521820, 6732533, 521821, 6732534, 0, 'Point', '{"type":"Point","coordinates":[15.4000267,60.7277823]}', 0, 13, '2018-10-01T09:43:35+02:00', 'Riksantikvarieämbetet', '2026-11-17', '0bda6c73b089f35aab1243ea75e5cbd0');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (341, '178e4145-f3ac-4eb5-a1b9-4f2682ba21c0', 'L1998:121', 'Stora Kopparberg 562', 'stora kopparberg 562', 'Gränsmärke', 'Övrig kulturhistorisk lämning', NULL, 'Gränsröse, rund, 2 m diam och 0,7 m h. Kallmurat av 0,2-0,5 m st stenar. Hjärtsten, 0,9 m h, 0,3 m br (NV-SÖ) och 0,15 m tj. (RAÄ dnr 326-214-2005)', 'SÖ-sluttande moränmark med blockinslag. Skogsmark (tall och hygge).', 'I rågång.', NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6335752, 15.5480124, 529980.3, 6722099.4, 529980, 6722099, 529981, 6722100, 0, 'Point', '{"type":"Point","coordinates":[15.5480124,60.6335752]}', 0, 15, '2018-10-01T12:09:18+02:00', 'Riksantikvarieämbetet', '2026-11-17', '6125fe8c55e223f718a5a7fc846c8bdb');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (347, '17cda6fb-89c7-4eff-ab85-46a51ba8fee0', 'L2023:7042', NULL, NULL, 'Bytomt/gårdstomt', 'Fornlämning', 'Äldsta skriftliga belägg för Sörskog är från år 1574. Övergiven gårdstomt redovisad på karta från år 1819.
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (351, '17ffcff2-781d-476b-be46-b7d0cfd687d1', 'L2024:592', NULL, NULL, 'Fångstgrop', 'Fornlämning', NULL, 'Fångstgrop (?), rund, 1,4 m diam och 0,5 m dj, med kring kanten en vall, 1,5-2 m br och intill 0,2 m h. Bevuxen med granar och två tallar. Vid provstick framkom blekjordsskikt i vall och i botten sotigt lager.', 'Slutet av åsrygg (NV-SO) i sluttning mot SO.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.8664629, 15.6291739, 534171.8, 6748077.4, 534171, 6748077, 534172, 6748078, 0, 'Point', '{"type":"Point","coordinates":[15.6291739,60.8664629]}', 0, 30, '2024-02-27T15:42:12.822+01:00', 'länsstyrelsen', '2026-11-17', '73352e0b196609aae473319d6df159f7');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (353, '181de1df-cce5-49f7-9a97-189bfd41219c', 'L2001:2070', 'Bjursås 94:1', 'bjursås 94:1', 'Område med fossil åkermark', 'Övrig kulturhistorisk lämning', NULL, 'Område med fossil åkermark, bestående av 2 fossila åkrar och minst 4 röjningsrösen.  Åkerparcellen på Ö sidan av vattendraget är närmast blockformig, ca 25 x 15 m st (NNV-SSÖ), med intill 1 m h terrasskanter i S  och V.  
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (362, '18626243-2129-4eb2-b298-8f781d69c9c3', 'L1998:2664', 'Stora Kopparberg 586', 'stora kopparberg 586', 'Fossil åker', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fossil åker, oregelbunden, ca 55x18-30 m (N-S) st, avgränsad mot omgivande mark av hak i V och terrasskanter i S och Ö samt banvall i N. Odlingsytan finns med på 1690 års karta (RAÄ dnr 321-4220-2009).', 'Flack moränmark invid sjöstrand. Skogsmark, blandskog.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6705015, 15.5267679, 528785.1, 6726202.6, 528770, 6726172, 528815, 6726229, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5265011,60.6704265],[15.5264918,60.6702485],[15.52677,60.670232],[15.5269068,60.6704945],[15.5270102,60.6705949],[15.5273023,60.6707309],[15.5266487,60.6706933],[15.5265011,60.6704265]]]}', 0, 10, '2018-10-01T12:20:26+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'a3b55636b3e1189788ec7742f0558295');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (375, '19be5793-2266-4abe-b1d0-9a867f6a4be2', 'L2000:1941', 'Leksand 892:2', 'leksand 892:2', 'Dike/ränna', 'Fornlämning', 'Järnmalmsfyndigheten vid Sörskogsgruvorna, till vilket detta skrådike tillhör, ska ha upptäckts år 1842 (tillkommit före år 1850).  Brytningen ska ha utförts genom krutsprängning (forna tiders bruk). Gruvan lades ned år 1873 (varaktigt övergiven).', 'Skrådike, ca 800 m l (NNV-SSÖ), 1-2 m br och 0.5-1 m dj. På Ö sidan vall, 1-2 m br och 0.5-1 m h. Skrådiket övergår i SSÖ i ett vanligt dike i myr och slutar i NNV i en mindre damm. Från dammen torde vattnet ha letts ner till hjulgraven (L2000:1942/Leksand 892:1) via enträränna. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'N-sluttning av bergs- och moränhöjd. Skogsmark och hygge.', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.8143527, 15.41737, 522705.3, 6742181.6, 522478, 6741818, 522933, 6742580, 0, 'LineString', '{"type":"LineString","coordinates":[[15.413241,60.8179409],[15.4133938,60.8179404],[15.4134016,60.8178722],[15.4135789,60.8177416],[15.413825,60.8175383],[15.4141189,60.8173094],[15.4143077,60.8170637],[15.4145886,60.8168432],[15.4147946,60.816574],[15.4152028,60.8160804],[15.4152763,60.816029],[15.4151506,60.8157566],[15.4154934,60.8156042],[15.415479,60.8154998],[15.4157074,60.8152817],[15.4158746,60.8150467],[15.4160904,60.8148606],[15.4162917,60.8145722],[15.4167616,60.8141231],[15.4168646,60.8139907],[15.4171544,60.8137937],[15.417315,60.8137249],[15.41737,60.8135926],[15.4178575,60.8133949],[15.4181169,60.8131819],[15.4184425,60.8130576],[15.4187614,60.8129301],[15.4190327,60.8128226],[15.4195148,60.8126679],[15.4198551,60.8126236],[15.4202159,60.8125758],[15.4208087,60.812544],[15.4210409,60.8125732],[15.4211634,60.8125595],[15.4214201,60.8123789],[15.4215115,60.8120655],[15.4214949,60.8118458],[15.4211966,60.8114537],[15.4210368,60.8112277],[15.4210758,60.8110811]]}', 0, 10, '2023-11-11T16:07:58.683+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', '04e4243995cbc56338404096b7726a10');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (379, '19e3b03f-0ef1-43ad-8a5a-576de2eb6980', 'L2023:6898', NULL, NULL, 'Fäbod', 'Fornlämning', 'Tillhör fäboden Vatta med belägg före år 1850. Husgrunden är med på en karta från år 1824. Sista fäbodbruk ska ha varit år 1900.', 'Fäbodlämning, bestående 1 husgrund, rektangulär 12 x 5 m (N - S) och 0,2 m h.  Synlig som en förhöjning med i NO ett spismursröse av rösugnstyp, kvadratisk 2 x 2 m och intill 0,5 m h av 0,2-0,6 m st stenar. I S är en källargrop 3 m diam och 0,5 m djup.', 'S-sluttande moränmark av bergshöjd. Skogsmark (barrskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Åverkan', 'Ej undersökt', 'Synlig ovan mark', 60.8301002, 15.4866303, 526460.1, 6743961.5, 526460, 6743961, 526461, 6743962, 0, 'Point', '{"type":"Point","coordinates":[15.4866303,60.8301002]}', 0, 25, '2023-11-09T15:40:40.670+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', 'a3711cd7cdc62e94e9e850ed350e7e11');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (382, '1a02c2aa-851f-4be7-ae78-82b443736ac1', 'L2023:6760', NULL, NULL, 'Kvarn', 'Ingen antikvarisk bedömning', NULL, 'Uppgift om kvarnplats. Enligt storskifteskarta från år 1819 har det på platsen funnits en kvarnplats. Vid platsbesök iakttogs inga lämningar, tydliga spår, på platsen.', 'Åsänka i kuperad moränmark. Skogsmark.', NULL, NULL, NULL, 'Uppgift om lämning, ej bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7453056, 15.3688926, 520111.3, 6734475.4, 520111, 6734475, 520112, 6734476, 0, 'Point', '{"type":"Point","coordinates":[15.3688926,60.7453056]}', 0, 30, '2023-11-08T13:07:30.249+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', '122409d525a0544f125e04eb23c0d8a7');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (386, '1a2c94f2-8471-45fe-b0c8-632f2fdd9173', 'L2000:1580', 'Leksand 852:1', 'leksand 852:1', 'Fäbod', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fäbodställe, ej övergivet. Ej avgränsat. Markeringen hänför sigtill en godtycklig plats inom fäbodstället Långrö. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', NULL, NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7434791, 15.2225744, 512135.1, 6734236, 512135, 6734235, 512136, 6734236, 0, 'Point', '{"type":"Point","coordinates":[15.2225744,60.7434791]}', 0, 30, '2018-10-01T10:32:57+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'ad2dde93c999e0b25ca4ea6f389498b6');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (393, '1ad90c81-e136-43e7-95de-fbcbbd55a26d', 'L2001:2211', 'Bjursås 42:1', 'bjursås 42:1', 'Källa med tradition', 'Övrig kulturhistorisk lämning', NULL, 'Trefaldighetskälla? rektangulär, 1,5 x 0,7 m st, igenväxt med stillastående vatten, troligt utlopp åt N. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (403, '1ba3b446-e8eb-4806-9483-1a9b8a917c6a', 'L2023:5700', NULL, NULL, 'Småindustriområde', 'Fornlämning', 'Förekommer på karta från år 1827 samt 1828. Vissa delar kan vara mer sentida än andra, då det förekommer murbruk vid husgrunden.', 'Småindustriområde, ca 80 x 20-30 m st (NNV-SSÖ) bestående av minst 3 dammvallar, 1 kvarngrund samt 1 ränna.
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (408, '1c4227eb-a932-4a1f-9a06-17ec4c946a4a', 'L2024:796', NULL, NULL, 'Färdväg', 'Fornlämning', 'Gamla färdvägen Sörskogs gruvor-Finnbo-Marnäs.', 'Färdväg, 88 m l, 1,2 m br och intill 0,3 m h, delvis uppbyggd vägbank, delvis eroderad stig. Ska enligt uppgift av ortsbor ha använts vid transporter mellan Sörskogs gruvor, Finnbo och Marnäs.', 'Flack NO-sluttande moränmark', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.8356747, 15.5418542, 529457.7, 6744605.9, 529421, 6744581, 529487, 6744637, 0, 'LineString', '{"type":"LineString","coordinates":[[15.5423907,60.8359321],[15.5423805,60.8359457],[15.5419583,60.835659],[15.541915,60.8356485],[15.5411903,60.8354594]]}', 0, 25, '2024-03-15T13:20:37.870+01:00', 'länsstyrelsen', '2026-11-17', '204b8480f0e7d10ae80916b431790ab2');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (409, '1c70cc0a-429a-4344-9a20-036629ad42d1', 'L2024:3210', NULL, NULL, 'Stridsvärn', 'Fornlämning', 'Strategiskt läge i förhållande till Dalkarlsvägen vilken har medeltida anor.', 'Skyttevärn, ca 25x10 m (NNÖ-SSV). Skyttevärnet består av minst tre värn med kallmurade bås och gångar av ca 0,2-1 m stora stenar. Stenarna är täckta med mycket lav.   Båsen är delvis uppbyggda mot markfasta block. Det största båset är kvadratiskt ca 3x3 m stort och 1,6 m h. Ena sidan utgörs av ett stort block med möjliga ristningar på. Inga spår av borrmärken, järn eller betong/cement eller andra recenta ingrepp noterades.', 'Krönläge i kuperad moränmark med talrika större block. Skogsmark, barrskog.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6500524, 15.5715218, 531250.4, 6723945.5, 531216, 6723900, 531282, 6723990, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5715683,60.6504434],[15.5711711,60.650382],[15.5709981,60.6502971],[15.5709013,60.6501778],[15.5709101,60.6499995],[15.5710215,60.6498716],[15.5711242,60.6498069],[15.5715378,60.6497264],[15.5718135,60.6496488],[15.5719015,60.649643],[15.5719613,60.6496592],[15.5720044,60.6496916],[15.5720489,60.6497843],[15.5720905,60.6499238],[15.5720858,60.6500406],[15.5719659,60.6502403],[15.5718552,60.650348],[15.5717285,60.6504123],[15.5715683,60.6504434]]]}', 0, 10, '2024-07-01T13:52:29.714+02:00', 'STIFTELSEN DALARNAS MUSEUM', '2026-11-17', '9876add7c3c642d5f5aeaca2334d3965');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (428, '1db15568-e38b-468c-b3ab-b3abc3851ef0', 'L1999:8480', 'Bjursås 143', 'bjursås 143', 'Område med skogsbrukslämningar', 'Fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Område med skogsbrukslämning, ca 30 m diam, bestående av en grund efter en kolarkoja och ett kolbottenområde med diffus utbredning, .
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (429, '1dbf6a99-fcb7-4716-b638-68ff3bbe3ec8', 'L2024:376', NULL, NULL, 'Boplats', 'Fornlämning', NULL, 'Boplats, oklar utsträckning. Inom angivet område, ca 16 x 3 m (NV-SO) påträffades på frameroderad sandstrand på sjöbotten vid lågvatten enstaka till rikligt med skärvsten, avgränsad av en koncentration i NV och en koncentration i SO. Delvis övervuxen i S av strandvegetation. Ca 50 m i NV fyndplats för trindyxa, i privat ägo, Sågmyra.', 'Sandstrand O om bäckutlopp i sjö.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7314767, 15.274751, 514985.4, 6732910, 514980, 6732904, 514992, 6732916, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.2746684,60.7315253],[15.2747377,60.7314972],[15.2748711,60.7314241],[15.2748482,60.7314262],[15.2746744,60.7314963],[15.2746684,60.7315253]]]}', 0, 10, '2024-02-05T11:40:51.709+01:00', 'länsstyrelsen', '2026-11-17', 'dd94999c98ac0afcdea64c47f865007f');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (434, '1e0927b6-f8f9-4cf3-b601-89f7b9e40a80', 'L2000:9193', 'Stora Kopparberg 215:2', 'stora kopparberg 215:2', 'Bytomt/gårdstomt', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', NULL, NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6545717, 15.5610668, 530674.5, 6724443.9, 530674, 6724443, 530675, 6724444, 0, 'Point', '{"type":"Point","coordinates":[15.5610668,60.6545717]}', 0, 30, '2018-10-01T11:11:41+02:00', 'Riksantikvarieämbetet', '2026-11-17', '7d9764c3cc97723ea7d8783a4be8b73a');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (439, '1e3ff49f-4efb-4ab2-8b14-57a01e072928', 'L2023:6857', NULL, NULL, 'Husgrund, historisk tid', 'Övrig kulturhistorisk lämning', NULL, 'Husgrund, rektangulär, 8 x 7 m (NÖ-SV) och 1,6 m h med kallmurade sidor. Ingång åt SÖ. Liknar jordkällare i sin karaktär men enligt informationsskylt på platsen kan den ha koppling till den skotillverkning som skett i Andersbo.', 'S-sluttande moränmark. Skogsmark (blandskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7799482, 15.3994484, 521753.7, 6738343.6, 521753, 6738343, 521754, 6738344, 0, 'Point', '{"type":"Point","coordinates":[15.3994484,60.7799482]}', 0, 25, '2023-11-09T13:03:29.208+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', '11e90998942dd2c9a2d5b120ff71dbe8');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (443, '1e774a2a-c1a0-429c-bb7d-58162456128f', 'L2001:2235', 'Bjursås 50:1', 'bjursås 50:1', 'Fäbod', 'Fornlämning', NULL, '1) Fäbodlämning, 65x50 m st (N-S), bestående av 1 (-2) husgrunder, 1 ruin och 1brunn samt en raserad ladugård (N-S) med timmer och tegeltak.Stuggrunden, i V, är 7x5 m st (N-S) med spisröse vid mitten av V långsidan.2) Fäbodlämning, uppgift om, med en markerad stuga på karta från 1912, ej återfunnengrund 1994 och troligen bortschaktad vid vägbygge.Saknar äldre belägg. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Svagt Ö-sluttande morän- och sedimentmark. Skogsmark (igenväxandegläntor i högblandskog).', 'Stuggrunden är 17 m Ö om körväg (N-S).', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Ej synlig ovan mark', 60.706989, 15.4490332, 524509.6, 6730234.9, 524484, 6730202, 524534, 6730269, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.4494555,60.7071557],[15.4494425,60.7072311],[15.4494139,60.7072636],[15.4493374,60.7072838],[15.4492863,60.7072876],[15.4491947,60.7072881],[15.4489711,60.7072786],[15.4486738,60.7072425],[15.448629,60.7071998],[15.4486241,60.7071797],[15.4486164,60.7071279],[15.4485846,60.7070132],[15.4485747,60.7068965],[15.44858,60.7068067],[15.4486589,60.7067309],[15.4487244,60.7067126],[15.4488854,60.7067046],[15.4491087,60.7067016],[15.4493285,60.7067058],[15.4494134,60.7067394],[15.4494509,60.7067805],[15.4494682,60.7068989],[15.4494555,60.7071557]]]}', 0, 10, '2018-10-01T09:43:47+02:00', 'Riksantikvarieämbetet', '2026-11-17', '082722f978bcd515ff732c48164b16d1');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (451, '1f06092c-714b-42c0-9475-63c35b83a673', 'L2001:1819', 'Bjursås 130:1', 'bjursås 130:1', 'Hyttområde', 'Fornlämning', NULL, 'Hyttområde, 85x25-35 m st (NV-SÖ), bestående av 1 hyttruin(?), 1vattenränna, 1husgrund och 1 slaggförekomst.Hyttruinen(?), (22 m V om SV hörnet av kvarn) består av en oregelbunden kulle av sten,delvis sotig jord och tegel, 4 m diam och 1.7 m h, på en liten holme i bäcken.Vattenrännan, är 20 m l (NV-SÖ), 2 m br och 2 m dj, av kallmuradeblock. Den ärbelägen NÖ om bäcken, i vilken den mynnar. Vattenrännans NV ände är 8 m VSV omkvarnens SV hörn.Husgrunden, 10 m NV om bron, RAÄ-nr 129, på bäckens NÖ sida, ovanför ett vattenfall,är otydlig och ca 4x4 m st (NNV-SSÖ).Slaggförekomsten, är ca 70x10-30 m st (NV-SÖ), bestående av sparsamt till rikligt medkopparslagg, mellan hyttruinen och vattenfallet ovan bron. Uppe påplatån i Ö är slaggennärmast varpbildande, möjligen utgörande bottenrester av bortfördavarp. Även pågårdsplanen Ö om kvarnen, vid markeringen på kartan, finns slagg och grus blandat. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Svagt SÖ-sluttande, stenig bäckravin (NV-SÖ). Skogsmark (tät lövskog). Delvistomtmark.', 'Omedelbart SV om större kvarnbyggnad.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Ej synlig ovan mark', 60.7498568, 15.4809715, 526217.9, 6735021.8, 526175, 6734991, 526253, 6735051, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.4814354,60.7495828],[15.481534,60.7495995],[15.4815975,60.7497076],[15.4816131,60.7498261],[15.4815423,60.7498778],[15.4813507,60.7499198],[15.4811075,60.7499813],[15.4808495,60.7500408],[15.4805697,60.7500985],[15.4804191,60.7501138],[15.4802479,60.7500698],[15.4801979,60.7500121],[15.4801948,60.7499887],[15.4802653,60.7499514],[15.4804612,60.7498789],[15.4806643,60.7498119],[15.4809085,60.7497109],[15.4811117,60.7496367],[15.4812777,60.7495909],[15.4814354,60.7495828]]]}', 0, 10, '2018-10-01T09:41:29+02:00', 'Riksantikvarieämbetet', '2026-11-17', '261f664aec702ac69992309b1a15704c');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (452, '1f1d60c7-bb51-4e32-941f-4bd598f80cff', 'L2000:9262', 'Stora Kopparberg 14:1', 'stora kopparberg 14:1', 'Gränsmärke', 'Övrig kulturhistorisk lämning', NULL, 'Gränsröse 1.5-2 m diam ca 0.5 m h av 0.3-0.5 m st skarpkantigastenar. I mitten en 1.5 m h pinne. Övermossat och beväxt medblåbärsris. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Krön av större bergs- och moränrygg. skogsmark, (barrskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7437273, 15.5394301, 529410.1, 6734363.9, 529410, 6734363, 529411, 6734364, 0, 'Point', '{"type":"Point","coordinates":[15.5394301,60.7437273]}', 0, 15, '2018-10-01T11:12:02+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'c7901f950a52b68bebdcd9fab22f135b');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (454, '1f25e432-7c81-4244-9dec-777a2e1fe7ce', 'L2023:6866', NULL, NULL, 'Bytomt/gårdstomt', 'Fornlämning', 'Andersbo omnämns som nybygge 1563. 1588 fanns en hemmansägare. 1639 fanns sex hemmansägare. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (466, '1fedcd3c-57b7-43c9-abc0-88f5ccfd941b', 'L2024:514', NULL, NULL, 'Husgrund, historisk tid', 'Övrig kulturhistorisk lämning', NULL, 'Husgrund, ca 3 x 3,5 m, bestående av hoprasade väggar efter timrad byggnad (lada?), 0,3-1,5 m h med i NO en dörröppning ca 1 m h.', 'Flack moränmark på bergshöjd.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7224017, 15.3086376, 516838.4, 6731907.4, 516838, 6731907, 516839, 6731908, 0, 'Point', '{"type":"Point","coordinates":[15.3086376,60.7224017]}', 0, 30, '2024-02-16T10:35:59.907+01:00', 'länsstyrelsen', '2026-11-17', '6f1c2914162e8ca4b45f7842138f8781');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (472, '202cf715-4974-4392-ada2-e7be59883f7e', 'L2024:577', NULL, NULL, 'Husgrund, historisk tid', 'Möjlig fornlämning', 'Har sannolikt samband med den fossila åkermarken.', 'Husgrund (?), 6 x 6 m och intill 0,4 m h, synlig som en förhöjning med stenkant synlig i S och V.', 'Höglänt yta i SV-sluttande moränmark invid stig.', NULL, NULL, NULL, 'Bekräftad i fält', 'Åverkan', 'Ej undersökt', 'Synlig ovan mark', 60.7266918, 15.3137138, 517113, 6732386.5, 517113, 6732386, 517114, 6732387, 0, 'Point', '{"type":"Point","coordinates":[15.3137138,60.7266918]}', 0, 30, '2024-02-26T17:34:18.075+01:00', 'länsstyrelsen', '2026-11-17', '045fa612f627a3d49c9e6291e240c1ec');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (475, '20bf438e-f9bb-43ec-9392-172c3f11c534', 'L2000:2037', 'Leksand 948:1', 'leksand 948:1', 'Färdväg', 'Övrig kulturhistorisk lämning', NULL, 'Färdväg, annan, delar av, inom Leksands socken ca 8 350 m l. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (482, '2108eb7f-0f5d-4c73-b6fb-e48a3f4c11d8', 'L2024:1390', NULL, NULL, 'Kokgrop', 'Möjlig fornlämning', 'Vallen något ojämn.', 'Kokgrop (?), rund, 1,5 m diam och 0,3 m dj, omgiven av en ställvis ojämn vall, 1,4-2,0 m br och intill 0,3 m h. Vid provstick framkom sot och kännbar stenpackning. Två block ingår i vallen.', 'SO-sluttande moränmark i sydsluttning mot bäck.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.8696934, 15.4827196, 526215, 6748369.8, 526215, 6748369, 526216, 6748370, 0, 'Point', '{"type":"Point","coordinates":[15.4827196,60.8696934]}', 0, 15, '2024-04-22T18:13:05.403+02:00', 'länsstyrelsen', '2026-11-17', '3a70055ed748748adf2565988cb5a79d');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (487, '216fcaa7-a68e-4166-9c33-8a7198e8e5f4', 'L2001:2096', 'Bjursås 22:2', 'bjursås 22:2', 'Övrigt', 'Övrig kulturhistorisk lämning', NULL, 'Hyttområde,  ca 10x4 m (NV-SÖ), bestående av 1 slaggföreskomst vid en grund,stenig och tämligen bred bäck, vilken rinner ut från Rällsjön motNV. I bäcken och pådess NÖ sida, finns ganska talrikt med slagg på en ca 10 m l sträcka. Slaggstyckena är0.05-0.15 m st, mestadels blåsiga, flutna och mörka. Dessutom finns talrika gröna,glasaktiga bitar.Inga spår av hytta eller fördämning vid slaggförekomsten. Enligt fru Brita Larsson,Rällsjö, fanns det spår av en hyttpipa här förr.1994 intervjuades ånyo Rällsjö Brita Larsson, som uppgav att hyttpipan återfunnits närvägen i bäckravinen drogs om 1929. Hyttruinen låg sannolikt mellanvägen ochravinsidan, och förstördes troligen vid vägbygget.Mellan slaggförekomsten och RAÄ-nr 21 ligger:2) Grunden till en skinnstamp, 5x5 m st (NNV-SSÖ) och 1 m h, av 0.3-1 m st stenar ochblock. Hjulgrav i grundens V del, 1 m br och 1 m dj, med bevarad lagersten på V kanten,0.6x0.3 m st och 0.2 m h. På en sträcka av ca 500 m nedströms frånhyttplatsen finnsförutom en bevarad såg, lämningar efter nio fördämningar, flertalet sannolikt efterskvaltor.Fäbodinventeringen 1963 upptar två strömkvarnar i Rällsjöströmmen. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Bäckravin. Skogsmark (blandskog).', 'Ca 50 m NV om Rällsjö dammhus (bäckutflödet).', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7660007, 15.2862302, 515594.7, 6736757.9, 515594, 6736757, 515595, 6736758, 0, 'Point', '{"type":"Point","coordinates":[15.2862302,60.7660007]}', 0, 30, '2018-10-01T09:43:00+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'cf8aaf98c785d4ef7708a8d4bda8a6f8');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (513, '23117748-3681-443d-afe8-fcf9f2c8c4a2', 'L2023:5697', NULL, NULL, 'Kvarn', 'Fornlämning', 'Redovisad på karta från år 1827. Ligger inom by med äldsta belägg från år 1539.', 'Kvarnlämning, inom ett område av ca 35 x 20 m (VNV-ÖSÖ) bestående av 1 dammvall och 1 kvarngrund. Dammvallen är 15  m l (N–S), 1-2 m br och och intill 0,4-1  m h, av 0,3-1 m st stenar. Överväxt
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (519, '237a2c3c-2ebf-45d3-b574-a2efa345ae1b', 'L2001:1314', 'Bjursås 107:1', 'bjursås 107:1', 'Gruvområde', 'Fornlämning', 'Gruvan finns omnämnd på Hulphers karta från 1835 som den gamla gruvan (karta med utmål i Hembygdsföreningens ägo, Sågmyra).', 'Gruvområde, 60x50 m st (VNV-ÖSÖ), bestående av 1 gruvhål, 2skrotstenshögar och 1 husgrund. Skrotstenshögarna, är 25x20 m st(Ö-V) och 2 m h samt 20 m diam oc h 1 m h, båda skogbeväxta, detmindre är helt övertorvat. Husgrunden, är 7x5 m st (NNÖ-SSV) ochbelägen ovanpå den större sk rotstenshögens SV del och verkarmodern. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Svagt NÖ-sluttande moränmark. Skogsmark (blandskog).', 'Gruvhålet är 14 m NNÖ om väg och 4 m SV om körväg.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7135107, 15.2820233, 515390.6, 6730910.6, 515364, 6730880, 515422, 6730943, 0, 'GeometryCollection', '{"type":"GeometryCollection","geometries":[{"type":"LineString","coordinates":[[15.2819382,60.7133184],[15.2819267,60.7133434],[15.2819778,60.7133562],[15.282033,60.7133367],[15.2820299,60.7133098],[15.2819935,60.7132989],[15.2819568,60.7133023],[15.2819382,60.7133184]]},{"type":"Polygon","coordinates":[[[15.2817075,60.7133137],[15.2817665,60.7132907],[15.2818365,60.7132676],[15.2819504,60.7132484],[15.2820531,60.7132417],[15.2821298,60.7132528],[15.2822029,60.7132657],[15.282305,60.7132895],[15.2824251,60.7133295],[15.2825628,60.7134145],[15.2825908,60.7134828],[15.2825527,60.7135634],[15.2824308,60.7136203],[15.2822757,60.713686],[15.2821024,60.7137499],[15.2818891,60.7137956],[15.2817389,60.7137913],[15.2816483,60.7137424],[15.2815585,60.7136433],[15.2815424,60.7135248],[15.2815663,60.7134226],[15.2816742,60.7133297],[15.2817075,60.7133137]]]}]}', 0, 25, '2024-02-05T09:29:19.290+01:00', 'länsstyrelsen', '2026-11-17', 'e4b54ae54942a74d49e7e712daf6af61');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (541, '24cee906-6cae-4ccf-99a6-14e8eb8daa46', 'L2024:388', NULL, NULL, 'Härd', 'Fornlämning', NULL, 'Härd, oval, 1,2 x 0,6 m och 0,1 m h med kring kanten 6 synliga stenar och 3 kännbara stenar, 0,06-0,18 m stora. Övermossad. Vid provstick framkom 3 cm blekjord över kol. Bevuxen med lövsly.', 'SSV-sluttande moränmark 9 m NO om sjöstrand.', NULL, NULL, NULL, 'Bekräftad i fält', 'Åverkan', 'Ej undersökt', 'Synlig ovan mark', 60.7192933, 15.2824463, 515410.9, 6731554.7, 515410, 6731554, 515411, 6731555, 0, 'Point', '{"type":"Point","coordinates":[15.2824463,60.7192933]}', 0, 30, '2024-02-05T16:08:56.919+01:00', 'länsstyrelsen', '2026-11-17', 'e486ae7e84af1b213d7ad853af348827');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (542, '24ea9a7c-69e9-4ef8-9a47-31c37c81a45f', 'L2001:1709', 'Bjursås 80:2', 'bjursås 80:2', 'Fäbod', 'Ingen antikvarisk bedömning', NULL, 'Inga synliga lämningar påträffat inom området 2023. Se inventeringsbok för äldre beskrivning av område 2.', 'S-sluttning högt upp på bergs- och moränhöjd på N sidan av huvuddalgång. Skogsmark(blandskog samt hyggge).', NULL, NULL, NULL, 'Utgår på grund av felregistrering', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.8328464, 15.4591228, 524962.3, 6744256.6, 524857, 6744201, 525022, 6744340, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.4596735,60.8335931],[15.4596052,60.8335173],[15.4595044,60.8334127],[15.4593701,60.8333277],[15.4592433,60.8332391],[15.4591089,60.8331576],[15.4589161,60.8330579],[15.458748,60.8330069],[15.4585212,60.8329519],[15.4583233,60.8329204],[15.4580995,60.8328996],[15.4577398,60.8328746],[15.4571957,60.8328774],[15.4572451,60.8327968],[15.4573198,60.8327397],[15.4574571,60.8326775],[15.4575979,60.8326207],[15.4577937,60.8325713],[15.4579969,60.832522],[15.4583254,60.8324571],[15.4585431,60.8324169],[15.4588491,60.8323716],[15.4591763,60.8323714],[15.4594891,60.8323531],[15.4596579,60.8323701],[15.4597821,60.8324084],[15.4598842,60.8324484],[15.4599675,60.8325116],[15.4600685,60.8326037],[15.4601394,60.8327333],[15.4601662,60.8328627],[15.460221,60.8330605],[15.460213,60.8332742],[15.4601643,60.8335002],[15.4596735,60.8335931]]]}', 0, 10, '2023-11-12T08:05:52.229+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', 'c452db4e8f3cad36d13f72e89b70c60c');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (545, '24f5d145-55d2-4746-8e0a-a8289ca3b90e', 'L2001:872', 'Bjursås 106:1', 'bjursås 106:1', 'Gruvhål', 'Ingen antikvarisk bedömning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Gruvområde, bestående av 1 gruvhål.Gruvhål,  igenfyllt och beväxt med ung lövskog. Delvis ännu synligt stängsel.Gruvorna RAÄ-nr 106-108 kallades 1835 för Sågmyra kopparmalmsgruvor(Bjursåsgruvan). Ytterligare några små gruvhål ingick i gruvfältet. Okända 1994.Dessutom fanns en del nu försvunnen bebyggelse. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Svagt NÖ-sluttande moränmark. Skogsmark (mest lövskog).', 'Ca 15(?) m S om liten väg.', NULL, NULL, 'Uppgift om lämning, ej bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7144204, 15.2795405, 515254.7, 6731011.3, 515254, 6731011, 515255, 6731012, 0, 'Point', '{"type":"Point","coordinates":[15.2795405,60.7144204]}', 0, 30, '2018-10-01T09:36:04+02:00', 'Riksantikvarieämbetet', '2026-11-17', '35d2808d7b16c8e1c2fc3ba5e1a3f1a4');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (549, '256f8d24-7ad8-49f6-bf42-2975d2a7b35f', 'L2000:9740', 'Stora Kopparberg 136:1', 'stora kopparberg 136:1', 'Fångstgrop', 'Fornlämning', NULL, 'Fångstgrop, närmast rund, 2.5 m diam och ca 3.5 m dj. Gropen ärcylinderformad med kallmurad vägg, av 0.2-0.5 m st stenar.Gropen är omgiven av en jordvall, 2.5-3.5 m br och intill 0.3 mh. Gropens botten delvis fylld med ris. Bevuxen med en björk, enunggran samt ca 40 tallplantor. Tre stubbar.20 m SSÖ m fångstgropen är en husgrund, 5x5x4 m och 0.5 m h.Smedja 70 m SSÖ om fångstgropen är en mindre gruva, stenbrott?,inom markerat områdex, 5 m SV om den är en varphög. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Blockig moränmark på krön av liten, flack höjd. Skogsmark(Kalhygge).', '75 m ÖNÖ om åkerhörn och ca 75 m SÖ om åkerhörn.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6718104, 15.5909894, 532293.1, 6726378.2, 532293, 6726378, 532294, 6726379, 0, 'Point', '{"type":"Point","coordinates":[15.5909894,60.6718104]}', 0, 30, '2018-10-01T11:16:11+02:00', 'Riksantikvarieämbetet', '2026-11-17', '1ce9cc840690578a306f16802bcc8c33');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (562, '25e4e0a7-7d91-4b84-bdad-ff6c892f4f69', 'L2024:452', NULL, NULL, 'Gruvområde', 'Möjlig fornlämning', 'Bedöms som "äldre" av SGU.', 'Gruvområde,71 x 48 m (ONO-VSV) bestående av två jordrymningar och fyra varphögar. Jordrymningarna är 1,5-1,6 m diam och 0,4-0,8 m dj, med kring kanten en vall0,5-2 m br och 0,15-0,5 m h.', 'SO-sluttande moränmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7316287, 15.3258819, 517774, 6732939.6, 517738, 6732917, 517809, 6732964, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.3257731,60.7318452],[15.3263163,60.7317891],[15.3265151,60.7316829],[15.3260648,60.7314295],[15.3252337,60.7314706],[15.3254918,60.731701],[15.3257092,60.7318454],[15.3257731,60.7318452]]]}', 0, 10, '2024-02-12T14:35:25.781+01:00', 'länsstyrelsen', '2026-11-17', '3d3cfd84a8e082fc69d900d682649e54');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (574, '268a422e-0f78-482b-b0ba-a4867f21d08a', 'L2001:2048', 'Bjursås 54:2', 'bjursås 54:2', 'Fäbod', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', '1) Fäbodlämning, 1050x50-400 m st (Ö-V). Utsträckning enligt LMV-karta från 1808.I områdets centrala och V del är två bebyggelseområden, varav detNÖ består av 2 stugor, 4ekonomibyggnader, 2 jordkällare samt 4 grunder efter ekonomibyggnader. 150 m SV om dettaär ett område med 4 stugor, 7 uthus och 1 grund efter ekonomibyggnader.Runt dessa områden är stenröjda ytor, odlingsrösen, stengärdesgårdar, åkerhak ochterrasskanter.Området används idag som fritidsbostäder. Någon byggnad är nyligenhitflyttad från  annanplats.30 m S om nr 1 är:2) Fäbodlämning, 140-170x30-120 m st (Ö-V). Utsträckning enligt LMV-karta från 1808,troligen bestående av rester efter 2 ekonomibyggnader.Vid omnumrering med därtill ändrad beskrivning för ADB, framkom inte klart huruvida derester som anges under nr 2 ligger där, eller inom nr 1.Namn enligt ekonomiska kartan. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'S-sluttning av berg. Skogsmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7700666, 15.5489143, 529902.6, 6737301.8, 529814, 6737239, 530001, 6737377, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5472927,60.7698539],[15.547363,60.7697016],[15.5475542,60.7695743],[15.5478479,60.7695243],[15.5482149,60.7695084],[15.5487945,60.7695445],[15.5492127,60.7696003],[15.5497816,60.7695576],[15.5503285,60.7695095],[15.5505706,60.7695203],[15.5506988,60.769585],[15.5506946,60.7697428],[15.5504227,60.7698735],[15.550231,60.7701173],[15.5501605,60.7703665],[15.5500317,60.7704883],[15.549877,60.7706335],[15.5496712,60.7707338],[15.5491501,60.7707282],[15.5486219,60.7706777],[15.5481157,60.7706111],[15.5478334,60.7705517],[15.5475733,60.7704117],[15.5474309,60.7702216],[15.5473144,60.7699615],[15.5472927,60.7698539]]]}', 0, 10, '2018-10-01T09:42:43+02:00', 'Riksantikvarieämbetet', '2026-11-17', '6fe1582b553bce5826b54c877014d809');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (576, '26bbc28a-081a-472c-84cd-144a8451cc66', 'L2001:2162', 'Bjursås 38:1', 'bjursås 38:1', 'Källa med tradition', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Trefaldighetskälla, 1 m diam och 0.2 m vattendjup. I kanterna ären del större stenar,0.5 m st, samt mindre stenar, 0.1-0.2 m st. Sandig botten. Avrinner mot NNV.Uppgift om källan har lämnats av Bränd Erik Mattsson, vars mor druckit trefaldighet ikällan. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Måttligt N-sluttande moränmark. Skogsmark (blandskog).', '22 m 80 gon om SÖ hörnet av liten åker och 40 m SSV om landsväg,samt 3 m N omstig (Ö-V).', 'Uppgiftslämnarens mor har druckit trefaldighet i källan.', NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7400061, 15.4197273, 522886.5, 6733901.8, 522886, 6733901, 522887, 6733902, 0, 'Point', '{"type":"Point","coordinates":[15.4197273,60.7400061]}', 0, 15, '2024-07-11T14:30:51.798+02:00', 'länsstyrelsen', '2026-11-17', '82a29a66c5165f911748bd5f196a7fb1');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (577, '26bc97a8-d523-4960-9f72-d5cd0f131324', 'L2023:6064', NULL, NULL, 'Område med skogsbrukslämningar', 'Övrig kulturhistorisk lämning', NULL, 'Område med skogsbrukslämningar, 30 x 25 m (V-Ö) bestående av 1 kolbotten efter resmila, 1 kolbotten, obestämbar samt 1husgrund efter kolarkoja. Kolbotten efter resmila, rund, 10 m diam och intill 0,4 m h med flack yta. 2 m V om denna är kolbotten, obestämbar, ca 10 m st och intill 0,6 m h med flack yta. NÖ om denna är husgrund efter kolarkoja, bestående av ett spisröse, ca 3 x 2 m (V-Ö) och 1 m h, övermossad med öppning åt N.', 'Fack och svagt kuperad stenig moränmark. Skogsmark (avverkningsyta)', NULL, NULL, NULL, 'Bekräftad i fält', 'Åverkan', 'Ej undersökt', 'Synlig ovan mark', 60.7533942, 15.3392273, 518489.4, 6735367.5, 518473, 6735356, 518505, 6735381, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.339513,60.7533738],[15.3394285,60.7532938],[15.3392767,60.7532921],[15.3390494,60.7533001],[15.3389618,60.7533572],[15.338944,60.7533963],[15.3390052,60.7534776],[15.3390679,60.7535065],[15.3392381,60.753501],[15.3393514,60.7534757],[15.3395136,60.7534437],[15.339513,60.7533738]]]}', 0, 5, '2023-10-24T11:13:58.648+02:00', 'Länsstyrelsen Dalarna', '2026-11-17', '828161b67eb24800b0e1cc7bc09082bb');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (579, '26d17e64-465a-43a1-8711-412386472f83', 'L2023:5686', NULL, NULL, 'Gruvhål', 'Fornlämning', 'Gråbergsvarp delvis överlagrad av röjningsröse tillhörande åker redovisad på 1819 års karta.
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (581, '27016e99-14f7-476c-b5a1-3ada793efec6', 'L2000:9901', 'Stora Kopparberg 438:1', 'stora kopparberg 438:1', 'Ristning, medeltid/historisk tid', 'Fornlämning', NULL, 'Minnessten bestående av ett stenblock, ca 0,7 m st, med inskriptionen 1841, NÖ-vänt placerad uppe på ett stort ovalt stenblock, ca 6x4 m (NV-SÖ) st och ca 2,6 m h (Dnr 326-2229-2008). - - Se Skannat dokument, Inventeringsbokuppslag under Referenser för uppgifter som har registrerats vid Fornminnesregistret före FMIS införande.', 'Flack sedimentmark. Skogsmark, f d åkermark (granskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6659848, 15.5020264, 527437, 6725688.9, 527436, 6725688, 527437, 6725689, 0, 'Point', '{"type":"Point","coordinates":[15.5020264,60.6659848]}', 0, 30, '2018-10-01T11:17:19+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'f25597e0d149e606738cf5c4a9651e94');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (586, '275d8a0d-ec55-40b6-af38-3a451b9ec054', 'L2023:7043', NULL, NULL, 'Bytomt/gårdstomt', 'Möjlig fornlämning', 'Ett kvarvarande uthus inom gårdstomten. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (603, '287a8a7c-d312-43a1-be85-ec0537705121', 'L2001:1318', 'Bjursås 108:1', 'bjursås 108:1', 'Gruvområde', 'Fornlämning', 'Gruvan utmärkt på Hulphers karta från 1835.', 'Gruvområde, 130 x 20-40 m (N-S) bestående av 3 gruvhål, 1 skärpning och 3 skrotstenshögar. Gruvhålen är från N 9 x 1-3 m (NO-SV) och 6 m dj, delvis vatten och skrotfyllt i botten på en större urgrävning; 15 m diam och 3-4 m dj; samt 11 x 7 m (NO-SV) och 4 m dj, skrotfyllt. Alla tre gruvhålen är inhägnade. Skärpningen är 4 m diam och 4 m dj, Skrotstenshögarna är 15-30 m diam och 1-2 m h.', 'Svagt N- och V-sluttande moränmark. Skogsmark (övervägande barrskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7126094, 15.2772549, 515130.8, 6730809.1, 515106, 6730747, 515149, 6730879, 0, 'GeometryCollection', '{"type":"GeometryCollection","geometries":[{"type":"LineString","coordinates":[[15.2771231,60.7128318],[15.2771735,60.7128805],[15.2772175,60.7128789],[15.2772472,60.7128539],[15.2772296,60.7128161],[15.2771748,60.7128105],[15.2771231,60.7128318]]},{"type":"LineString","coordinates":[[15.2771825,60.7125933],[15.2771632,60.7126453],[15.2771811,60.7126669],[15.2772363,60.7126528],[15.2772553,60.7126188],[15.2772337,60.7125954],[15.2771972,60.7125862],[15.2771825,60.7125933]]},{"type":"LineString","coordinates":[[15.2770906,60.712216],[15.2770718,60.7122392],[15.2771083,60.7122484],[15.2771854,60.712238],[15.2771784,60.7122236],[15.2771531,60.7122037],[15.2771092,60.7121981],[15.2770906,60.712216]]},{"type":"Polygon","coordinates":[[[15.2768315,60.7128917],[15.2775652,60.713232],[15.2775729,60.7131628],[15.2775711,60.7129512],[15.2775758,60.712528],[15.2775588,60.7124874],[15.2774256,60.712447],[15.2775321,60.7122758],[15.2775731,60.7122229],[15.2775807,60.7121415],[15.2772646,60.712077],[15.2770485,60.7120531],[15.2769574,60.7120817],[15.2769248,60.712155],[15.2769336,60.7122079],[15.2770361,60.7125454],[15.2770281,60.712578],[15.2768634,60.712737],[15.276806,60.7128226],[15.2768149,60.7128917],[15.2768315,60.7128917]]]}]}', 0, 25, '2024-02-28T11:10:57.986+01:00', 'länsstyrelsen', '2026-11-17', '721e06020b6272dc340e1e3c1c924a72');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (609, '28caf610-b570-4a36-9ac6-55113e9e94c5', 'L1998:2665', 'Stora Kopparberg 587', 'stora kopparberg 587', 'Fossil åker', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fossil åker, oregelbunden, ca 100x70 m (NÖ-SV) st.  I SV och SÖ avgränsad mot omgivande mark av röjningsrösen, ställvis murliknande. I NÖ avgränsad av dike och väg och i NV av hak och mindre röjningsrösen. Odlingsytan finns med på storskifteskartan (RAÄ dnr 321-4220-2009).', 'Svagt V-sluttande stenig morän. Skogsmark, gles barrskog med inslag av björk.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6770347, 15.5082462, 527767.4, 6726922.3, 527719, 6726882, 527819, 6726987, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5075374,60.676682],[15.5077909,60.6766838],[15.5082106,60.6767308],[15.5085978,60.6767397],[15.5089279,60.6768291],[15.509178,60.6769459],[15.5088855,60.6771076],[15.5087236,60.6776058],[15.5083595,60.6773747],[15.507652,60.6772281],[15.5076318,60.6771313],[15.5074754,60.6770388],[15.5073748,60.6770075],[15.5074026,60.6767934],[15.5075374,60.676682]]]}', 0, 10, '2018-10-01T12:20:27+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'f27c832b0fd797574e08935880e68e07');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (623, '298285fc-1f7d-42ca-b3c1-d3b0e60a3984', 'L2024:387', NULL, NULL, 'Härd', 'Möjlig fornlämning', 'Äldre typ av härd.', 'Beskrivning: Härd, oval, 1,4 x 0,7 m och 0,1 m h med kring kanten 5 synliga stenar, 0,07-0,18 m stora. Övermossad. Vid provstick framkom sot och kol. Bevuxen med lövsly. Inget blekjordsskikt, men kan vara borteroderat i stigen.', 'SSV-sluttning 9 m NO om sjöstrand.', NULL, NULL, NULL, 'Bekräftad i fält', 'Åverkan', 'Ej undersökt', 'Synlig ovan mark', 60.7193283, 15.2824328, 515410.2, 6731558.6, 515410, 6731558, 515411, 6731559, 0, 'Point', '{"type":"Point","coordinates":[15.2824328,60.7193283]}', 0, 30, '2024-02-05T16:40:19.272+01:00', 'länsstyrelsen', '2026-11-17', '47d218939e93b04a62096ba1dea6957e');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (628, '29d6378a-f7eb-462b-9d07-a54891380b7d', 'L2024:785', NULL, NULL, 'Färdväg', 'Fornlämning', 'Utgör del av den gamla vägen från Finnbo till sockenkyrkan i Bjursås.', 'Färdväg, del av, L 26,9 m, B 0,4 m. Färdvägen utgör en del av den gamla färdvägen mellan Finnbo och Bjursås.', 'Flack morän- och sedimentmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.8301416, 15.5335628, 529011.9, 6743985.9, 529008, 6743973, 529014, 6744000, 0, 'LineString', '{"type":"LineString","coordinates":[[15.5335032,60.8300273],[15.5335036,60.8300275],[15.5335596,60.8300775],[15.5335855,60.8302612]]}', 0, 25, '2024-03-15T09:18:07.061+01:00', 'länsstyrelsen', '2026-11-17', '2679aa109510f77a2f7ccd10ece08168');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (634, '2a4050c8-3a59-46da-a016-fac0e47eb941', 'L2000:8272', 'Stora Kopparberg 82:1', 'stora kopparberg 82:1', 'Småindustriområde', 'Fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Område med kalkbrytning, ca 65x55 m (Ö-V), bestående av 2kalkbrott & kalkugnsruin.Kalkbrott, oregelbundet & svåravgränsat, ca 28x18 m (ÖNÖ-VSV),intill 6 m dj. I brottet är nedrasad sten, vindfällen mm.Kraftigt beväxt med löv- och barrträd samt sly. Från brottets Ödel löper ett dike mot Ö.Ca 2 m S om N kanten av kalkbrottet & ca 20 m Ö om väg är:Klakugnsruin, kvadratisk, 4 m i sida (N-S), ca 1.0 -2.4 m h, av0.2-1.2 m st delvis huggna stenar i kallmur samt sandfodrad.Delvis utrasad åt S. Inga synliga öppningshål. Beväxt med 2större tallar.Ca 5 m ÖNÖ om väg (NNV-SSÖ) är:Kalkbrott, oregelbundet avlångt, ca 10x4 m (Ö-V), ca 1.8-2.5 m djtill vattenytan.Inom området är ställvis smärre varp och högar av ofyndig sten. IV delen det största kalkbrottet har sen tid dumpats bark(sågverksavfall).Området finns utmärkt på LMV Gävle, akt U/22 6:1, 1772 ochomtalas där som Kalek Grufva. Längs i S är en kojruin medspridmursröse. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'ÖSÖ-sluttning nära bergskrön, blockig moränmark. Skogsmark,(barrskog med inslag av lövträd och -sly).', 'Kalkbrottet är ca 8 m Ö om väg (N-S) och ca 20 m S ombeståndsgräns.', NULL, 'Kalkgruvan', 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6799317, 15.5910506, 532288.3, 6727282.8, 532260, 6727244, 532323, 6727311, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5905455,60.680103],[15.5905542,60.6800064],[15.5905676,60.6797996],[15.5906141,60.6797602],[15.5907008,60.6797042],[15.5907935,60.679664],[15.5909647,60.6795884],[15.5911049,60.6796168],[15.5912399,60.6797123],[15.5914081,60.6798235],[15.5914863,60.6798776],[15.5916491,60.6799781],[15.5916819,60.6800409],[15.5916306,60.6800982],[15.5915281,60.6801464],[15.5912427,60.6801781],[15.5909501,60.6801739],[15.5906685,60.6801501],[15.5905455,60.680103]]]}', 0, 10, '2018-10-01T11:07:03+02:00', 'Riksantikvarieämbetet', '2026-11-17', '1b9aee4f39b375f3b1e6e236eafb3867');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (636, '2a5dbed4-237e-4b7d-8e80-10d621dc8db7', 'L2000:9659', 'Stora Kopparberg 244:1', 'stora kopparberg 244:1', 'Bytomt/gårdstomt', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', NULL, NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6801058, 15.5639854, 530809.6, 6727289.1, 530809, 6727289, 530810, 6727290, 0, 'Point', '{"type":"Point","coordinates":[15.5639854,60.6801058]}', 0, 30, '2018-10-01T11:15:15+02:00', 'Riksantikvarieämbetet', '2026-11-17', '724678332c3fb3b22538f2018a6699c4');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (640, '2a8287b3-afab-49a0-bbf5-e4139aea4a1d', 'L1999:677', 'Stora Kopparberg 233:1', 'stora kopparberg 233:1', 'Bytomt/gårdstomt', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Gårdstomt. Ej avgränsad då äldre kartunderlag saknas. X-markeringen på FMR:s registerkarta hänför sig till sannolikt läge för äldre bebyggelse. Enligt kartor från 1690 och 1807 fanns ca 1 gård. Idag är 1 gård i anslutning till detta läge. Äldsta belägg: smidsarffvet 1432, DD1.', NULL, NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6679482, 15.5414374, 529589.1, 6725924.7, 529589, 6725924, 529590, 6725925, 0, 'Point', '{"type":"Point","coordinates":[15.5414374,60.6679482]}', 0, 30, '2018-10-01T11:22:26+02:00', 'Riksantikvarieämbetet', '2026-11-17', '2c93ca1973a6f27c6a220b9b9bb3684a');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (665, '2c3d9aec-b44b-4e10-a17e-a0ba5ff58614', 'L1998:2559', 'Stora Kopparberg 604', 'stora kopparberg 604', 'Gruvhål', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Gruvhål? 3x2 m (Ö-V) och minst 2,5 m dj. Med brädklädda sidor, liggande brädor på långsidorna och Ö kortsidan, stående i V.  Ligger i anslutning till odlingsyta i SSÖ (RAÄ dnr 321-4220-2009).', NULL, NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6783886, 15.5084317, 527776.4, 6727073.1, 527776, 6727073, 527777, 6727074, 0, 'Point', '{"type":"Point","coordinates":[15.5084317,60.6783886]}', 0, 30, '2018-10-01T12:20:03+02:00', 'Riksantikvarieämbetet', '2026-11-17', '5afc110352ed68df3b9e773de557baec');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (667, '2c458eb5-2b64-4f31-bb3b-eeb762bc4d55', 'L2023:7040', NULL, NULL, 'Bytomt/gårdstomt', 'Fornlämning', 'Äldsta skriftliga belägg för Sörskog är från år 1574. Övergiven gårdstomt redovisad på karta från år 1819.
