INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (699, '2eb3d829-2648-4cae-bc59-10678c1e55d2', 'L2024:530', NULL, NULL, 'Förvaringsanläggning', 'Möjlig fornlämning', 'Fångstgropsliknande men vallen ställvis otydlig och inte tydligt blekjordsskikt.', 'Förvaringsgrop (?), rund, 2 m diam och 0,3 m dj, omgiven av en vall, ställvis otydlig, 1-2 m br och intill 0,15 m h.', 'V-sluttning av kulle på krön av bergshöjd i moränmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7239183, 15.3147279, 517169.8, 6732077.9, 517169, 6732077, 517170, 6732078, 0, 'Point', '{"type":"Point","coordinates":[15.3147279,60.7239183]}', 0, 20, '2024-02-16T15:30:00.783+01:00', 'länsstyrelsen', '2026-11-17', '7a49a2b7013334874d497d1d91713dae');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (710, '2f9f6448-998f-44d9-b531-50239b4b3936', 'L1999:117', 'Stora Kopparberg 193:1', 'stora kopparberg 193:1', 'Gruvområde', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Gruvområde, cas 22x16 m (Ö-V), bestående av 1 gruvhål (igenfyllt)samt 1 skrotstensvarp.Gruvhål, nyligen igenfyllt med jord, skrotsten samt störrestenblock. Ö-S-V om det igenfyllda gruvhålet är ettskrotstenvarp, halvcirkelformat, 11 m i radie, 2-6 m br, intill1 m h. Magnetitförande. Övermossat samt skadat i Ö delen. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'S-sluttning av blockig moränhöjd. Skogsmark (tät, ung tallskog).', 'Omedelbart S om körväg (Ö-V).', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6691605, 15.5883384, 532150.9, 6726081.8, 532150, 6726081, 532151, 6726082, 0, 'Point', '{"type":"Point","coordinates":[15.5883384,60.6691605]}', 0, 30, '2018-10-01T11:19:11+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'df20004a805cee63ca1c37c3f24506bc');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (717, '30041fc2-5df0-4978-90aa-6a894c3bf01b', 'L2025:6119', NULL, NULL, 'Röjningsröse', 'Övrig kulturhistorisk lämning', NULL, 'Röjningsrösen, runda till ovala, 2-5 m diam intill 0,5 m h. Röjningsrösena är sju till antalet och är belägna i och invid åker som är i bruk.', 'Odlingsmark', NULL, NULL, NULL, 'Bekräftad i fält', 'Åverkan', 'Ej undersökt', 'Synlig ovan mark', 60.7425855, 15.4557312, 524847.7, 6734202.1, 524792, 6734126, 524906, 6734303, 0, 'MultiPoint', '{"type":"MultiPoint","coordinates":[[15.4550652,60.7434924],[15.4551377,60.7430419],[15.4547194,60.742262],[15.456794,60.7426472],[15.4564091,60.7419057],[15.4562617,60.7421635]]}', 0, 30, '2025-11-07T12:57:46.931+01:00', 'STIFTELSEN DALARNAS MUSEUM', '2026-11-17', '2514f32870e2ca1b00cd8e2dd8cd57ca');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (720, '30357406-b5ad-4c62-9cff-10d35390a799', 'L2001:1845', 'Bjursås 4:1', 'bjursås 4:1', 'Gränsmärke', 'Fornlämning', 'Gränsstenen är kopplad till en äldre sockengräns som är övergiven och inte längre brukas, men ligger i en annan gräns (fastighetsgräns) med ett annat syfte. Kan därmed bedömas vara övergiven. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (732, '3154e248-4919-4b2a-a309-14aca6cc1fa4', 'L2024:604', NULL, NULL, 'Kolningsanläggning', 'Övrig kulturhistorisk lämning', NULL, 'Kolbotten, oregelbunden, 15 m diam och intill 0,6 m h. Bevuxen med granar, tallar och lövsly.', 'NNV-sluttande moränmark på höjdsträckning.', NULL, NULL, NULL, 'Bekräftad i fält', 'Åverkan', 'Ej undersökt', 'Synlig ovan mark', 60.8720799, 15.61547, 533421.7, 6748696, 533421, 6748695, 533422, 6748696, 0, 'Point', '{"type":"Point","coordinates":[15.61547,60.8720799]}', 0, 30, '2024-02-27T16:23:13.934+01:00', 'länsstyrelsen', '2026-11-17', 'b081685ef697b0fd55952b9385112d52');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (738, '31884735-5833-43f5-8f75-3febff959ada', 'L2001:2099', 'Bjursås 90:1', 'bjursås 90:1', 'Gruvområde', 'Fornlämning', NULL, 'Gruvområde, 30x20 m st (N-S), bestående av 1 gruvhål och 1vägramp. Gruvhålet, i bergssiden, är 4 m diam och 0.5-2 m djtill vattenyta n. Grunt, snarast en skärpning, men ger ettålderdomligt intryck. Släta, schaktväggar. Vägrampen, är ca 20 ml (NÖ-SV), 3 m br och intill 1.5 m h, brant sluttande, avskrosten. Leder upp till gruvan från SV. Skiss iinventeringshandlingarna. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'NÖ kanten av ravin (NÖ-SV), i själva bergssidan. Nedanför är blockmorän. Glesskogsmark, (blandskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7697131, 15.2791952, 515209.7, 6737169.7, 515197, 6737155, 515224, 6737184, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.2791478,60.769581],[15.2792069,60.769595],[15.2793289,60.7696282],[15.2794254,60.7696671],[15.279452,60.7697028],[15.2794384,60.7697424],[15.2794208,60.7697712],[15.2793079,60.7698025],[15.2791547,60.769834],[15.2790702,60.7698309],[15.2790184,60.7698133],[15.2789735,60.7697813],[15.2789799,60.7697472],[15.2790035,60.7696699],[15.2790459,60.7696086],[15.2790783,60.7695868],[15.2791478,60.769581]]]}', 0, 10, '2018-10-01T09:43:01+02:00', 'Riksantikvarieämbetet', '2026-11-17', '6f8c9710174f680c92c5e25c68d16668');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (768, '331e68fe-0dff-4af7-92cd-21b6f3a346b2', 'L1999:141', 'Stora Kopparberg 204:1', 'stora kopparberg 204:1', 'Bytomt/gårdstomt', 'Fornlämning', NULL, 'Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', NULL, NULL, NULL, 'Handskarvets gamla tomt', 'Bekräftad i fält', 'Okänd', 'Okänd', 'Ej synlig ovan mark', 60.6467138, 15.5634637, 530813, 6723569.8, 530768, 6723531, 530863, 6723609, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5629662,60.6466986],[15.5628457,60.6466553],[15.5626415,60.6465474],[15.5626416,60.6464954],[15.5628283,60.6464026],[15.5630184,60.646369],[15.5638251,60.6466252],[15.5639166,60.6465752],[15.5643764,60.6467519],[15.5638603,60.6470626],[15.5633967,60.6469021],[15.5632467,60.6469627],[15.5628453,60.6467916],[15.5629662,60.6466986]]]}', 0, 10, '2018-10-01T11:19:17+02:00', 'Riksantikvarieämbetet', '2026-11-17', '3d41b84ba2418d483e558bcbaaacc6c8');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (771, '333cc905-c455-40d2-b94e-551de7f8759b', 'L2023:6922', NULL, NULL, 'Kolningsanläggning', 'Övrig kulturhistorisk lämning', NULL, 'Kolbotten efter liggmila, rektangulär, 7,5 x 6 m (NV-SÖ) och 0,4 m h. Stybbgropar utmed sidorna, ca 0,5-2 m st och 0,2-0,5 m dj.', 'NV sluttande moränmark. Skogsmark (tallskog med frötallar).', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.8144384, 15.3650059, 519856.6, 6742174.2, 519856, 6742174, 519857, 6742175, 0, 'Point', '{"type":"Point","coordinates":[15.3650059,60.8144384]}', 0, 25, '2023-11-09T16:53:18.226+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', 'ea4e0de95ae472eafa3e16a64c46a607');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (776, '339c2126-cda4-4904-abd4-0a047262a505', 'L2001:1967', 'Bjursås 51:4', 'bjursås 51:4', 'Fäbod', 'Ingen antikvarisk bedömning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', '1) Fäbodlämning, 360x320 m st (N-S). Utsträckning enligt LMV-karta från 1808-11.Inom ett 120x120 m st område är rester av 1 stuga med spismursröse, 1 grund av enekonomibyggnad. 1 stuga och 9 ekonomibyggnader kvarstår liksom 1 jordkällare och 1 brunn.Inom tomtområdet finns 1 boningshus och 1 trösklada som uppförts senare.I det stenröjda området däromkring är ett 40-tal röjningsrösen, 5-10 m diam och 0.5-1.2 m h,samt stengärdesgårdar, diken, terrasskanter och åkerhak.10 m SSÖ om nr 1 är:2) Fäbodlämning, 750x50-300 m st (NNV-SSÖ). Utsträckning enligt LMV-karta från 1808-11. Inom området finns fem mindre bebyggelseområden, 30x30-100x40m st (NÖ-SV). Inomvarje bebyggelseområde har varit 1-2 stugor och 4-6 ekonomibyggnader. Totalt kvarstår 8ekonomihus och 2 stugor.30 m SV om nr 1 är:Fäbodlämning, 150x70 m st (NV-SÖ). Utsträckning enligt LMV-karta från 1808-11.70 m VSV om nr 2 är:4) Fäbodlämning 100x80 m st (NV-SÖ). Utsträckning enligt LMV-kartafrån 1808-11.Runt bebyggelseområdena är röjningsrösen, 3-12 m diam, 0.3-1 m h,samt diken, terrasskanteroch åkerhak. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'S-sluttande moränmark. Skogsmark (blandskog). F.d. vallområde.', NULL, NULL, NULL, 'Uppgift om lämning, ej bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7988661, 15.570889, 531071.8, 6740519.6, 531014, 6740474, 531123, 6740581, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5707272,60.798484],[15.5709395,60.7984594],[15.5712194,60.7984918],[15.5716098,60.7985432],[15.571809,60.7985815],[15.5718053,60.7987358],[15.5717016,60.798853],[15.5715544,60.7989938],[15.5712839,60.7991999],[15.5710247,60.7994149],[15.5707537,60.799291],[15.5703427,60.7991499],[15.5698297,60.798884],[15.5704273,60.7985378],[15.5707272,60.798484]]]}', 0, 10, '2018-10-01T09:42:16+02:00', 'Riksantikvarieämbetet', '2026-11-17', '45a807b8bfb4b7885bb3a9190e04ff15');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (780, '33df1c54-f48c-498b-860e-c9780e5f95af', 'L2024:488', NULL, NULL, 'Brott/täkt', 'Möjlig fornlämning', 'Har sannolikt koppling till de hyttor son funnits i närheten', 'Kvartsbrott (?). Inom angivet område, ca 3 m diam, ett delvis övermossat röse av brutna stenar och block helt eller delvis av kvarts.', 'SV-sluttande moränmark av bergshöjd.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7244269, 15.3181202, 517354.6, 6732135.4, 517354, 6732135, 517355, 6732136, 0, 'Point', '{"type":"Point","coordinates":[15.3181202,60.7244269]}', 0, 30, '2024-02-14T17:12:40.794+01:00', 'länsstyrelsen', '2026-11-17', 'e16f0a6bf486c02b3c4a21f73b8768d5');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (789, '35266b2e-685c-40b6-8be7-43a844eb77fb', 'L2001:2105', 'Bjursås 124:1', 'bjursås 124:1', 'Fyndplats', 'Övrig kulturhistorisk lämning', NULL, 'Fyndplats för tre små avslag(?) av vit kvarts på ovankanten av en0.5 m h, grusig,vanligen helt övertorvad strandbrink (NNV-SSÖ). Endast 2x1 m är ejövertorvad. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Liten, SV-exponerad moränudde i sjö. Skogsmark (barrskog).', '1 m NÖ om bryggfäste, 7 m NNÖ om vattenbryn.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7363251, 15.5248213, 528620.2, 6733533, 528620, 6733532, 528621, 6733533, 0, 'Point', '{"type":"Point","coordinates":[15.5248213,60.7363251]}', 0, 30, '2018-10-01T09:43:02+02:00', 'Riksantikvarieämbetet', '2026-11-17', '89cad71d045a14d36fceefedd33456ff');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (792, '352ee4b1-1aa3-4c48-8f74-216f0c6be304', 'L1999:8804', 'Stora Kopparberg 482', 'stora kopparberg 482', 'Gränsmärke', 'Fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fredsmilsröse, 1 m h, 2 m l (i VSV). Visare, 0,6 m l, 0,45 m br och 0,05 m tj. Har sannolikt senare fungerat som eldstad i kolarkoja.', 'Moränmark. Skogsmark.', NULL, 'Fredsmilen kring Kopparbergs gruva.', NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6905398, 15.5491834, 529991.3, 6728444.4, 529991, 6728444, 529992, 6728445, 0, 'Point', '{"type":"Point","coordinates":[15.5491834,60.6905398]}', 0, 15, '2018-10-01T12:03:07+02:00', 'Riksantikvarieämbetet', '2026-11-17', '8f50f5962026e310301a9acdf8b96539');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (797, '3576d37d-6697-4e0b-adce-a052389c636e', 'L1999:8405', 'Bjursås 141', 'bjursås 141', 'Fyndplats', 'Övrig kulturhistorisk lämning', NULL, 'Fyndplats för stenredskap yxa? av bergart. Detta är 13 cm l, 7 cm br och 1-3,5 cm tj, slipat på båda flatsidorna och avsmalnande mot ena kortsidan och ena långsidan. Redskapet påträffades på ca 0,3 m dj vid grävning för elledning 2007-08-24. Ca 2 m V om fyndplatsen påträffades ett kollager ca 2 m diam. Redskapet förvaras hos markägaren.', 'Svagt SV-sluttand moränmark mellan tjärn och sjö. Tomtmark, gräsmatta.', '1 m SÖ om ÖSÖ hörnet på garage och 8 m SV om byväg.', NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7355427, 15.4825275, 526314.4, 6733428.1, 526314, 6733428, 526315, 6733429, 0, 'Point', '{"type":"Point","coordinates":[15.4825275,60.7355427]}', 0, 30, '2018-10-01T12:01:21+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'b0e72aada22b6df04a1da91f5b24af1c');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (804, '35db9956-ef49-4c0d-948a-53d086fcf03d', 'L2024:482', NULL, NULL, 'Husgrund, historisk tid', 'Övrig kulturhistorisk lämning', NULL, 'Husgrund, 5 x 6 m och 0,15 m h av 0,2-0,4 m st stenar. I mitten är spismursröse med lämning efter ugn, murad av tegel och 0,3-0,6 m st stenar. Bevuxen med lövsly.', 'Krön av mindre moränförhöjning.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.722265, 15.319521, 517432.2, 6731895, 517432, 6731895, 517433, 6731896, 0, 'Point', '{"type":"Point","coordinates":[15.319521,60.722265]}', 0, 30, '2024-02-14T11:37:21.231+01:00', 'länsstyrelsen', '2026-11-17', '706e37661dc523187545b1a440c6ecc0');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (806, '35f51521-a7f3-4a97-8056-eef3e41ede93', 'L2001:662', 'Bjursås 70:1', 'bjursås 70:1', 'Boplats', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Boplats(?). Inom ett 20x10 m st (NV-SÖ) område förekommer måttligt med skärvstensamt enstaka avslag av kvarts. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Svag V-sluttning mot sjö. Åkermark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7901923, 15.5493083, 529905.3, 6739543.5, 529895, 6739535, 529917, 6739554, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5492447,60.7901226],[15.5494614,60.7901249],[15.5495141,60.7901856],[15.549489,60.790209],[15.5493724,60.7902474],[15.54923,60.7902805],[15.5491374,60.7902452],[15.5491392,60.7901627],[15.5492447,60.7901226]]]}', 0, 10, '2018-10-01T09:34:48+02:00', 'Riksantikvarieämbetet', '2026-11-17', '3b16935baa08a0adf2835c09f600dfff');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (811, '361ed780-5656-4fa1-a056-a81aa39681eb', 'L2001:799', 'Bjursås 9:1', 'bjursås 9:1', 'Vägmärke', 'Ingen antikvarisk bedömning', NULL, 'Kilometerstolpe, ej återfunnen 2023, beskriven vid inventeringen 1967: av gråsten, avslagen, i två delar. Den ena delen, lös, 0.2 m h, 0.3 m br och 0.1 m tj, med texten:22. Den andra delen, den nedre, är 0.4 m h, 0.35 m br och 0.2 m tj. Ingen del återfunnen 2023. Beskrivningen är inte kvalitetssäkrad. Se även Inventeringsbok.', 'Vägkant. Skogsmark.', 'Invid och V om vägkant på en punkt 5 m N om korsning med avtagsväg åt V.', NULL, NULL, 'Uppgift om lämning, ej bekräftad i fält', 'Okänd', 'Ej undersökt', 'Synlig ovan mark', 60.7589952, 15.4075485, 522209.3, 6736012.6, 522209, 6736012, 522210, 6736013, 0, 'Point', '{"type":"Point","coordinates":[15.4075485,60.7589952]}', 0, 13, '2023-11-06T16:09:56.246+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', '7a1a654d8947cf0920683ac5e631c25d');
