INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (819, '367b821a-1883-4dff-9114-28f38842d922', 'L2024:765', NULL, NULL, 'Färdväg', 'Möjlig fornlämning', 'Gamla färdvägen mellan Sörskog och Marnäs', 'Färdväg, 277 m lång och intill 0,4 m br. Del av den gamla färdvägen mellan Sörskogs gruvor och Marnäs.', 'SV-sluttande moränmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.8389234, 15.5223002, 528391.8, 6744959.1, 528326, 6744847, 528468, 6745079, 0, 'LineString', '{"type":"LineString","coordinates":[[15.5211226,60.8400023],[15.5211148,60.8400001],[15.5212327,60.8398995],[15.5215563,60.8395387],[15.521617,60.8393813],[15.5216823,60.8393297],[15.5227572,60.8385466],[15.522732,60.8384979],[15.5235542,60.838017],[15.5235349,60.8380145],[15.5236789,60.8379146]]}', 0, 25, '2024-03-12T16:59:29.896+01:00', 'länsstyrelsen', '2026-11-17', 'c7a33e03449a068e32bb7f8a5dfebe05');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (824, '36b17e2b-e48b-4e5a-b03a-4a4836927f02', 'L2001:2077', 'Bjursås 3:1', 'bjursås 3:1', 'Övrigt', 'Ingen antikvarisk bedömning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Krog, uppgift om, anvisad av A. Zetterström, 75 år, Floholm. Ev.husgrunder m.mborttogs vid vägbygge 1965-66. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Asfalterad parkeringsficka.', NULL, NULL, NULL, 'Uppgift om lämning, ej bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7279411, 15.404275, 522052.2, 6732552.7, 522052, 6732552, 522053, 6732553, 0, 'Point', '{"type":"Point","coordinates":[15.404275,60.7279411]}', 0, 30, '2018-10-01T09:42:54+02:00', 'Riksantikvarieämbetet', '2026-11-17', '683d186e9a81bbfa9ab2614bc2137f81');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (861, '38be193e-2eaf-48df-9ba0-9e4b4b688a2e', 'L2024:524', NULL, NULL, 'Kolningsanläggning', 'Övrig kulturhistorisk lämning', NULL, 'Kolbotten efter liggmila, 9 x 9 m och intill 0,5 m h med kring kanterna vall, och i SV och SO stybbtäktsgropar. Bevuxen med granar och en.', 'Flack moränmark på höjdsträckning.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7222165, 15.3053551, 516659.4, 6731885.9, 516659, 6731885, 516660, 6731886, 0, 'Point', '{"type":"Point","coordinates":[15.3053551,60.7222165]}', 0, 30, '2024-02-16T11:53:37.853+01:00', 'länsstyrelsen', '2026-11-17', '4e014cf08e593c21c9d36bb32b8083f0');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (864, '3922a80a-3029-41f5-95cb-36090d3c82c4', 'L2024:773', NULL, NULL, 'Bytomt/gårdstomt', 'Övrig kulturhistorisk lämning', NULL, 'Gårdstomt, 51 x 38 m, enligt Storskifteskarta (1819/U3-8:1). Vid inventeringstillfället iakttogs en skadad husgrund.', 'Flack sediment och moränmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Åverkan', 'Ej undersökt', 'Synlig ovan mark', 60.8340818, 15.5270732, 528655.6, 6744421.9, 528628, 6744399, 528679, 6744450, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.527031,60.8343259],[15.5273933,60.8341704],[15.5274892,60.8338808],[15.5268944,60.8339176],[15.5265812,60.8341184],[15.527031,60.8343259]]]}', 0, 10, '2024-03-14T10:19:35.860+01:00', 'länsstyrelsen', '2026-11-17', 'd28a9f1851c2e33688ab69f723947b5c');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (877, '39d4af9e-c379-453c-9a10-99d4c7b1c71a', 'L2023:6640', NULL, NULL, 'Bytomt/gårdstomt', 'Fornlämning', 'Övergiven gårdstomt redovisad på karta från år 1819. Ytterligare lämningar kan förekomma dolda under mark. Äldsta skriftliga belägg för Sågsbo är 1588 med två hemmansägare. 1639 fanns åtta hemmansägare.', 'Gårdstomt, ca 50 x 40 m (NÖ-SV) bestående av 4 husgrunder. Tomten är övergiven.
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (878, '39d93a4b-b482-4aa6-93bb-6c10d355bc24', 'L2000:9085', 'Stora Kopparberg 213:1', 'stora kopparberg 213:1', 'Bytomt/gårdstomt', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', NULL, NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6606914, 15.565573, 530915, 6725127.6, 530914, 6725127, 530915, 6725128, 0, 'Point', '{"type":"Point","coordinates":[15.565573,60.6606914]}', 0, 30, '2018-10-01T11:11:12+02:00', 'Riksantikvarieämbetet', '2026-11-17', '51468f830baac0239bc32a7e9c57983e');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (889, '3a50aa4d-a2c9-4068-81bf-06eca8f97ecc', 'L2001:645', 'Bjursås 26:1', 'bjursås 26:1', 'Vägmärke', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Kilometerstolpe, ej återfunnen 1994. Beskrevs i inventeringen 1967 som, 0.4 m h, 0.2m br och 0.1 m tj. Ingen siffra syntes, men enligt herr Forsell, Orrholen, skall det stå: 3.Herr Forsell hjälpte till med utplacerandet av kilometerstolparnalängs Rogvägen år 1920. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Blockrik moränplatå. Skogsmark (ung lövskog).', '1 m N om väg (VNV-ÖSÖ) på en punkt 46 m V om korsning med mindrekörväg.', NULL, NULL, 'Uppgift om lämning, ej bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.752753, 15.4899457, 526704.7, 6735348, 526704, 6735347, 526705, 6735348, 0, 'Point', '{"type":"Point","coordinates":[15.4899457,60.752753]}', 0, 13, '2018-10-01T09:34:41+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'bb26784d42b1ca866194eae4c6802956');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (895, '3a8a90ac-1254-4ae9-b516-b8950ee45896', 'L2001:1864', 'Bjursås 58:1', 'bjursås 58:1', 'Fäbod', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fäbodlämning, 120x120 m st. I N delen av området är 1 stuga, 3 ekonomibyggnader, 1brunn samt resterna av 1 jordkällare.Runt tomtområdet är ett stenröjt område med enstaka odlingsrösen,2 m diam och 0.2 m h.Ö om landsvägen är ett 50x30 m st (VNV-ÖSÖ) område som bär spår avodling. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', NULL, 'Svag SV-sluttning mot tjärn. Ängsmark.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.8174339, 15.5346275, 529081.4, 6742571, 529007, 6742508, 529130, 6742624, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.535376,60.8168672],[15.5354973,60.8170333],[15.5355133,60.8172538],[15.5354974,60.8175229],[15.5353338,60.8177624],[15.5351263,60.8178461],[15.5345029,60.8179017],[15.5341205,60.8178896],[15.5338646,60.8177817],[15.5332796,60.8175823],[15.53368,60.8174186],[15.5340722,60.8172137],[15.5343503,60.8170004],[15.5346255,60.8169845],[15.535376,60.8168672]]]}', 0, 10, '2018-10-01T09:41:43+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'b951991c6e035ef4a0e208950874d048');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (899, '3acdd321-ad6e-4341-a54a-f32f796917dc', 'L2001:2237', 'Bjursås 109:1', 'bjursås 109:1', 'Gruvområde', 'Fornlämning', 'Enligt Hulphers karta 1835 är detta gruvhål upptaget på 1830-talet.', 'Gruvområde, 84 x 50 m (NO-SV), bestående av två gruvhål, en skrotstenshög och ett dike. Gruvhålen är oregelbundna, 8-15 x 5-8 m (O-V), vattenfyllda med 0,2-2,5 m till vattenytan. Skrotstensvarpet är oregelbundet, 14 x 8 m st och intill 1,5 m h. Dike i NO 20 m l, 0,5 m br och 0,3-0,7 m dj. Invid det norra gruvhålet finns ett mindre hål i marken, 0,6 x 0,6 m och intill 0,5 m dj. I norra delen av området finns också en eldpallsliknande struktur, 1,5 x 1,5 m och 0,4 m h av 0,15-0,25 m st stenar.', 'Svagt till måttligt NO-sluttande moränmark.', 'En skärpning i NV är 8 m N om åkerkant, den sydligaste skärpningen är 46 m Ö omSÖ hörnet av åker.', NULL, NULL, 'Bekräftad i fält', 'Ringa åverkan', 'Ej undersökt', 'Synlig ovan mark', 60.7119159, 15.2755616, 515038.7, 6730731.5, 515008, 6730691, 515068, 6730773, 0, 'GeometryCollection', '{"type":"GeometryCollection","geometries":[{"type":"LineString","coordinates":[[15.2754729,60.7117564],[15.2754208,60.711801],[15.2754275,60.7118315],[15.2755153,60.7118373],[15.2755636,60.7118016],[15.2755494,60.7117782],[15.2755314,60.7117602],[15.2754729,60.7117564]]},{"type":"Polygon","coordinates":[[[15.2752011,60.7116093],[15.2750938,60.7116787],[15.2750049,60.7119677],[15.2752302,60.7120893],[15.2755048,60.712162],[15.2757301,60.7122877],[15.2760121,60.7122464],[15.2760779,60.7121731],[15.2760941,60.7121201],[15.276043,60.7119737],[15.2759586,60.7118152],[15.2758164,60.7116935],[15.2757412,60.7116407],[15.2756328,60.7115921],[15.2753419,60.7115561],[15.2752011,60.7116093]]]},{"type":"LineString","coordinates":[[15.2757873,60.7118591],[15.2758437,60.7117949],[15.2757462,60.7117573],[15.2756271,60.7117938],[15.2757873,60.7118591]]}]}', 0, 25, '2024-02-28T10:52:41.450+01:00', 'länsstyrelsen', '2026-11-17', '7e1d579fc7755bc71632237ce44dfa34');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (925, '3c9e7a30-2c0e-4bc7-bda1-bca24c1302c4', 'L2001:2195', 'Bjursås 6:1', 'bjursås 6:1', 'Vägmärke', 'Ingen antikvarisk bedömning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Kilometerstolpe, uppgift om, med siffran:30.Anvisad av herr Liljedahl, Sågmyra. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Vägkant. Skogsmark (hygge).', 'Omedelbart NNV om väg.', NULL, NULL, 'Uppgift om lämning, ej bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7294445, 15.4189492, 522851.6, 6732725.1, 522851, 6732725, 522852, 6732726, 0, 'Point', '{"type":"Point","coordinates":[15.4189492,60.7294445]}', 0, 13, '2018-10-01T09:43:35+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'ebe18d5ca3b28380cd986444290a8382');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (930, '3cd863b9-b8bd-4f3a-a12b-d8dcbc9028aa', 'L2000:8271', 'Stora Kopparberg 82:2', 'stora kopparberg 82:2', 'Kalkugn', 'Fornlämning', NULL, 'Område med kalkbrytning, ca 65x55 m (Ö-V), bestående av 2kalkbrott & kalkugnsruin.Kalkbrott, oregelbundet & svåravgränsat, ca 28x18 m (ÖNÖ-VSV),intill 6 m dj. I brottet är nedrasad sten, vindfällen mm.Kraftigt beväxt med löv- och barrträd samt sly. Från brottets Ödel löper ett dike mot Ö.Ca 2 m S om N kanten av kalkbrottet & ca 20 m Ö om väg är:Klakugnsruin, kvadratisk, 4 m i sida (N-S), ca 1.0 -2.4 m h, av0.2-1.2 m st delvis huggna stenar i kallmur samt sandfodrad.Delvis utrasad åt S. Inga synliga öppningshål. Beväxt med 2större tallar.Ca 5 m ÖNÖ om väg (NNV-SSÖ) är:Kalkbrott, oregelbundet avlångt, ca 10x4 m (Ö-V), ca 1.8-2.5 m djtill vattenytan.Inom området är ställvis smärre varp och högar av ofyndig sten. IV delen det största kalkbrottet har sen tid dumpats bark(sågverksavfall).Området finns utmärkt på LMV Gävle, akt U/22 6:1, 1772 ochomtalas där som Kalek Grufva. Längs i S är en kojruin medspridmursröse. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'ÖSÖ-sluttning nära bergskrön, blockig moränmark. Skogsmark,(barrskog med inslag av lövträd och -sly).', 'Kalkbrottet är ca 8 m Ö om väg (N-S) och ca 20 m S ombeståndsgräns.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6796939, 15.5909512, 532283.1, 6727256.2, 532283, 6727256, 532284, 6727257, 0, 'Point', '{"type":"Point","coordinates":[15.5909512,60.6796939]}', 0, 30, '2018-10-01T11:07:02+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'cc890b061cae48b7f1c32683c8ad3b7e');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (932, '3ce187ef-9691-4d20-b303-22e05d49f421', 'L2024:466', NULL, NULL, 'Bytomt/gårdstomt', 'Möjlig fornlämning', 'Belagd på 1827 års storskifteskarta (20-bju-40). Skadad av senare tiders verksamhet,', 'Gårdstomt, 48 x 38 m (NV-SO), bestående av 2 husgrunder och 1 röjningsrösemur. Den ena husgrunden är skadad och har endast NV hörnet bevarat, den andra husgrunden är kvadratisk, 6 x 6 m och 0,1-0,4 m h, med ett spismursröse 2 x 1,5 m och 0,6 m h. I SO är en röjningsrösemur som avgränsar en terrasserad yta, 25 m l och 1-3 m br.', 'SO-sluttning.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7203377, 15.3205191, 517487.7, 6731680.6, 517463, 6731650, 517509, 6731713, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.3204083,60.7206278],[15.3207842,60.7204563],[15.3208088,60.7204428],[15.3208995,60.7201813],[15.3207008,60.720065],[15.3200697,60.7203089],[15.3200722,60.7203345],[15.3204083,60.7206278]]]}', 0, 10, '2024-02-13T11:32:34.792+01:00', 'länsstyrelsen', '2026-11-17', '954b32fb8e4a936086f1bfb810491885');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (936, '3d3d56c7-adfe-4e16-b0bd-fdfc0fe8c923', 'L2024:323', NULL, NULL, 'Kolningsanläggning', 'Övrig kulturhistorisk lämning', NULL, 'Kolbotten, rund, 10 m diam och intill 0,5 m h med kring kanterna gropar och diken, intill 0,5 m dj. Kraftigt bevuxen med granar, grantelningar och lövsly.', 'N-sluttande moränmark av bergshöjd.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7146406, 15.2609569, 514240.5, 6731031.7, 514240, 6731031, 514241, 6731032, 0, 'Point', '{"type":"Point","coordinates":[15.2609569,60.7146406]}', 0, 30, '2024-01-29T09:37:23.670+01:00', 'länsstyrelsen', '2026-11-17', '83b3177ba10539dd7915e81d0df7317b');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (941, '3d4f1617-ce79-4743-a97b-650e343c1524', 'L2001:1571', 'Bjursås 75:1', 'bjursås 75:1', 'Boplats', 'Fornlämning', NULL, 'Boplats, minst 35x24 m st (Ö-V), bestående av bitvis måttlig förekomst av skärvsten samt fynd av ett större avslag av hälleflinta, 9 cm st, i den NV delen samt i Ö en bit skarpkantad kvarts samt ett skifferbryne(?).', 'SV-slänt av grus- och sandplatå, samt strandplan av sand och grusmot S. Hagmark.', '15 m Ö om parkeringsområde.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Ej synlig ovan mark', 60.7312672, 15.2668338, 514553.7, 6732884.8, 514535, 6732869, 514574, 6732902, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.2672018,60.7311959],[15.2671489,60.7312734],[15.267084,60.7313133],[15.2669169,60.7313683],[15.2667275,60.7314108],[15.2666359,60.7314132],[15.266566,60.7313993],[15.266517,60.7313511],[15.2665011,60.7313046],[15.2665476,60.7312594],[15.2666411,60.7311942],[15.2667061,60.7311579],[15.2667754,60.7311449],[15.2668813,60.7311316],[15.2670243,60.7311361],[15.2672018,60.7311959]]]}', 0, 10, '2018-10-01T09:39:58+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'b73333218b42d762a471be51d3b86ce7');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (945, '3daf2596-b8ef-4986-858e-715a280901a1', 'L2001:1876', 'Bjursås 24:1', 'bjursås 24:1', 'Källa med tradition', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Hälsokälla(?) i ett dike (NÖ-SV). Vattnet har röd-brun färg. Källans storlek är svåratt ange, då diket var delvis vattenfyllt vid inventeringstillfället.Vid den 1994 antagna källan har det smala diket en rund utvidgning, 2 m diam, medrödbrunt slammvatten, liksom i hela diket. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Plan, sank sedimentmark. Skogsmark (björkskog). F.d åkermark.', '43 m ÖNÖ om dikesvinkel och 53 m ÖNÖ om bro över dike.', 'Känd i orten som surbrunn.', NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7576443, 15.4980246, 527140.9, 6735896.1, 527140, 6735896, 527141, 6735897, 0, 'Point', '{"type":"Point","coordinates":[15.4980246,60.7576443]}', 0, 15, '2018-10-01T09:41:48+02:00', 'Riksantikvarieämbetet', '2026-11-17', '628d9ad2b2d187095f6eb1d00446a6be');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (950, '3ddb16b1-9b6e-49f5-ab14-b50a4aaa7218', 'L2000:9420', 'Stora Kopparberg 38:1', 'stora kopparberg 38:1', 'Gruvområde', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Gruvområde, 200x100 m (N-S) bestående av 1 grushål, skrotstensamt minst 5 skärpningar.Gruvhålet är ca 5 m diam och intill 2.5 m dj, 3j vattenfyllt. Igrunvhålets S kant är en öppning mot sluttningen. Beväxt medgran.Skrotsten framförallt i S. I området finns minst 5 mindreskärpningar och platser för stentäkt. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'S-sluttning i moränmark. Skogsmark (barrskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6796378, 15.5625073, 530729.3, 6727236.3, 530671, 6727157, 530781, 6727306, 0, 'GeometryCollection', '{"type":"GeometryCollection","geometries":[{"type":"Polygon","coordinates":[[[15.561582,60.6801794],[15.5614619,60.6799964],[15.5615028,60.679785],[15.5617121,60.6795237],[15.5619362,60.6791944],[15.5621012,60.6790765],[15.5623319,60.6789802],[15.5627161,60.6789309],[15.5630087,60.6789405],[15.5632462,60.6790324],[15.5633699,60.6792334],[15.5634348,60.6795257],[15.563317,60.6797997],[15.5630753,60.6798672],[15.5631223,60.6800502],[15.5632247,60.6800701],[15.5633672,60.6801009],[15.5634147,60.6801386],[15.5633816,60.6801762],[15.5632425,60.6802279],[15.5630376,60.6802418],[15.562723,60.6802536],[15.5621744,60.6802363],[15.5616222,60.6801885],[15.561582,60.6801794]]]},{"type":"LineString","coordinates":[[15.5619141,60.6798028],[15.5618811,60.6798189],[15.5618663,60.6798387],[15.5618918,60.6798602],[15.5619283,60.6798782],[15.5619613,60.6798621],[15.5619688,60.6798424],[15.5619506,60.6798226],[15.5619141,60.6798028]]}]}', 0, 25, '2018-10-01T11:12:49+02:00', 'Riksantikvarieämbetet', '2026-11-17', '1d2798ea47627f218c6fe063def51ce4');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (955, '3e665382-fac5-4d18-aa55-a6a1bab85be3', 'L2023:6351', NULL, NULL, 'Kvarn', 'Fornlämning', 'Redovisad på karta från år 1819.', 'Kvarnlämning, inom ett område av ca 50 x 25 m (N-S), bestående av 1 dammvall, 1 kvarngrund och 1 kvarnsten.
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (974, '3f70479b-040e-4910-b996-a9361687ea31', 'L1999:8809', 'Stora Kopparberg 483', 'stora kopparberg 483', 'Gränsmärke', 'Fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fredsmilsröse, rektangulärt, 2x1,5 m (NNV-SSÖ) och 0,5 m h, av stenar, 0,3-0,7 m. Visarsten, 0,75 m h, 0,4 m br och 0,15 m tj, omkullfallen mot NÖ. I SSV hörnet är en nedrasad sten. Markerad med pinne i mitten. Övermossad.', 'N-sluttande bergshöjd. Skogsmark (barrskog).', NULL, 'Fredsmilen kring Kopparbergs gruva.', NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6886894, 15.5392048, 529448.1, 6728233.8, 529448, 6728233, 529449, 6728234, 0, 'Point', '{"type":"Point","coordinates":[15.5392048,60.6886894]}', 0, 15, '2018-10-01T12:03:09+02:00', 'Riksantikvarieämbetet', '2026-11-17', '1764c7db8714044fcf45b9766add8ff4');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (975, '3f799b80-f245-4eac-a7fa-d4c626f90193', 'L2023:6359', NULL, NULL, 'Kolningsanläggning', 'Övrig kulturhistorisk lämning', NULL, 'Kolbotten efter resmila, rund, 14 m diam och 0,1-0,5 m h med ojämn, delvis flack yta.', 'Svagt kuperad moränmark vid myrmark. Skogsmark (barrskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7757213, 15.362516, 519745, 6737861.1, 519745, 6737861, 519745, 6737862, 0, 'Point', '{"type":"Point","coordinates":[15.362516,60.7757213]}', 0, 25, '2023-10-31T15:45:33.328+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', 'd819102e05d06c5458d2d3132f9d645a');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1002, '418976a6-7887-4c85-961d-30407e1af0b1', 'L2023:6646', NULL, NULL, 'Bytomt/gårdstomt', 'Ingen antikvarisk bedömning', NULL, 'Uppgift om gårdstomt, ca 360 x 30 m (V-S) enligt utsträckning på storskifte år 1819. Tomten är övergiven. På storskifteskarta från år 1819 är 5 byggnader redovisade inom angivet område. Vid besökstillfället var det hög vegetation och inga tydliga lämningar, husgrunder, kunde iakttas.', 'SSÖ-sluttande moränmark. Öppen småbruten bymiljö.', NULL, NULL, NULL, 'Uppgift om lämning, ej bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.770668, 15.3824836, 520835.8, 6737304.4, 520803, 6737287, 520870, 6737320, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.3829147,60.7707952],[15.3830967,60.7707033],[15.3828399,60.770543],[15.382389,60.770519],[15.3820099,60.7705608],[15.3818928,60.770761],[15.3825513,60.7708029],[15.3829147,60.7707952]]]}', 0, 5, '2023-11-06T14:34:29.373+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', '3f142756cfebce36a769c51639ff40ad');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1006, '41c16e0d-59e6-4aa5-8680-1bc083ccc37e', 'L1999:576', 'Stora Kopparberg 148:1', 'stora kopparberg 148:1', 'Övrigt', 'Övrig kulturhistorisk lämning', NULL, 'Stolpröse, närmast rektangulärt, 3x1.85 m (ÖNÖ-SSV)  och intill1.1 m h, kallmurat, av 0.2-0.8 m st stenar.I mitten en rest stolpe 1.4 h. Stolpen har en järnspik och lutarmot NNV och är starkt förrutnad.lantbrukare Ernst Gullben, Studsarvet, f 1905, uppger att rösetanvänddes till att resa upp störar och stolpar av olika längder.De kallades för rogkal i folkmålet. Beläget på toppen av ettstort odlingsröse. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Krön av odlingsröse. Åkerholme, i svag NNV-sluttning', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6856464, 15.5261173, 528736.1, 6727889.1, 528736, 6727889, 528737, 6727890, 0, 'Point', '{"type":"Point","coordinates":[15.5261173,60.6856464]}', 0, 30, '2018-10-01T11:21:53+02:00', 'Riksantikvarieämbetet', '2026-11-17', '4842878ee4591b249eff22c4ce2cc537');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1013, '4267e6dc-a162-49e0-b17b-02138e6a7401', 'L2023:6063', NULL, NULL, 'Kolningsanläggning', 'Övrig kulturhistorisk lämning', NULL, 'Kolbotten efter liggmila, kvadratisk, 7x7 m (NNV-SSÖ) och 0,1-0,8 ,m h med flack yta. Omgiven av stybbdiken, 1-2 m br och 0,3-0,5 m dj.', 'Svag SSÖ sluttning i småkuperad stenig och blockig moränmark. Skogsmark (tallskog)', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7456322, 15.3496773, 519063.6, 6734506, 519063, 6734505, 519064, 6734506, 0, 'Point', '{"type":"Point","coordinates":[15.3496773,60.7456322]}', 0, 25, '2023-10-24T11:05:03.847+02:00', 'Länsstyrelsen Dalarna', '2026-11-17', '303467b1b47b6889f7fe2385ea23a77f');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1038, '44114c80-6ccc-4b54-9c7f-1eaa9f8e8685', 'L2023:6353', NULL, NULL, 'Kvarn', 'Fornlämning', 'Kvarnplats redovisad på karta från år 1819.', 'Kvarnlämning, inom ett område av ca 40 x 20 m (NNÖ-SSV), bestående av 1 dammvall och 1 kvarngrund 
