INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1057, '4502f759-71f9-49d4-9b28-9057afdbea80', 'L2001:1014', 'Bjursås 127:1', 'bjursås 127:1', 'Fäbod', 'Fornlämning', NULL, '1) Fäbodlämning, 40x35 m st (NÖ-SV), bestående av 2 husgrunder, varav en stuggrundmed spisröse och en källargrund.70 m NÖ om nr 1 är:2) Fäbodlämning, 145x25-50 m st (NÖ-SV), bestående av 10 husgrunder, fördelade på tvåklungor med 5 i SV och 5 i NÖ. I SV finns två stuggrunder med spisröse. I NÖ är enstuggrund med spisröse och källargrop samt ytterligare en källargrund.5 m SÖ om NÖ delen av nr 2 och SÖ om väg är:3) Fäbodlämningar, uppgift om, där det år 1811 fanns 4 byggnader inom ett ca 70x20 m stområde (NÖ-SV), utan spår 1994. Grunderna är åtminstone delvis troligen förstörda elleröverlagrade i samband med vägbygge.Ca 65 m Ö om NÖ delen av nr 2 är:4) Fäbodlämningar, uppgift om, där det år 1811 fanns 1 byggnad, troligen en stuga och därförtroligen finns flera husgrunder. Ej eftersökta 1994.110 m NV om nr 4 är:5) Fäbodlämning, uppgift om, markerad med en stuga 1912 och två byggnader påEkonomiska kartan. Ej på kartan 1811.År 1811 markeras vid nr 1 en byggnad och vid nr 2 endast två byggnader, en i SVoch en iNÖ, trots att 10 grunder konstaterades.Uggelåsens fäbodar markeras på en karta år 1811, fäboden omtalas som gammal avForsslund. Namnet och två stugor markeras NV om vägen på Generalstabskartan 1912. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Krön av moränrygg (NÖ-SV) mellan mosse och tjärn. Skogsmark (högbarrskog. I NÖdelen av nr 2 är hög blandskog intill igenväxande åker).', 'Nr 2 är intill och NV om väg.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Ej synlig ovan mark', 60.7178963, 15.4279861, 523352.9, 6731442.1, 523331, 6731422, 523376, 6731462, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.4278434,60.7177181],[15.4279129,60.717729],[15.4280777,60.7177309],[15.4281983,60.7177615],[15.428297,60.7178118],[15.42837,60.7178693],[15.4283953,60.7179375],[15.4283584,60.7179931],[15.4282776,60.7180396],[15.4281163,60.7180736],[15.4279003,60.7180734],[15.4277833,60.7180392],[15.4276555,60.7179566],[15.4276046,60.7178812],[15.4275866,60.7177951],[15.4276748,60.7177449],[15.4278434,60.7177181]]]}', 0, 10, '2018-10-01T09:36:53+02:00', 'Riksantikvarieämbetet', '2026-11-17', '652690ec8c62918ea85ab398c1450398');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1060, '4543f73e-e777-4a8e-a79b-654eb35784af', 'L2001:2107', 'Bjursås 25:1', 'bjursås 25:1', 'Plats med tradition', 'Övrig kulturhistorisk lämning', NULL, 'Ravin, med namn, ca 250 m l (NÖ-SV), 10-15 m br och intill 10 m dj. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'SSV-sluttande blockig moränmark. Skogsmark (barrskog).', 'Ca 125 m SV om Såtjärns S ände.', NULL, 'Trollgatan', 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7673429, 15.4932345, 526871.7, 6736974.3, 526768, 6736885, 526972, 6737066, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.4950677,60.7679101],[15.4950734,60.7679837],[15.4949914,60.7680407],[15.4949353,60.7680889],[15.4947797,60.7681598],[15.4946552,60.7681519],[15.4945277,60.7681189],[15.4942551,60.7680116],[15.4933073,60.7676025],[15.4924938,60.7672606],[15.491899,60.766972],[15.4916559,60.7668594],[15.4914123,60.7667683],[15.4913622,60.7667142],[15.4913344,60.7666476],[15.4914502,60.7665549],[15.4916921,60.7665562],[15.4918494,60.7665733],[15.4921883,60.7666666],[15.4927225,60.7668778],[15.4932921,60.7671447],[15.4943634,60.7676011],[15.4950677,60.7679101]]]}', 0, 10, '2018-10-01T09:43:03+02:00', 'Riksantikvarieämbetet', '2026-11-17', '90fd13efb1b5c4a177ff936bd47dd3f5');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1062, '457eb2dc-e873-475c-b93a-ff2e5fe41824', 'L2001:1094', 'Bjursås 127:2', 'bjursås 127:2', 'Fäbod', 'Fornlämning', NULL, '1) Fäbodlämning, 40x35 m st (NÖ-SV), bestående av 2 husgrunder, varav en stuggrundmed spisröse och en källargrund.70 m NÖ om nr 1 är:2) Fäbodlämning, 145x25-50 m st (NÖ-SV), bestående av 10 husgrunder, fördelade på tvåklungor med 5 i SV och 5 i NÖ. I SV finns två stuggrunder med spisröse. I NÖ är enstuggrund med spisröse och källargrop samt ytterligare en källargrund.5 m SÖ om NÖ delen av nr 2 och SÖ om väg är:3) Fäbodlämningar, uppgift om, där det år 1811 fanns 4 byggnader inom ett ca 70x20 m stområde (NÖ-SV), utan spår 1994. Grunderna är åtminstone delvis troligen förstörda elleröverlagrade i samband med vägbygge.Ca 65 m Ö om NÖ delen av nr 2 är:4) Fäbodlämningar, uppgift om, där det år 1811 fanns 1 byggnad, troligen en stuga och därförtroligen finns flera husgrunder. Ej eftersökta 1994.110 m NV om nr 4 är:5) Fäbodlämning, uppgift om, markerad med en stuga 1912 och två byggnader påEkonomiska kartan. Ej på kartan 1811.År 1811 markeras vid nr 1 en byggnad och vid nr 2 endast två byggnader, en i SVoch en iNÖ, trots att 10 grunder konstaterades.Uggelåsens fäbodar markeras på en karta år 1811, fäboden omtalas som gammal avForsslund. Namnet och två stugor markeras NV om vägen på Generalstabskartan 1912. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Krön av moränrygg (NÖ-SV) mellan mosse och tjärn. Skogsmark (högbarrskog. I NÖdelen av nr 2 är hög blandskog intill igenväxande åker).', 'Nr 2 är intill och NV om väg.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Ej synlig ovan mark', 60.7188596, 15.4301027, 523467.7, 6731550.1, 523409, 6731497, 523539, 6731596, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.4291031,60.7185032],[15.4291473,60.7184476],[15.4292244,60.7184064],[15.4293746,60.718385],[15.4295539,60.7184121],[15.4297075,60.7184553],[15.4300475,60.7185919],[15.4302886,60.7187105],[15.4304969,60.7188165],[15.4308553,60.7189137],[15.4310674,60.7189803],[15.4312502,60.7190576],[15.4313926,60.7191438],[15.4314034,60.7191815],[15.431297,60.7192173],[15.4309782,60.71926],[15.430612,60.7192687],[15.4303265,60.7192469],[15.4301838,60.7192092],[15.4301328,60.7191625],[15.4301293,60.719105],[15.4301334,60.7190297],[15.4301153,60.7189741],[15.4299947,60.7189273],[15.4298923,60.7188806],[15.4297531,60.7189038],[15.4295992,60.7189216],[15.4293905,60.7189053],[15.4292369,60.7188675],[15.4290872,60.7187687],[15.4290436,60.7186897],[15.4290513,60.7186216],[15.4290699,60.7185624],[15.4291031,60.7185032]]]}', 0, 10, '2018-10-01T09:37:16+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'e5964d6ff902ecc1692d53ef034d78f2');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1075, '45da7593-319e-40f0-b78b-bc86f1a0321c', 'L1998:2110', 'Leksand 2281', 'leksand 2281', 'Fångstanläggning övrig', 'Fornlämning', 'Lämningen blev dendrodaterad på två olika ställen av Bertil Israels 2007,  till 1700 - 1800-tal (RAÄ dnr 326-360-2011). 1763 den ena biten (möjligen 1510), och 1837 den andra biten. Lämningen har sannolikt varit i bruk under 1800-talet , troligen även under 1700-talet, enligt Bertil Israels.', 'Område med fiskefångstanläggningar sk katsor, ca 210x40-90 m (NNV-SSÖ), bestående av åtminstone 15-talet fångstanläggningar i form av regelbunda till oregelbundna ledarmar i form av rader av störar, brädor och kluvna stockar lodrätt nedkörda i den dyiga bottnen.  Ledarmarna är är mellan 3-33x0,5-5 m och de är rektangulära till bågformade. Störarna/stockarna i dessa sticker upp ovan "mark" 0,05-0,7 m, merparten endast 0,1-0,15 m. I områdets NV del i anslutning till den längsta ledarmens S del är en förmodad "sump" ca 2x2 m. Stor del av störar, brädor och kluvna stockar som ingår i ledarmarna uppvisar spår av bearbetning och i området ligger även ställvis grövre stockar/brädor med spår av hål och olika huggna formningar av träet. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1088, '467d0ea0-1d02-4f9c-a72c-80777f49be4b', 'L2023:5619', NULL, NULL, 'Gränsmärke', 'Övrig kulturhistorisk lämning', NULL, 'Gränsmärke, bestående av en stående visarsten, ca 0,6 m h, ca 5-18 cm bredd (V-Ö) och 5 cm i toppen (V-Ö) och 7-12 cm tj.', 'NV slänt i kuperad moränmark. Skogsmark (barrskog med inslag av löv).', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.735113, 15.3440283, 518761.7, 6733332.8, 518761, 6733332, 518762, 6733333, 0, 'Point', '{"type":"Point","coordinates":[15.3440283,60.735113]}', 0, 10, '2023-10-11T17:19:58.146+02:00', 'Länsstyrelsen Dalarna', '2026-11-17', '91ec7cb1d51f888272782e7e2b17d103');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1112, '479287b2-819c-453b-90f6-d419f0f0ee0a', 'L2023:6635', NULL, NULL, 'Bytomt/gårdstomt', 'Fornlämning', 'Övergiven gårdstomt redovisad på karta från år 1819. Ytterligare lämningar kan förekomma dolda under mark. Äldsta skriftliga belägg för Sågsbo är 1588 med två hemmansägare. 1639 fanns åtta hemmansägare.', 'Gårdstomt, ca 50 x 45 m (ÖNÖ-VSV) bestående av minst 1 husgrund. Tomten är övergiven.
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1122, '483fa566-1e75-472b-9ac6-62adc02f0d2f', 'L2001:1554', 'Bjursås 13:1', 'bjursås 13:1', 'Plats med tradition', 'Övrig kulturhistorisk lämning', NULL, 'Berghäll, med namn, ca 15x2 m st (NNÖ-SSV) och intill 1 m h, bildande en avsatsned mot åker i ÖSÖ.Samlingsplats vid midsommar. På hällen är en skylt med nämnda namn. Utsiktspunkt på"Vildmarksleden". Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'ÖSÖ krönkanten av bergshöjd. Kant av skogsmark intill åkermark.', NULL, NULL, 'Hanses hällar', 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.749317, 15.4498093, 524519.7, 6734949.6, 524519, 6734949, 524520, 6734950, 0, 'Point', '{"type":"Point","coordinates":[15.4498093,60.749317]}', 0, 30, '2018-10-01T09:39:53+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'b06b7b7776315d1d5ea9ac74be3be635');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1136, '4921be35-f5f9-4a0c-886d-deba8672af7c', 'L2000:9968', 'Stora Kopparberg 162:1', 'stora kopparberg 162:1', 'Källa med tradition', 'Fornlämning', NULL, 'Trefaldighetskälla, rund, 1.2 m diam och 0.1 m dj. Källanavrinner mot V genom en i sen tid anlagd ledning,7 m l, till en invändigt kallmurad brunn, 1.2 m diam och ca 0.7dj, av otuktade 0.2-0.4 m st gråstenar. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'V foten av höjd (N-S). Skogsmark, (ung lövskog) intill tomtmark.', '1 m ÖSÖ om stig, 9 m NNÖ om sämre körväg (VNV-ÖSÖ).', 'Lantbrukare E. Gullberg, f 1905, Studsarvet, uppger att han i sinbarndom sett källan lövad och att man drack trefaldighet där.', 'Sigrids källa', 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6802415, 15.5081698, 527760.4, 6727279.4, 527760, 6727279, 527761, 6727280, 0, 'Point', '{"type":"Point","coordinates":[15.5081698,60.6802415]}', 0, 15, '2018-10-01T11:18:18+02:00', 'Riksantikvarieämbetet', '2026-11-17', '7af8cd81360edb3e2e2f1fcfb977841b');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1147, '49b65786-fa03-47cf-8dfb-70617727e778', 'L2024:3207', NULL, NULL, 'Stensättning', 'Fornlämning', NULL, 'Stensättning, närmast rund, 3 m diam och 0,2 m h. Tydligt välvd profil och väl avgränsad mot omgivande mark. Runtom är dike ca 0,5 br, och 0,3 m dj. Vid sondning framkom kol.', 'Sydsluttande moränmark. Skogsmark, barr- och lövträd. Intill ängs/hagmark.', 'Ca 0,2-0,5 m från rågångshörn.', NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7441176, 15.397984, 521698.1, 6734352.3, 521698, 6734352, 521699, 6734353, 0, 'Point', '{"type":"Point","coordinates":[15.397984,60.7441176]}', 0, 30, '2024-07-01T11:42:28.796+02:00', 'STIFTELSEN DALARNAS MUSEUM', '2026-11-17', 'b1ca9a3c44e6d13fb6e43fa9d4dfcf2f');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1159, '4a82e0af-5f6b-43af-91bb-90ef321a9a48', 'L2000:8267', 'Stora Kopparberg 81:1', 'stora kopparberg 81:1', 'Gruvområde', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Gruvområde, ca 80x55 m (ÖNÖ-VSV), bestående av 3 gruvhål,skrotstensvarp och 1 kojruin,separat beskrivna.Gruvhål, närmast ovalt, ca 8x7 m (Ö-V), ca 3 m dj. I botten ärnedrasad sten och skrotsten. Ö resp NÖ därom är skrotstensvarp.16 m SV om gruvhålet är:Gruvhål, närmast runt, ca 8 m i diam, ca 3 m dj. I botten ärnedrasad sten och skrotsten. Omkring gruvhålet ärskrotstensvarp.2 m SV om gruvhålet är:Gruvhål, närmast ca 8x7 m (NÖ-SV), ca 2 m dj. I botten ärnedrasad sten och skrotsten. I Nö kanten är ett större block.SV om gruvhålet är ett större skrotstensvarp.10 m VNV om det NÖ gruvhålet är en kojruin med välbevaradspismur.27 m NV om det NÖ gruvhålet och inom området är2) Gränsröse (ej nuvarande gräns), rektangulärt, 1.5x1.2 m(SÖ-NV) 0.4 m h av huggen gråsten i kallmur. På toppen är enupprättstående visarsten. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Flack SSÖ-sluttning av blockig moränmark. Skogsmark (hygge medrikligt med utsparade tallar).', 'Nr q är ca 100 m VSV om väg (NNV-SSÖ).', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6738764, 15.5960253, 532566.2, 6726610.8, 532533, 6726571, 532603, 6726649, 0, 'GeometryCollection', '{"type":"GeometryCollection","geometries":[{"type":"LineString","coordinates":[[15.5959151,60.6737782],[15.5959041,60.6737836],[15.5958858,60.6737979],[15.5959113,60.6738159],[15.5959259,60.6738266],[15.5959369,60.6738177],[15.5959626,60.6738034],[15.5959553,60.6737926],[15.5959151,60.6737782]]},{"type":"LineString","coordinates":[[15.5963319,60.6738451],[15.5963208,60.6738613],[15.5963061,60.6738828],[15.5963279,60.6739043],[15.5963609,60.6738918],[15.5963756,60.6738793],[15.5963647,60.6738595],[15.5963319,60.6738451]]},{"type":"LineString","coordinates":[[15.5957112,60.6737793],[15.5957587,60.6738009],[15.5957989,60.6737956],[15.5958063,60.6737615],[15.5957808,60.6737346],[15.5957369,60.6737202],[15.5956967,60.6737362],[15.5956893,60.6737577],[15.5957112,60.6737793]]},{"type":"Polygon","coordinates":[[[15.595466,60.6738469],[15.5954297,60.673759],[15.5954152,60.673673],[15.5954483,60.6735906],[15.5956239,60.6735336],[15.595741,60.6735266],[15.5959128,60.6735753],[15.5960918,60.6736348],[15.5963148,60.6737051],[15.5965121,60.6737629],[15.5966692,60.6738564],[15.5966982,60.6739568],[15.5966651,60.6740338],[15.5965187,60.6741142],[15.5962589,60.6741764],[15.5960467,60.6742136],[15.5958895,60.67419],[15.5957544,60.6741127],[15.595601,60.673987],[15.5955281,60.6738882],[15.595466,60.6738469]]]}]}', 0, 25, '2018-10-01T11:07:02+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'aa5d41eef59e168ed10905f160675339');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1163, '4a9a8702-f486-4795-ab8a-96cc53dc482c', 'L2024:776', NULL, NULL, 'Träindustri', 'Fornlämning', 'Finns markeringar på platsen på äldre kartor.', 'Lämning efter pärthyvel, bestående en husgrund och en dammvall, som delats med de intilliggande kvarnarna', 'Flack morän- och sedimentmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.8298064, 15.5335763, 529013, 6743948.6, 529012, 6743948, 529013, 6743949, 0, 'Point', '{"type":"Point","coordinates":[15.5335763,60.8298064]}', 0, 30, '2024-03-14T13:55:31.377+01:00', 'länsstyrelsen', '2026-11-17', '827f6ca6048510b8c2d1db84fe74ee80');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1208, '4d97ae90-10c9-413d-80cb-8599b07dcb1f', 'L2023:6290', NULL, NULL, 'Bytomt/gårdstomt', 'Fornlämning', 'Övergiven gårdstomt redovisad på karta från år 1819. Ytterligare lämningar kan förekomma dolda under mark. Limbo var tidigare en byklunga till Sågsbo. Äldsta skriftliga belägg för Sågsbo är 1588 med två hemmansägare. 1639 fanns åtta hemmansägare.', 'Gårdstomt, ca 40x 35 m (ÖNÖ-VSV) bestående av 5 husgrunder. Tomten är övergiven.
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1209, '4d99af7a-08ef-41bc-bbd2-7e21e57ebdcf', 'L2024:793', NULL, NULL, 'Färdväg', 'Fornlämning', 'Spår av den gamla färdvägen Finnbo-Marnäs, ställvis hålvägsliknande.', 'Färdväg, del av, L 147 m, B 0,4-0,6 m (?) Färdvägen utgör en del av den gamla färdvägen mellan Finnbo och Marnäs.', 'O-sluttande morän- och sedimentmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.8344677, 15.5354202, 529109, 6744468.6, 529078, 6744403, 529149, 6744526, 0, 'LineString', '{"type":"LineString","coordinates":[[15.5348436,60.8338885],[15.5351103,60.8341357],[15.535255,60.8343121],[15.5355229,60.8346284],[15.5356461,60.8347703],[15.5356672,60.8347845],[15.5358019,60.8348633],[15.5361623,60.8349778]]}', 0, 25, '2024-03-15T11:03:14.873+01:00', 'länsstyrelsen', '2026-11-17', '31994d3603bc55a062089aea1531ec5f');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1215, '4dfed887-0d1c-40a8-99d5-307593423e89', 'L2024:772', NULL, NULL, 'Bytomt/gårdstomt', 'Möjlig fornlämning', 'Belagd på Storskifteskarta 1819, men svårbesiktigat vid inventeringstillfället,', 'Gårdstomt 82 x 64 m (N-S) enligt Storskifteskarta (1819/U3-8:1). Vid inventeringstillfället iakttogs två övervuxna förhöjningar som eventuellt kan vara lämningar efter husgrunder och ett odlingsröse. Kraftig vegetation på de misstänkta grunderna vid besiktning.', 'Flack morän och sedimentmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.8346081, 15.5280437, 528707.8, 6744481, 528677, 6744428, 528746, 6744526, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5287433,60.8346353],[15.5284125,60.8345722],[15.5284592,60.8342936],[15.5278234,60.8341352],[15.5277564,60.8342501],[15.5278326,60.8344129],[15.5275683,60.8345082],[15.5274909,60.8348875],[15.5281523,60.8350091],[15.5287433,60.8346353]]]}', 0, 10, '2024-03-14T09:27:00.174+01:00', 'länsstyrelsen', '2026-11-17', '441e328075e8a5dbae14d10d2bb4f2f5');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1216, '4e15c965-ab5a-4843-aef4-886371126018', 'L1999:273', 'Stora Kopparberg 245:1', 'stora kopparberg 245:1', 'Bytomt/gårdstomt', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', NULL, NULL, NULL, 'Tå', 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6733455, 15.6080946, 533226.2, 6726557.7, 533226, 6726557, 533227, 6726558, 0, 'Point', '{"type":"Point","coordinates":[15.6080946,60.6733455]}', 0, 30, '2018-10-01T11:19:59+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'cc408afb418b67c422ee6ff5ba6f16c9');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1252, '51154dff-49c5-4795-ba1b-e357a8d49086', 'L2001:1411', 'Bjursås 78:1', 'bjursås 78:1', 'Fyndplats', 'Övrig kulturhistorisk lämning', NULL, 'Fyndplats, för 1 bearbetat stycke, av mörk, tät bergart och 1 litet avslag av vit kvarts. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Strandplan av sand och grus mot S inne i bukt.', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.731704, 15.2693738, 514692, 6732934.1, 514691, 6732934, 514692, 6732935, 0, 'Point', '{"type":"Point","coordinates":[15.2693738,60.731704]}', 0, 30, '2018-10-01T09:39:04+02:00', 'Riksantikvarieämbetet', '2026-11-17', '8a3d8621b0086925bc3e0b5a6704ccb9');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1258, '51363659-f126-448f-8a54-22ca4626b1a9', 'L2024:1229', NULL, NULL, 'Fångstgrop', 'Möjlig fornlämning', 'Otydligt blekjordsskikt, men lik övriga längs bäcken.', 'Fångstgrop, rund, 1,6 m diam och 0,3 m dj, omgiven av en vall 1,4-2,0 m br och 0,3 m h.', 'Terrasskant nära ytterkant i O-sluttande moränmark mot bäck.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.8533314, 15.4779566, 525969.6, 6746545.5, 525969, 6746545, 525970, 6746546, 0, 'Point', '{"type":"Point","coordinates":[15.4779566,60.8533314]}', 0, 30, '2024-04-15T18:07:51.042+02:00', 'länsstyrelsen', '2026-11-17', 'b6112e59015ca0df3bd5999d07a11934');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1269, '51c2f6ed-61a4-46f6-8e01-7f405251052a', 'L2023:6274', NULL, NULL, 'Fornlämningsliknande bildning', 'Ej kulturhistorisk lämning', NULL, 'Stensättningsliknande bildning, närmast rund, 7 m diam och intill 0,4 m h. I mitten är en grop, försänkning, ca 1,8x0,8 m st (V-Ö) och intill 0,2 m dj.', 'Krön av moränås i kuperad stenig moränmark. Skogsmark (granskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7518986, 15.3355179, 518288.1, 6735199.9, 518288, 6735199, 518289, 6735200, 0, 'Point', '{"type":"Point","coordinates":[15.3355179,60.7518986]}', 0, 25, '2023-10-30T10:50:12.975+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', 'eb5905239bd7c486503ba655e2a8645c');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1288, '52e71f30-3a3e-45e1-ad10-ec606efb2b36', 'L2023:6768', NULL, NULL, 'Bytomt/gårdstomt', 'Ingen antikvarisk bedömning', NULL, 'Uppgift om gårdstomt, ca 35 x 30m (ÖNÖ-VSV) enligt utsträckning på storskifte år 1819. Tomten är övergiven. På storskifteskartan är totalt 5 byggnader bestående av 1 kringbyggd gård med 4 byggnader samt 1 fristående byggnad redovisade. Vid platsbesök iakttogs inga lämningar ovan mark.', 'småkuperad flack jordbruksmark i moränmark. Gräsbevuxen ängs-/hagmark.', NULL, NULL, NULL, 'Uppgift om lämning, ej bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.773945, 15.4069494, 522166.3, 6737677.4, 522145, 6737658, 522193, 6737700, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.4069785,60.7741433],[15.4074309,60.7738744],[15.407122,60.7738411],[15.4068336,60.7737768],[15.4065648,60.7738875],[15.4066757,60.7740379],[15.4069785,60.7741433]]]}', 0, 5, '2023-11-08T13:37:53.357+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', 'd3e518356099e532c384064e8aeb8dc6');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1294, '53666d70-e7a9-4010-986f-297291647546', 'L2000:9827', 'Stora Kopparberg 127:1', 'stora kopparberg 127:1', 'Vägmärke', 'Fornlämning', NULL, 'Postament till milstolpe, av sten, kallmurat, kvadratiskt, 1.65 msida och 1.1 m h. SÖ hörnet raserat. Mitt på postamentet är enrest flat sten, 0.65 m h, 0.3 m br (ÖV) och0.1 m tj sannoliktgränssten.Enl uppgift skall järnplattan ha borttagits och förvaras på ensommarstugetomt i Kårsarvet. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'NÖ sluttning av blockrik moränhöjd. Skogsmark, (blandskog).', 'Ca 50 m SÖ om litet vägskäl och 2 m VSV om körväg (NNV-SSÖ).', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.642137, 15.5689965, 531120, 6723062.7, 531119, 6723062, 531120, 6723063, 0, 'Point', '{"type":"Point","coordinates":[15.5689965,60.642137]}', 0, 13, '2018-10-01T11:16:45+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'e37927007678d90c0d38f92fcfb39059');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1295, '536baa47-4820-4070-a06a-7129da0249f0', 'L2023:6658', NULL, NULL, 'Husgrund, historisk tid', 'Övrig kulturhistorisk lämning', NULL, 'Husgrund efter jordkällare, rektangulär, 8 x 5,5 m (VNV-ÖS) och 1 m h med öppning I ÖSÖ. Kallmurad och igenrasad.', 'Fot av ÖSÖ sluttande moränmark. Skogsparti (blandskog) i småbrutet odlingslandskap.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7703833, 15.389217, 521202.8, 6737274.9, 521202, 6737274, 521203, 6737275, 0, 'Point', '{"type":"Point","coordinates":[15.389217,60.7703833]}', 0, 25, '2023-11-06T15:42:48.505+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', 'd6e2d873a5f641b65f210f5dc0ff2097');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1297, '5386008f-da00-4a35-8c2c-9e00f7a2b740', 'L1999:8803', 'Stora Kopparberg 481', 'stora kopparberg 481', 'Gränsmärke', 'Fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fredsmilsröse, 1,8x1,8 m (Ö-V) och 0,3 m h, av stenar, 0,1-0,5 m. Sannolik visare, liggande, 0,6 m l och 0,35 m br.', 'N-sluttande moränmark. Skogsmark.', '30 m SÖ om beståndskant mot skogsmark.', 'Fredsmilen kring Kopparbergs gruva.', NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6912081, 15.556152, 530371.3, 6728522, 530371, 6728522, 530372, 6728523, 0, 'Point', '{"type":"Point","coordinates":[15.556152,60.6912081]}', 0, 15, '2018-10-01T12:03:07+02:00', 'Riksantikvarieämbetet', '2026-11-17', '190d0bb778997384b610463d2c3bfff7');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1330, '55ae8977-4ba9-4545-9716-644bea019bdd', 'L2024:392', NULL, NULL, 'Boplats', 'Fornlämning', NULL, 'Boplats, oklar utsträckning. Inom angivet område, ca 6 x 3 m (NV-SO), påträffades på sandig sjöbotten 0,1-0,3 m under vattnet måttligt med skärvstenar och avslag av vit kvartsit.', 'Strand i flack V-sluttande sandig moränmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7206135, 15.2821063, 515391.8, 6731701.7, 515391, 6731701, 515392, 6731702, 0, 'Point', '{"type":"Point","coordinates":[15.2821063,60.7206135]}', 0, 30, '2024-02-05T16:55:59.375+01:00', 'länsstyrelsen', '2026-11-17', '1b27c24e77daa253a3b9694d8e5bc760');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1333, '55df15b8-97f2-41e2-9468-a9f5db64edaa', 'L2023:6357', NULL, NULL, 'Kolningsanläggning', 'Övrig kulturhistorisk lämning', NULL, 'Kolbotten efter liggmila, kvadratisk, 8 x 8 m (NÖ-SV) och 0,1-0,3 m h med ojämn, delvis utgrävd yta. Omgiven av stybbdiken, 1-3 m br och 0,3-0,6 m dj.', 'Svag NÖ sluttning i moränmark. Skogsmark (barrskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7725523, 15.353671, 519265.1, 6737505.5, 519265, 6737505, 519266, 6737506, 0, 'Point', '{"type":"Point","coordinates":[15.353671,60.7725523]}', 0, 25, '2023-10-31T15:34:33.556+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', '748190cb134df5b01564d315284bd60a');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1334, '55e7486d-db2f-4090-9eef-50a7e81d98ad', 'L2001:1863', 'Bjursås 57:1', 'bjursås 57:1', 'Fäbod', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fäbodlämning, 120x80 m st (Ö-V). I områdets Ö del är rester efter1 stuga medspismursröse, 1 grund efter en ekonomibyggnad och 1 kvarstående ekonomibyggnad.I områdets V del, längst ut mot sjön, är rester av 1 stuga med spismursröse och 2 grunder frånekonomibyggnad. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Moränudde. Skogsmark (barrskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7885966, 15.5472122, 529792.7, 6739364.8, 529718, 6739323, 529861, 6739404, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5476299,60.7882236],[15.5479615,60.7882791],[15.5482568,60.7883509],[15.5483883,60.7884811],[15.5484549,60.7886636],[15.5483307,60.7888509],[15.5479833,60.7889067],[15.5474922,60.7889401],[15.5469378,60.7889362],[15.5459251,60.788795],[15.5458449,60.7886574],[15.5459266,60.7885385],[15.5461476,60.7884135],[15.5464063,60.7883313],[15.5468046,60.7882536],[15.5472083,60.7882476],[15.5476299,60.7882236]]]}', 0, 10, '2018-10-01T09:41:43+02:00', 'Riksantikvarieämbetet', '2026-11-17', '27c61ab6f38ca8f7f024069c8f53064f');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1340, '565fe788-357f-4167-a710-e231c9121b03', 'L1998:2612', 'Stora Kopparberg 591', 'stora kopparberg 591', 'Fossil åker', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fossil åker, oregelbunden, ca 45x20-40 m (NV-SÖ) st.  Avgränsad mot omgivande mark av röjningsrösen och intill 0,7 m h terrasskanter i SV, av svaga hak och röjningssten i NV. I SÖ och NÖ något oklar avgränsning. Hjulspår från skogsmaskin rakt över lämningen. Odlingsytan finns med på storskifteskartan (RAÄ dnr 321-4220-2009).', 'SV-sluttande stenig moränmark. Skogsmark, gles granskog.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6755065, 15.5101058, 527870.3, 6726752.8, 527841, 6726732, 527889, 6726774, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5095761,60.6755222],[15.5097733,60.6754866],[15.5100822,60.6754056],[15.5100263,60.6753688],[15.510176,60.6753193],[15.5104464,60.6754393],[15.5104357,60.6755432],[15.5103478,60.6756873],[15.5102752,60.6755901],[15.5101064,60.6756046],[15.5100908,60.6756555],[15.5098327,60.6756056],[15.5095761,60.6755222]]]}', 0, 10, '2018-10-01T12:20:13+02:00', 'Riksantikvarieämbetet', '2026-11-17', '61c4603e2d58582a302d3d8a6de0555d');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1343, '566b88bc-1f88-419f-985e-1c6b810db4d0', 'L2001:2144', 'Bjursås 138:1', 'bjursås 138:1', 'Gränsmärke', 'Fornlämning', 'Röset är varaktigt övergivet i sin ursprungliga funktion som markering av sockengränsen mellan Leksand och Bjursås.', 'Gränsmärke, stenröse, 2.7 m diam med 2 visare. Den S visar isiktning SSV och den N visar mot NNÖ. Visarna har en kronainristad på resp Ö sida. Inget årtal synligt. Gränsrösetmarkerar den tidigare gränsen mellan Leksands och Bjursås sn ochnumera markerar röset gränsen mellan skogsskiftet Liholen 1:3samt olika skiften hörande till Andersbo. UppgiftslämnareLars-Erik Westlund, Bjursås.Har även namnet: Kjällkjernbergs röset. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'V-sluttning av berg (Liholsberget), ca 100 m V om gångstig(NNÖ-SSV). Skogsmark (tall) moränmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7765137, 15.4413977, 524040.8, 6737975.7, 524040, 6737975, 524041, 6737976, 0, 'Point', '{"type":"Point","coordinates":[15.4413977,60.7765137]}', 0, 15, '2026-05-04T11:55:00.049+02:00', 'Länsstyrelsen Dalarna', '2026-11-17', '466fc4054690a4aef66369f0b67229ba');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1347, '56985a3a-7692-4d9f-b508-2a26cdef106b', 'L2023:5810', NULL, NULL, 'Bytomt/gårdstomt', 'Fornlämning', 'Redovisad på karta  från år 1827. Äldsta belägg för Gopa är från år 1539.', 'Gårdstomt, ca 55 x 45 m (ÖNÖ-VSV) bestående av minst 4 husgrunder. Tomten är övergiven. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1351, '57181daa-2ec4-4536-accb-27bef9e3bf2a', 'L2001:2130', 'Bjursås 125:1', 'bjursås 125:1', 'Boplats', 'Fornlämning', NULL, 'Boplats, synlig 12x3 m st (VNV-ÖSÖ), utgörande en liten sandstrand på NÖ delen av enflack moränudde i sjö, bestående av ett 10-tal hittade avslag av vit kvarts i vattenbrynet,vanligen under vattenytan, både Ö och V om brygga. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'NÖ-exponerad sandstrand på moränudde i sjö. Tomtmark (skogstomt).', 'Ö och V sidorna av brygga.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'I byggnad eller under vatten', 60.728902, 15.4926064, 526869.6, 6732692.6, 526862, 6732688, 526877, 6732698, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.4926912,60.728863],[15.492717,60.7288718],[15.4927357,60.7288878],[15.4927359,60.7288986],[15.4927033,60.7289132],[15.4926449,60.7289225],[15.4925318,60.7289446],[15.4924985,60.7289323],[15.4924874,60.7289234],[15.4924796,60.7289037],[15.4925486,60.7288799],[15.4926912,60.728863]]]}', 0, 10, '2018-10-01T09:43:11+02:00', 'Riksantikvarieämbetet', '2026-11-17', '018704b550fc10e4dd6a57aa2789c679');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1370, '57f6c8dc-c2f1-4950-8d07-7cf011b05471', 'L2001:1968', 'Bjursås 51:2', 'bjursås 51:2', 'Fäbod', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', '1) Fäbodlämning, 360x320 m st (N-S). Utsträckning enligt LMV-karta från 1808-11.Inom ett 120x120 m st område är rester av 1 stuga med spismursröse, 1 grund av enekonomibyggnad. 1 stuga och 9 ekonomibyggnader kvarstår liksom 1 jordkällare och 1 brunn.Inom tomtområdet finns 1 boningshus och 1 trösklada som uppförts senare.I det stenröjda området däromkring är ett 40-tal röjningsrösen, 5-10 m diam och 0.5-1.2 m h,samt stengärdesgårdar, diken, terrasskanter och åkerhak.10 m SSÖ om nr 1 är:2) Fäbodlämning, 750x50-300 m st (NNV-SSÖ). Utsträckning enligt LMV-karta från 1808-11. Inom området finns fem mindre bebyggelseområden, 30x30-100x40m st (NÖ-SV). Inomvarje bebyggelseområde har varit 1-2 stugor och 4-6 ekonomibyggnader. Totalt kvarstår 8ekonomihus och 2 stugor.30 m SV om nr 1 är:Fäbodlämning, 150x70 m st (NV-SÖ). Utsträckning enligt LMV-karta från 1808-11.70 m VSV om nr 2 är:4) Fäbodlämning 100x80 m st (NV-SÖ). Utsträckning enligt LMV-kartafrån 1808-11.Runt bebyggelseområdena är röjningsrösen, 3-12 m diam, 0.3-1 m h,samt diken, terrasskanteroch åkerhak. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'S-sluttande moränmark. Skogsmark (blandskog). F.d. vallområde.', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.8018725, 15.5730229, 531185, 6740855.5, 530978, 6740471, 531330, 6741200, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5711077,60.801825],[15.5719213,60.8019116],[15.5724668,60.8019962],[15.5727873,60.8018848],[15.5728936,60.801721],[15.5728598,60.8015364],[15.5729099,60.8013263],[15.5726381,60.8010176],[15.5723785,60.8009098],[15.5725185,60.8007744],[15.5727489,60.8007335],[15.5730877,60.8007745],[15.5732736,60.8007178],[15.5736447,60.8005721],[15.5739478,60.8003496],[15.5743155,60.8000622],[15.5745786,60.7998544],[15.5738588,60.8000022],[15.5732679,60.8000147],[15.5728339,60.7999869],[15.572358,60.8000489],[15.5721355,60.799957],[15.572336,60.7998966],[15.5722926,60.7997695],[15.5726469,60.7993835],[15.5730246,60.798897],[15.5735014,60.7988744],[15.5738764,60.7987394],[15.5742296,60.7986171],[15.5745022,60.7984988],[15.5748271,60.7984197],[15.5752285,60.7986236],[15.5753983,60.7988109],[15.5755284,60.7990325],[15.5756298,60.7994336],[15.5754584,60.801944],[15.5751136,60.8021111],[15.5746609,60.8022232],[15.5741767,60.8022459],[15.5737506,60.8022413],[15.5741753,60.802341],[15.5747254,60.8024632],[15.5755449,60.8026412],[15.5754879,60.8030218],[15.5752244,60.803522],[15.574817,60.8036877],[15.5741374,60.8036792],[15.5733666,60.8035422],[15.5727098,60.8034117],[15.5721316,60.8036519],[15.5715369,60.8038133],[15.5715551,60.8042724],[15.5715366,60.8047317],[15.5713402,60.804966],[15.5709897,60.8048982],[15.5706549,60.8047155],[15.5700647,60.8044536],[15.5695685,60.8041283],[15.5694387,60.803921],[15.5696325,60.8037298],[15.569834,60.8035564],[15.5694998,60.8033969],[15.5692477,60.8031456],[15.5693858,60.8029259],[15.5698298,60.802604],[15.5702467,60.8022176],[15.5706689,60.8017523],[15.5711077,60.801825]]]}', 0, 10, '2018-10-01T09:42:17+02:00', 'Riksantikvarieämbetet', '2026-11-17', '5ddb234ff8ebc8396483bc4349be4ea6');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1392, '59e65d7c-fe4b-45b3-8328-1b8101ffe0a0', 'L2023:7044', NULL, NULL, 'Uppfordringsanläggning', 'Fornlämning', 'Järnmalmsfyndigheten ska ha upptäckts år 1842 (tillkommit före år 1850).  Brytningen ska ha utförts genom krutsprängning (forna tiders bruk). Gruvan lades ned år 1873 (varaktigt övergiven).', 'Stånggångslämning, ca 520 m l (NNÖ-SSV) , bestående av 55 stångångsfundament. Stånggångsfundamenten är främst runda, ovala eller oregelbundna, 2-6 m st och 0,2-0,8 m h. Majoriteten av fundamenten är överväxta, övermossade. Där stenarna är synliga är de vanligtvis 0,1–0,4 m st, till synes brutna. Stånggångsfundamenten är belägna med ett inbördes avstånd av 3-10 m. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1395, '5a059329-41f7-488d-8a87-9ccb296a93fe', 'L2001:2209', 'Bjursås 40:1', 'bjursås 40:1', 'Naturföremål/-bildning med bruk, tradition eller namn', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Källa med namn.1994 bestod källan av en grop, 3 m diam och 1 m dj, med gyttjig botten, kantad avungbjörkar. Den har relativt nyligen grävts ut av Ernst Mattsson,Sörskog, som ocksåanför namnformen Hedningskällan (ej Hednakällan). Enligt Mattsson,ska en häst hadränkts i källan. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Bergkrön. Skogsmark (ung blandskog).', NULL, NULL, 'Hedningskällan', 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.8210112, 15.3849926, 520939.6, 6742912.5, 520939, 6742912, 520940, 6742913, 0, 'Point', '{"type":"Point","coordinates":[15.3849926,60.8210112]}', 0, 30, '2018-10-01T09:43:39+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'daf434b6cd60316f0315f386f62b4c97');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1408, '5a9fdac9-6e42-45a4-a506-58ee4a01e617', 'L2000:9263', 'Stora Kopparberg 15:1', 'stora kopparberg 15:1', 'Gränsmärke', 'Övrig kulturhistorisk lämning', NULL, 'Gränsröse, 15-2 m diam och ca 0.5 m h av lagda gråstenar 0.3-0.5m st med ett större block i NV. I mitten finns en ca 0.5 m hpinne av trä. Rösets kanter är kallmurade intill 3 skift.Övermossat. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'SV-sluttning av bergs- och moränhöjd ned mot sjö. Skogsmark,(barrskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7360277, 15.530892, 528951.5, 6733502.5, 528951, 6733502, 528952, 6733503, 0, 'Point', '{"type":"Point","coordinates":[15.530892,60.7360277]}', 0, 15, '2018-10-01T11:12:02+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'a33829029d3e23bf77e04380133a10c2');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1417, '5b7fb7ad-e151-450f-a90e-68d9120241ff', 'L1998:2112', 'Stora Kopparberg 609', 'stora kopparberg 609', 'Bytomt/gårdstomt', 'Fornlämning', NULL, 'Gårdstomt ca 90x55 m (NÖ-SV), bestående av minst 1 grund efter boningshus och 3 uthusgrunder samt 1 grund efter smedja. Husgrunderna ligger i N delen av området och den ev. smedjan i SV. Boningshusgrunden är can 7x5 m (NÖ-SV) med spisröse i NV hörnet, 2 m diam och 0,4 m h. Utanför NÖ kortsidan är en källargrop. De andra husgrunderna är 10x6 m  (NNV-SSÖ) resp. 8x5 m (Ö-V). SV om boningshuset är grunden efter en jordkällare 10x8 m (VSV-ÖNÖ). Äldsta namnbelägg: Boosarvet 1411, DD 1 (Ståhl, H. 1960)
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1421, '5bc0fd08-54b1-48d8-9c5e-cd0d2b7b6dd2', 'L2001:1835', 'Bjursås 45:1', 'bjursås 45:1', 'Boplats', 'Fornlämning', NULL, 'Boplats, ca 90x50-65 m st (Ö-V), bestående av avslag av  vit kvarts i hela åkern, rikligt på krönplatån i N kanten, där hästar sparkat bort torven, vilken i övrigt döljer jorden. Fyra avslag tillvaratogs, varav ett retuscherat troligen utgör en skrapa.', 'Krönplatå och svaga S- och V-sluttningar av flack sedimenthöjd. Åkermark.', 'Omedelbart N om sjö.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Ej synlig ovan mark', 60.69066, 15.4223892, 523067, 6728406.6, 523025, 6728381, 523112, 6728438, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.42314,60.6905855],[15.4230737,60.6906625],[15.4230186,60.6907271],[15.4229634,60.6907898],[15.4229156,60.6908256],[15.4228752,60.6908579],[15.422758,60.6908829],[15.4224945,60.690897],[15.4223151,60.690922],[15.4221065,60.6909397],[15.4219967,60.6909325],[15.4219202,60.690866],[15.4218182,60.690769],[15.4217381,60.6906972],[15.421669,60.6906092],[15.4216218,60.690541],[15.4216257,60.6904944],[15.4217832,60.6904389],[15.4219991,60.6904445],[15.42216,60.690468],[15.4223319,60.6904699],[15.4225552,60.6904486],[15.4227565,60.6904416],[15.4228992,60.6904435],[15.4230637,60.6904598],[15.423166,60.6904922],[15.4231952,60.6905191],[15.42314,60.6905855]]]}', 0, 10, '2018-10-01T09:41:33+02:00', 'Riksantikvarieämbetet', '2026-11-17', '6a9258029d92382e67f25536e6bfce99');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1422, '5bea829b-b6db-4847-8fda-9a1e28260b29', 'L2001:1413', 'Bjursås 80:1', 'bjursås 80:1', 'Fäbod', 'Fornlämning', 'Äldsta belägg från 1700-talet.', 'Fäbodlämning, ca 465 x 70-140 m st (NÖ-SV), bestående av minst 12 husgrunder, 2 ruiner, 1 källa, ca 15 åkertegar samt 6 röjningsrösen. Husgrunderna, är 4-7 x 7-9 m och intill 0,7 m h. En utgörs endast av hörnstenar, en har spisröse. Ruinerna, är 3 x 3 respektive 5 x 4 m st, bevarade upp till 12 respektive 5 stockvarv. Källan, är 1 m diam och 0.5 m dj till vattenyta, med stensatt schakt, övertäckt av trälock. Åkertegarna, är skiftande block- och bandformiga, 20-70 x 3-27 m st. De avgränsas i S av intill 1,3 m h terrasseringar. Röjningsrösena, är 5-15 m stora och intill 0.8 m h. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1437, '5cd36eb2-6a4c-40ad-80b0-b26ea883c556', 'L2024:1257', NULL, NULL, 'Kolningsanläggning', 'Möjlig fornlämning', 'Den 0,6 m kraftiga tallen på lämningen antyder att den kan härröra från tiden före 1850.', 'Kolbotten, oregelbundet rund, 10 m diam och intill 1 m h. Bevuxen med granar och en 0,6 m grov tall.', 'Kulle i N-sluttande moränmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.8528139, 15.4757579, 525850.6, 6746487, 525850, 6746487, 525851, 6746488, 0, 'Point', '{"type":"Point","coordinates":[15.4757579,60.8528139]}', 0, 30, '2024-04-17T09:30:56.514+02:00', 'länsstyrelsen', '2026-11-17', 'c7fb66d3c73eb41ff9bcbcf6befe7814');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1441, '5d234f5c-33dc-4e08-bfa4-d9373e8f4044', 'L2024:786', NULL, NULL, 'Färdväg', 'Övrig kulturhistorisk lämning', NULL, 'Färdväg, del av, L71 m, B 1,8 m. Brukningsspår från modern tid. Färdvägen utgör en del av den gamla färdvägen mellan Finnbo och Marnäs.', 'Flack moränmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.8335734, 15.5343183, 529049.9, 6744368.5, 529028, 6744340, 529072, 6744396, 0, 'LineString', '{"type":"LineString","coordinates":[[15.5347027,60.8338079],[15.534714,60.8338155],[15.5343104,60.8335726],[15.533919,60.8333212]]}', 0, 25, '2024-03-15T09:34:33.506+01:00', 'länsstyrelsen', '2026-11-17', '644512ccab408c0c7ce34033e92c6c57');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1448, '5dabc7b5-a07d-4053-944e-aed3a941ae82', 'L2024:775', NULL, NULL, 'Färdväg', 'Övrig kulturhistorisk lämning', NULL, 'Färdväg, del av, L80 m, B 1,8 m. Brukad med fyrhjuling i modern tid. Färdvägen utgör en del av den gamla färdvägen mellan Finnbo och Bjursås.', 'Flack morän- och sedimentmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Åverkan', 'Ej undersökt', 'Synlig ovan mark', 60.8330545, 15.5326207, 528958.1, 6744310, 528918, 6744307, 528998, 6744315, 0, 'LineString', '{"type":"LineString","coordinates":[[15.5333372,60.833087],[15.533341,60.8330885],[15.5333368,60.8330896],[15.5329274,60.833046],[15.5325377,60.8330313],[15.5321349,60.8330664],[15.5318936,60.8330641],[15.5318924,60.8330628]]}', 0, 25, '2024-03-14T11:49:35.719+01:00', 'länsstyrelsen', '2026-11-17', 'd66f29b4b58568bf49e598d172470379');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1458, '5e06ac27-0c5e-4a70-8b77-8531dfd590c3', 'L2023:6284', NULL, NULL, 'Bytomt/gårdstomt', 'Fornlämning', 'Övergiven gårdstomt redovisad på karta från år 1819. Ytterligare lämningar kan förekomma dolda under mark. Limbo var tidigare en byklunga till Sågsbo. Äldsta skriftliga belägg för Sågsbo är 1588 med två hemmansägare. 1639 fanns åtta hemmansägare.', 'Gårdstomt, ca 30 x 30(NNÖ-SSV) bestående av minst 2 husgrunder. Tomten är övergiven.
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1460, '5e2c3e31-cda3-4f71-8f3f-199dbb62f04f', 'L2001:2287', 'Bjursås 61:1', 'bjursås 61:1', 'Fäbod', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fäbodlämning, 80x50 m st (NNV-SSÖ). Centralt inom området är rester efter 1 stuga medspismursröse och grunder av 2 ekonomibyggnader.Runt tomtområdet är ett 10-tal röjningsrösen, 3-5 m diam och 0.3-0.7 m h. Inom området äräven spår av kolbottnar.Hela området är beväxt med barrskog. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', NULL, NULL, 'Enligt en sägen togs här en fäbodjänta, Bladbergs-Britta av trollen. (Enligt Ingrid Göras,Fjällgrycksbo).', NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.818182, 15.5665039, 530814.5, 6742668.9, 530786, 6742631, 530845, 6742706, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.566298,60.8178836],[15.5664918,60.8178465],[15.5668393,60.8179341],[15.5670454,60.8181069],[15.5670379,60.8182522],[15.5668283,60.8184041],[15.5665515,60.8185062],[15.5662866,60.8184917],[15.5660228,60.8183641],[15.5659959,60.8181616],[15.5661705,60.8179291],[15.566298,60.8178836]]]}', 0, 10, '2018-10-01T09:44:04+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'd27e3bd1599a231a4a38979bef1e2865');
