INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1474, '5f389a71-026c-4688-8f20-e3f17e4e6a96', 'L2001:2131', 'Bjursås 34:1', 'bjursås 34:1', 'Fornlämningsliknande bildning', 'Ej kulturhistorisk lämning', NULL, 'Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Flack sjöstrand. Skogsmark (blandskog).B. Älvkvarnsliknande naturbildning, i stenhäll, (ÖNÖ-VSV), 4x2 m st och 0.6 m h, avgrå gnejs. I hällen finns ett 80-tal grunda gropar, vanligen 0.1 mdiam och 0.05-0.15 m dj.Stenhällen är kraftigt övermossad.', 'Omedelbart intill sjöstrand (Ö-V), 25 m 330 gon om härbres N gavel.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7112158, 15.4445273, 524260.5, 6730704, 524260, 6730704, 524261, 6730705, 0, 'Point', '{"type":"Point","coordinates":[15.4445273,60.7112158]}', 0, 30, '2018-10-01T09:43:11+02:00', 'Riksantikvarieämbetet', '2026-11-17', '3ad7454ecbd30c1cb3353b80143e9a72');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1475, '5f5770a6-ee7e-4650-ab17-223e233e2005', 'L1998:107', 'Leksand 1518', 'leksand 1518', 'Fäbod', 'Fornlämning', NULL, 'Fäbodlämning 145 x 10-95 m (NÖ-SV) bestående av 10 husgrunder, minst 2 fossila åkrar samt 28 röjningsrösen och minst 1 röjd yta. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1484, '5fde09d1-9b9f-41d1-bb3a-13c9ecb4148f', 'L1999:526', 'Stora Kopparberg 348:1', 'stora kopparberg 348:1', 'Brott/täkt', 'Övrig kulturhistorisk lämning', NULL, 'Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', NULL, NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.651842, 15.5437612, 529730.9, 6724131.9, 529702, 6724110, 529762, 6724157, 0, 'GeometryCollection', '{"type":"GeometryCollection","geometries":[{"type":"LineString","coordinates":[[15.5439799,60.6517337],[15.5439943,60.6517982],[15.5440637,60.6518181],[15.5441149,60.6518146],[15.5441296,60.6517824],[15.5440786,60.6517232],[15.5440166,60.6517087],[15.5439727,60.6517247],[15.5439799,60.6517337]]},{"type":"Polygon","coordinates":[[[15.544046,60.6516496],[15.5441629,60.6516624],[15.5442685,60.6517738],[15.5443194,60.6518348],[15.544301,60.6518688],[15.5441803,60.6519008],[15.544056,60.6519095],[15.543855,60.6519144],[15.5436354,60.6520035],[15.5435768,60.652041],[15.5434561,60.6520623],[15.5433795,60.652037],[15.5432665,60.6519471],[15.5432339,60.6518646],[15.5433036,60.6518164],[15.5435779,60.6517399],[15.5438852,60.6516725],[15.544046,60.6516496]]]}]}', 0, 10, '2018-10-01T11:21:32+02:00', 'Riksantikvarieämbetet', '2026-11-17', '7b7bf298cba366ce360f599b2e9985eb');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1487, '5fff9e5b-252e-4ea7-a20f-0da22ec7afc5', 'L2001:715', 'Bjursås 30:1', 'bjursås 30:1', 'Källa med tradition', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Trefaldighetskälla, stensatt, rektangulär, 0.5x0.4 m st (VNV-ÖSÖ)och 0.3 m dj,varav 0.1 m vatten. Avrinner mot NNÖ i ett dike mellan åkrar. 2 mmot NNÖ är ensekundär, träfodrad källa.1m N om källan är en björk. Omnämnd i orten, och i mannaminne använd somtrefaldighetskälla. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Mot NNÖ måttligt sluttande åkermark.', '14 m 230 gon om järnväg på en punkt 24 m 330 gon tomtgräns mot åker. I åkerkantmed stig (NNV-SSÖ).', NULL, 'Björkkällan', 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7098802, 15.2996864, 516356.4, 6730510.5, 516356, 6730510, 516357, 6730511, 0, 'Point', '{"type":"Point","coordinates":[15.2996864,60.7098802]}', 0, 15, '2018-10-01T09:35:09+02:00', 'Riksantikvarieämbetet', '2026-11-17', '5c8a824929b46c71978981cff9b4dfb7');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1501, '60ebfe67-5aca-4da3-acc3-5e476392a927', 'L2001:1487', 'Bjursås 80:3', 'bjursås 80:3', 'Fäbod', 'Ingen antikvarisk bedömning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', '1) Fäbodlämning, 440x70-130 m st (NÖ-SV), bestående av 12 husgrunder, 2 ruiner, 1källa, ca 15 åkertegar samt 5 röjningsrösen.Husgrunderna, är 4-7x7-9 m och intill 9.7 m h. En utgörs endast avhörnstenar, en har spisröse.Ruinerna, är 3x3 respektive 5x4 m st, bevarade upp till 12 respektive 5 stockvarv.Källan, är 1 m diam och 0.5 m dj till vattenyta, med stensatt schakt.Åkertegarna, är skiftande block- och bandformiga, 20-70x3-27 m st.De avgränsas i S av intill1 m h terrasseringar.Röjningsrösena, är 5-7 m diam och intill 0.6 m h.1994 var 3 stugor och 1 bod iståndhållna, men knappast brukade, möjligen som jaktstugor.Skogsbilvägen som dragits genom fäbodstället har skadat framför allt den fossila åkermarken.Uppgift om äldsta belägg saknas.20 m SÖ om NÖ delen av nr 1 är:2) Fäbodlämning, 30-150x20-130 m st Ö-V). Utsträckning enligt storskifteskarta från 1822-25.60 m SSÖ om nr 2 är:3) Fäbodlämning, 70x20 m st (NV-SÖ. Utsträckning enligt storskifteskarta från 1822-25.40 m V om nr 3 är:4) Fäbodlämning, 30x10 m st (NNÖ-SSV). Utsträckning enligt storskifteskarta från 1822-25.15 m S om SV delen av nr 1 är:5) Fäbodlämning, 110-260x10-110 m st (ÖNÖ-VSV). Utsträckning enligt storskifteskarta från1822-25.25 m SSÖ om nr 5 är:6) Fäbodlämning, 30x20 m st (ÖNÖ-VSV). Utsträckning enligt storskifteskarta från 1822-25. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'S-sluttning högt upp på bergs- och moränhöjd på N sidan av huvuddalgång. Skogsmark(blandskog samt hyggge).', NULL, NULL, NULL, 'Uppgift om lämning, ej bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.8315696, 15.4584927, 524929, 6744114.1, 524900, 6744078, 524960, 6744151, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.4582559,60.8318965],[15.4579638,60.8318018],[15.4580873,60.831691],[15.4582445,60.8315535],[15.4585129,60.8313716],[15.4587285,60.8312505],[15.4590422,60.8313741],[15.4582559,60.8318965]]]}', 0, 10, '2018-10-01T09:39:30+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'edc9015431f561cb71b81de7fe36761f');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1507, '615c747f-79c6-45d2-abb7-eef9ebea9b53', 'L2023:7038', NULL, NULL, 'Småindustriområde', 'Fornlämning', 'På en karta från år 1819 syns 2 mindre dammspeglar, på en karta från år 1828 syns två kvarnsymboler. På generalstabskarta från år 1899 syns 1 kvarnsymbol.', 'Småindustriområde ca 75 x 35 m (NNV-SSÖ) bestående av minst 2 dammvallar, 2 kvarngrunder och 1 husgrund 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1510, '6175e71b-d50f-4f51-8c76-2ddcdee3e38e', 'L1998:2533', 'Stora Kopparberg 598', 'stora kopparberg 598', 'Fossil åker', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fossil åker, ca 40x20 m (Ö-V) st. Avgränsad mot omgivande mark av intill 1 m h terrasskant i V, samt av hak i S och Ö. Något diffus avgränsning i N. Odlingsytan finns med på storskifteskartan (RAÄ dnr 321-4220-2009).', 'V-sluttande stenig moränmark. Skogsmark, lövskog med inslag av gran.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6757465, 15.5114795, 527945.1, 6726780.1, 527923, 6726767, 527965, 6726791, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5115014,60.6756503],[15.51175,60.6756305],[15.5118272,60.6757618],[15.5117743,60.675804],[15.5116409,60.675819],[15.511393,60.6758404],[15.511086,60.675819],[15.5111064,60.6757356],[15.5115014,60.6756503]]]}', 0, 10, '2018-10-01T12:19:55+02:00', 'Riksantikvarieämbetet', '2026-11-17', '547a5f0e4202a4837343f4f7c08d2f18');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1512, '618d4390-9785-4a3b-aa6e-29ccfc5c7a0d', 'L2001:2252', 'Bjursås 51:3', 'bjursås 51:3', 'Fäbod', 'Ingen antikvarisk bedömning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', '1) Fäbodlämning, 360x320 m st (N-S). Utsträckning enligt LMV-karta från 1808-11.Inom ett 120x120 m st område är rester av 1 stuga med spismursröse, 1 grund av enekonomibyggnad. 1 stuga och 9 ekonomibyggnader kvarstår liksom 1 jordkällare och 1 brunn.Inom tomtområdet finns 1 boningshus och 1 trösklada som uppförts senare.I det stenröjda området däromkring är ett 40-tal röjningsrösen, 5-10 m diam och 0.5-1.2 m h,samt stengärdesgårdar, diken, terrasskanter och åkerhak.10 m SSÖ om nr 1 är:2) Fäbodlämning, 750x50-300 m st (NNV-SSÖ). Utsträckning enligt LMV-karta från 1808-11. Inom området finns fem mindre bebyggelseområden, 30x30-100x40m st (NÖ-SV). Inomvarje bebyggelseområde har varit 1-2 stugor och 4-6 ekonomibyggnader. Totalt kvarstår 8ekonomihus och 2 stugor.30 m SV om nr 1 är:Fäbodlämning, 150x70 m st (NV-SÖ). Utsträckning enligt LMV-karta från 1808-11.70 m VSV om nr 2 är:4) Fäbodlämning 100x80 m st (NV-SÖ). Utsträckning enligt LMV-kartafrån 1808-11.Runt bebyggelseområdena är röjningsrösen, 3-12 m diam, 0.3-1 m h,samt diken, terrasskanteroch åkerhak. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'S-sluttande moränmark. Skogsmark (blandskog). F.d. vallområde.', NULL, NULL, NULL, 'Uppgift om lämning, ej bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.8042442, 15.5665901, 530832.6, 6741116.6, 530784, 6741070, 530903, 6741191, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5662831,60.8038772],[15.566697,60.8038335],[15.5670788,60.8038276],[15.5674576,60.8038505],[15.5677446,60.803872],[15.567861,60.8039808],[15.5678454,60.8040974],[15.5676999,60.8041593],[15.5674149,60.8042166],[15.5672369,60.804302],[15.5671214,60.8043888],[15.5669551,60.8044974],[15.5667408,60.8046009],[15.5665077,60.804683],[15.5662855,60.8047579],[15.5661,60.8048361],[15.5659366,60.8049142],[15.5657832,60.804795],[15.5657173,60.8046483],[15.565784,60.8045187],[15.5658465,60.8043641],[15.5657327,60.8042124],[15.5657035,60.8040619],[15.565891,60.8039173],[15.5661254,60.8038907],[15.5662831,60.8038772]]]}', 0, 10, '2018-10-01T09:43:53+02:00', 'Riksantikvarieämbetet', '2026-11-17', '1588c6ba76e3fff7d838737c74f359c0');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1519, '61f745e5-7cf2-4e89-a100-7e38cdd7c593', 'L2023:7054', NULL, NULL, 'Husgrund, historisk tid', 'Övrig kulturhistorisk lämning', NULL, 'Husgrund, 10 x 5,5  m (V-Ö) och 0,2-0,8 m h av kallmurade huggna stenar.
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1523, '6248953f-facd-42ab-86fe-f99ca2dbe927', 'L2023:5876', NULL, NULL, 'Bytomt/gårdstomt', 'Fornlämning', 'På storskifteskarta från år 1827 är en kringbyggd gård med 4 byggnader redovisad.
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1530, '62ae336d-eb0f-4124-a518-9e8c3a059790', 'L2023:1145', NULL, NULL, 'Brott/täkt', 'Övrig kulturhistorisk lämning', NULL, 'Täkt, närmast rektangulär, 5,7x2,5-2,7 m (NV-SÖ) och 0,3-0,5 m dj. Längs med NÖ långsidan är en vall, delvis övertorvad, 1,2-1,5 m br och intill 0,2 m h. I denna är enstaka synliga stenar 0,2-0,4 m st. I NV kanten är ett markfast block, 1,5x1,1 m och intill 0,5 m h.', 'N-sluttande, ställvis hällbunden storblockig morän. Skogsmark, hygge med uppväxande tallskog.', '2 m ÖSÖ om drivningsväg (NNÖ-SSV).', NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6386623, 15.5456576, 529846.8, 6722664.9, 529846, 6722664, 529847, 6722665, 0, 'Point', '{"type":"Point","coordinates":[15.5456576,60.6386623]}', 0, 30, '2023-04-05T13:36:05.044+02:00', 'STIFTELSEN DALARNAS MUSEUM', '2026-11-17', 'e58338b6bb9116abc75fcfc346367c96');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1532, '62e41de4-5807-45a3-b7c7-cb3265a2b601', 'L2023:6853', NULL, NULL, 'Kvarn', 'Fornlämning', 'På 1819 års karta syns en kvarnplats här.', 'Kvarnlämning, inom ett område av ca 30 x 17 m (NV-SÖ) bestående av 1 dammvall,  1 kvarngrund, 1 husgrund samt 1 kvarnhjul. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1547, '63dd4798-bbdc-49f5-9778-01ae144496c0', 'L2023:6893', NULL, NULL, 'Kolningsanläggning', 'Övrig kulturhistorisk lämning', NULL, 'Kolbotten efter liggmila, rektangulär 10 x 8 m (N-S) och intill 0,9 m h med kring kanten otydliga stybbgropar.', 'S sluttande moränmark intill myndre myrmark. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1549, '6409f136-3406-465e-bc97-17626bcb86f9', 'L2023:7036', NULL, NULL, 'Område med skogsbrukslämningar', 'Övrig kulturhistorisk lämning', NULL, 'Område med skogsbrukslämningar 30 x 20 ( VSV-ÖNÖ), bestående av 2 kolbottnar efter liggmilor. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1556, '648af34b-859c-42d6-9361-9bc23ded3e96', 'L2025:6120', NULL, NULL, 'Brott/täkt', 'Övrig kulturhistorisk lämning', NULL, 'Täkt, halvcirkelformad, ca 20x30 m och intill 10 m dj. Öppning åt SÖ. Ingrävd i ravin/sänka. Ett flertal mindre täktgropar finns i närområdet.', 'Nedre delen av ett krön eller ravin. Skogsmark, hagmark och åkermark omkring.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7435622, 15.4590677, 525028.8, 6734312.2, 525016, 6734298, 525046, 6734327, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.4591012,60.7434382],[15.4588654,60.7434591],[15.4588364,60.7435849],[15.4589403,60.7436699],[15.4590945,60.7436895],[15.4593803,60.743578],[15.4591012,60.7434382]]]}', 0, 10, '2025-11-07T13:01:58.217+01:00', 'STIFTELSEN DALARNAS MUSEUM', '2026-11-17', '6a1de1d947b9d8c00553ef045e28b8a1');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1558, '64a43579-cd66-45aa-a5af-44e87bce27be', 'L2001:1818', 'Bjursås 129:1', 'bjursås 129:1', 'Bro', 'Fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Stenvalvsbro, 8x4 m st (NNÖ-SSV) och 2 m h. Ett spann, 3 m l och1.5 m h, avkallmurade block. Ej i trafik. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Körväg i svagt SÖ-sluttande, stenig bäckravin (NV-SÖ). Skogsmark(lövskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7494732, 15.4817155, 526258.8, 6734979.4, 526258, 6734979, 526259, 6734980, 0, 'Point', '{"type":"Point","coordinates":[15.4817155,60.7494732]}', 0, 20, '2018-10-01T09:41:28+02:00', 'Riksantikvarieämbetet', '2026-11-17', '06de536c44836cf957699c023ebfabe6');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1559, '64c91e90-88cf-4d4a-9aaf-f8338bb57e62', 'L2024:1231', NULL, NULL, 'Fångstgrop', 'Fornlämning', NULL, 'Kolningsgrop (?), oval, 1 x 1,5 m och 0,4 m dj, omgiven av en vall, 1,5 – 2 m br och intill 0,3 m h. Rektangulärt bottenplan. Vid provstick framkom sot och kol. Bevuxen med granar.', 'Terrasskant i NO-sluttande moränmark vid bäck.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.8533906, 15.4777496, 525958.3, 6746552, 525958, 6746552, 525959, 6746553, 0, 'Point', '{"type":"Point","coordinates":[15.4777496,60.8533906]}', 0, 30, '2024-04-15T18:44:39.876+02:00', 'länsstyrelsen', '2026-11-17', '9dd20c042596f4f7b2f1b9edc11b530b');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1564, '6540d796-1370-4f64-925b-0d5ec623cf65', 'L2001:2267', 'Bjursås 88:2', 'bjursås 88:2', 'Fäbod', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', '1) Fäbodlämning, 80x50 m st, (NV-SÖ), bestående av 2 hus, 1 ruinsamt 2 husgrunder.Ruinen, är bevarad upp till taket. Av husgrunderna är den ena, 7x5m st, med spisröse. Troligenstuga. Den andra ligger avskilt i skogen, 4x4 m st och med stort spisröse, 2x1 m st. Troligentorkstuga.Ca 75 m SSÖ om nr 1 är:2) Fäbodlämning, 50x35 m st (NNV-SSÖ), bestående av 1 vagnslider och 3 husgrunder.Husgrunderna, är 4-5x5-9 m st, en har spisröse.Enligt Claes Frisk, ca 60 år, Rällsjöbo, användes dessa gårdar somfäbodar av Rällsjöbo(Matses och Prinsens). På storskifteskartan är åkrarna men inte gårdarna medtagna, varfördessa bör vara tillkomna efter 1819-26. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', NULL, NULL, NULL, 'Prinsens änge', 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7809477, 15.2851423, 515528.2, 6738422.4, 515511, 6738398, 515547, 6738447, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.2848694,60.7811018],[15.2848324,60.7810011],[15.2848428,60.7809079],[15.2848631,60.7808489],[15.2849426,60.780776],[15.285017,60.7807444],[15.285142,60.7807347],[15.2852879,60.7807592],[15.2853785,60.7807923],[15.2854715,60.7808648],[15.2854799,60.780942],[15.2854712,60.7809849],[15.2854066,60.7810508],[15.2853465,60.7810933],[15.2851757,60.7811582],[15.2850214,60.7811659],[15.2848694,60.7811018]]]}', 0, 10, '2018-10-01T09:43:58+02:00', 'Riksantikvarieämbetet', '2026-11-17', '18a0f53faaf65efa9aea967de523a1f7');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1590, '66736f70-fb80-4f3a-b6ef-94caeceed672', 'L2001:952', 'Bjursås 82:3', 'bjursås 82:3', 'Fäbod', 'Övrig kulturhistorisk lämning', NULL, 'Fäbodområde till Granåsens fäbodar, 210x180 m st (NV-SÖ). Utsträckning  för del av inägomarken enligt storskifteskarta från 1822-25. Det angivna området har bestått av slog och betesmark.', 'N-sluttning av bergshöjd. Skogsmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.8481588, 15.4727925, 525693.2, 6745967.4, 525582, 6745872, 525797, 6746057, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.4709829,60.8477125],[15.471205,60.8478231],[15.4714423,60.8479122],[15.4716948,60.8479762],[15.4719962,60.8479848],[15.4722391,60.8479787],[15.4724634,60.8479672],[15.4726669,60.8479197],[15.4728304,60.8478306],[15.4730678,60.8476727],[15.473433,60.8474922],[15.4736665,60.8474017],[15.4738259,60.847336],[15.4740719,60.8472991],[15.4743705,60.8475091],[15.4744278,60.8475848],[15.4745014,60.8477683],[15.474575,60.8479536],[15.4746876,60.8482074],[15.4744615,60.8482979],[15.4740039,60.8483766],[15.4735616,60.8484248],[15.4734027,60.8484636],[15.4731757,60.8485972],[15.472933,60.8487775],[15.4726168,60.8489574],[15.4720169,60.8487948],[15.4716692,60.8487088],[15.4714566,60.8486737],[15.4711514,60.8486669],[15.4709476,60.848375],[15.4708769,60.848046],[15.4708171,60.8479129],[15.470743,60.8477864],[15.4709829,60.8477125]]]}', 0, 10, '2024-04-17T16:12:38.645+02:00', 'länsstyrelsen', '2026-11-17', 'da16e23c403c811b7b6115533e3a787c');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1593, '66d4d78c-a404-49a3-b083-9cd4e439995b', 'L2023:5687', NULL, NULL, 'Bytomt/gårdstomt', 'Ingen antikvarisk bedömning', NULL, 'Uppgift om gårdstomt, ca 35 x 25 m (ÖNÖ-VSV) enligt utsträckning på storskifte år 1827. Tomten är övergiven. På storskifteskarta från år 1827 är en kringbyggd gård med 4 byggnader redovisad. Vid besök iakttogs inga synliga lämningar ovan mark.', 'SSÖ-sluttande moränmark.', NULL, NULL, NULL, 'Uppgift om lämning, ej bekräftad i fält', 'Åverkan', 'Ej undersökt', 'Ej synlig ovan mark', 60.7245986, 15.3466543, 518911.1, 6732162.4, 518893, 6732146, 518925, 6732175, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.3468915,60.7247056],[15.3468648,60.7246496],[15.3467648,60.7244627],[15.346711,60.7244546],[15.3466578,60.7244926],[15.3464973,60.7245472],[15.3463352,60.7246122],[15.3465356,60.7246753],[15.3467338,60.7246978],[15.3468915,60.7247056]]]}', 0, 10, '2023-10-12T11:10:42.592+02:00', 'Länsstyrelsen Dalarna', '2026-11-17', 'c96c28bce7e7d6e6b8913ec24561bf0e');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1598, '6712336b-3537-4a09-8a8d-c243b5a17551', 'L2023:6660', NULL, NULL, 'Husgrund, historisk tid', 'Övrig kulturhistorisk lämning', NULL, 'Husgrund, efter jordkällare, kvadratisk, 6 x 6 m (VNV-ÖSÖ) och 0,4-1,6 m h. Kallmurad med välvt tak och ingång, ca 1 m br, åt ÖSÖ.', 'NÖ sluttande moränmark. skogsmark (ung blandskog).', 'Direkt NNV om väg.', NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7703966, 15.3777938, 520580.5, 6737272.7, 520580, 6737272, 520581, 6737273, 0, 'Point', '{"type":"Point","coordinates":[15.3777938,60.7703966]}', 0, 25, '2023-11-06T15:47:26.655+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', '17637925bc2041cce587f7226e1fe086');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1607, '67daa7fd-ce1f-4c67-97fd-db9eeda9bc27', 'L2001:2103', 'Bjursås 123:2', 'bjursås 123:2', 'Fyndplats', 'Övrig kulturhistorisk lämning', NULL, '1) Boplats, ca 20x4-8 m st (NV-SÖ), bestående av ett stenigt strandplan med småsandytor och en smal, övertorvad moränplatå ovan ett ca 1 m h strandhak.  På sandytorna ivattenbrynet hittades fem-sex avslag och på kanten av platån två avslag, alla av vit kvarts. Ihaket syns spridd skärvsten och ställvis svart jord.Ca 35 m NNV om nr1 är:2) Fyndplats, för ett avslag av vit kvarts på en liten sandstrand. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Liten, SV-exponerad moränudde i sjö. Skogsmark (övervägande tallskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7420142, 15.5148355, 528070.7, 6734162.3, 528070, 6734162, 528071, 6734163, 0, 'Point', '{"type":"Point","coordinates":[15.5148355,60.7420142]}', 0, 30, '2018-10-01T09:43:01+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'f1bb1875b212e1024ddb9b3821ee3e29');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1621, '68e525be-0999-4b5a-8d28-53ce9c1a2cd8', 'L2023:6748', NULL, NULL, 'Kvarn', 'Ingen antikvarisk bedömning', NULL, 'Uppgift om kvarnplats. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1622, '68e70b6d-f791-4f48-b201-36ef141d84b3', 'L1998:112', 'Stora Kopparberg 555', 'stora kopparberg 555', 'Kolningsanläggning', 'Övrig kulturhistorisk lämning', NULL, 'Kolbotten efter resmila, rund, 11 m diam, med nedsänkt plan botten. Runt om är en stybbvall, 1,5 m br och 0,2-0,4 m h. I NNÖ och NV är flacka täktgropar. (RAÄ dnr 326-214-2005)', 'Kuperad blockig moränmark. Skogsmark (tall).', '20 m ÖSÖ om stig.', NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6363847, 15.5409088, 529589.1, 6722409.1, 529589, 6722409, 529590, 6722410, 0, 'Point', '{"type":"Point","coordinates":[15.5409088,60.6363847]}', 0, 30, '2018-10-01T12:09:16+02:00', 'Riksantikvarieämbetet', '2026-11-17', '24f5efac4eb601b9d13249565f3ae9ec');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1638, '69e5f883-fcd1-4666-a0eb-c958fb649237', 'L2000:8275', 'Stora Kopparberg 86:1', 'stora kopparberg 86:1', 'Brott/täkt', 'Övrig kulturhistorisk lämning', NULL, 'Område med kvartsbrytning, ca 10x7 m (Ö-V), bestående av 1kvartsbrott och 1 skrotstensvarp.Kvartsbrottet är oregelbundet, ca 5x3 m (NNV-SSÖ), 0.7-2 m dj. Ibotten övermossad, nedrasad sten.ÖNÖ därom är ett varp, rikt på krossad vit kvarts.Ca 45 m S om kvartsbrott är ett mindre kvartsbrott (-försök?). Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'ÖNÖ-sluttning av berg, blockig moränmark. Skogsmark (hyggesplöjtkalhygge).', 'Ca 80 m ÖSÖ om Ö deln av vändplan och i anslutning till 3utspakade träd på kalhygge.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.684254, 15.5700336, 531136, 6727754, 531132, 6727750, 531139, 6727758, 0, 'LineString', '{"type":"LineString","coordinates":[[15.5700352,60.6842203],[15.5699913,60.6842292],[15.5699765,60.6842472],[15.570002,60.6842687],[15.5700276,60.6842849],[15.5700788,60.6842814],[15.5700863,60.6842599],[15.5700608,60.6842365],[15.5700352,60.6842203]]}', 0, 10, '2018-10-01T11:07:04+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'b72dd09447fecdd0451bdf9cee1be233');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1642, '6a2f39eb-de67-4803-a55c-9609926e7335', 'L2001:2058', 'Bjursås 60:1', 'bjursås 60:1', 'Fäbod', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fäbodlämning, 170x120 m st (N-S). I områdets N del är rester av 1grund medspismursröse, 1 jordkällare, 1 jordkoja och 3 grunder av ekonomibyggnader. Det stenröjdavallområdet är helt barrskogsbeväxt. Här finns ett flertal grundadiken.Enligt uppgift skall en ensam man ha bott här permanent (efter fäbodtiden) ända in på 1980-talet. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'S-sida av blockrik moränhöjd mot myrmark. Skogsmark (barrskog).', NULL, NULL, 'Bjursås-Kölens fäbodar', 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.8298514, 15.6032135, 532799.4, 6743986.4, 532751, 6743903, 532863, 6744072, 0, 'GeometryCollection', '{"type":"GeometryCollection","geometries":[{"type":"Point","coordinates":[15.6033606,60.8304256]},{"type":"Polygon","coordinates":[[[15.603402,60.8292895],[15.6038299,60.8294013],[15.6041768,60.8294971],[15.604336,60.8295791],[15.6043779,60.8296848],[15.6042917,60.8298448],[15.6041797,60.8299941],[15.6039799,60.8301795],[15.6037911,60.8303596],[15.6036238,60.8304947],[15.6034626,60.83054],[15.603125,60.8305931],[15.6031106,60.8306147],[15.6027643,60.8305655],[15.6025646,60.8304818],[15.6025012,60.8304084],[15.6024735,60.830265],[15.6024227,60.8300336],[15.6023277,60.8297971],[15.6023669,60.8294291],[15.6023537,60.8292605],[15.6024258,60.829149],[15.6025026,60.8291165],[15.6026642,60.8291052],[15.6030808,60.8291901],[15.603402,60.8292895]]]}]}', 0, 30, '2018-10-01T09:42:47+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'c8585db554b1c1febe913713faed2a2b');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1667, '6bd2a757-8b14-459e-bd49-a7297aca1207', 'L1999:8857', 'Stora Kopparberg 480', 'stora kopparberg 480', 'Gränsmärke', 'Fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fredsmilsröse, rektangulärt, 1,6x1,3 m (NÖ-SV) och 0,2 m h, av stenar, 0,2-0,7 m. Visare, 0,75 m l, i röset. Ligger mot jordfast sten i NÖ.', 'NV-sluttande moränmark.', '5 m S om kraftledning (mellan två stolpar).', 'Fredsmilen kring Kopparbergs gruva.', NULL, 'Bekräftad i fält', 'Åverkan', 'Ej undersökt', 'Synlig ovan mark', 60.6847938, 15.5214854, 528483.8, 6727792.1, 528483, 6727792, 528484, 6727793, 0, 'Point', '{"type":"Point","coordinates":[15.5214854,60.6847938]}', 0, 15, '2018-10-01T12:03:26+02:00', 'Riksantikvarieämbetet', '2026-11-17', '879d6177d1edceef9be684b588ca74e9');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1674, '6c2f16d4-6e4d-4363-8ab9-9a97f170cd8d', 'L2001:1837', 'Bjursås 121:1', 'bjursås 121:1', 'Boplats', 'Fornlämning', NULL, 'Boplats, ca 100x5-15 m st (VNV-ÖSÖ), utgörande en sandstrand och troligen den övertorvade platån N därom och ovan det ca 1 m h strandhaket. På stranden, också under vattenbrynet ligger rikligt med avslag av vit kvarts (minst 100 synliga). Under vattenrännor på ett uthus på platån i  V syns avslag i markytan. En stor del av platån är troligen boplats. 9 avslag tillvaratogs, varav två retuscherade som verkar vara skrapor.', 'S-exonerad sandstrand och moränplatå på udde i sjö. Tomtmark, skogstomter.', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Ej synlig ovan mark', 60.7366724, 15.5004784, 527292.4, 6733561.3, 527247, 6733544, 527338, 6733577, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5012997,60.736548],[15.5012508,60.7366051],[15.5011336,60.7366027],[15.5009793,60.7366252],[15.5008328,60.7366208],[15.5006928,60.7366577],[15.5005381,60.7366982],[15.5004162,60.7367406],[15.500261,60.7368026],[15.5001215,60.7368144],[15.4999642,60.7368081],[15.4996571,60.7367814],[15.4996647,60.7367652],[15.4997608,60.7367281],[15.5000175,60.7367151],[15.5002267,60.7366983],[15.5003518,60.7366756],[15.5005066,60.7366334],[15.5006063,60.7365944],[15.5007209,60.7365484],[15.5008387,60.7365239],[15.5009595,60.7365264],[15.5012997,60.736548]]]}', 0, 10, '2018-10-01T09:41:33+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'b65da259383b25ddc78279e3575af249');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1683, '6c97777e-9050-42b7-9037-bc9181bcdceb', 'L2024:3206', NULL, NULL, 'Stensättning', 'Fornlämning', NULL, 'Stensättning, närmast rund, ca 3 m diam och 0,3 m h. Tydligt välvd profil och väl avgränsad mot omgivande mark. Runtom är ett dike  ca 0,4 m br och 0,2 m dj. Vid sondning framkom kol.', 'Sydsluttande moränmark. Skogsmark, barr- och lövträd. Intill ängs/hagmark.', 'Ca 1 m från  rågångshörn.', NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7440939, 15.3980099, 521699.6, 6734349.7, 521699, 6734349, 521700, 6734350, 0, 'Point', '{"type":"Point","coordinates":[15.3980099,60.7440939]}', 0, 30, '2024-07-01T11:40:35.574+02:00', 'STIFTELSEN DALARNAS MUSEUM', '2026-11-17', 'ca5f83e5297d5e720dce07d6765682bb');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1685, '6cabb410-f57d-4d70-a742-014f5e17622c', 'L2024:409', NULL, NULL, 'Gruvområde', 'Möjlig fornlämning', 'Svårbedömd ålder och kontext.', 'Gruvområde bestående av två jordrymningar, den ena är rund, 4 m diam och 0,8 m dj, den andrav är oval, 3 x 2 m (NNV-SSO) och 1 m dj. Bevuxna med gran och tall.', 'V-sluttning av berg vid myr.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7364677, 15.3089548, 516848.3, 6733474.1, 516836, 6733464, 516859, 6733483, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.3088886,60.7365394],[15.3091375,60.7364981],[15.3090532,60.7363803],[15.30873,60.7364705],[15.3088886,60.7365394]]]}', 0, 10, '2024-02-09T11:42:03.244+01:00', 'länsstyrelsen', '2026-11-17', '788f47ff6a09989a3e8b5ea79272ca32');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1689, '6cd29d6d-caa2-41a1-a6d4-238d5f232212', 'L2023:7055', NULL, NULL, 'Färdväg', 'Övrig kulturhistorisk lämning', NULL, 'Färdväg i form av kvarnväg/-stig, ca 225 m l (N-S, ÖNÖ-VSV), 0,5-1,5 m br och 0,2-0,3 m h, flack stig. Försvinner i ÖNÖ änden, avslutas i S änden vid kvarnplats, småindustriområde.', 'Blockig och stenig NV-  och N-sluttande moränmark. Skogsmark (barrskog, avverkningsyta).', NULL, NULL, NULL, 'Bekräftad i fält', 'Åverkan', 'Ej undersökt', 'Synlig ovan mark', 60.8180275, 15.3578256, 519463.8, 6742571.8, 519448, 6742466, 519517, 6742650, 0, 'LineString', '{"type":"LineString","coordinates":[[15.3576663,60.817081],[15.3577392,60.8172151],[15.3577826,60.8173468],[15.3577845,60.8174303],[15.3577237,60.8175642],[15.3575892,60.8177225],[15.3575966,60.8178395],[15.357555,60.8179481],[15.3575959,60.8180496],[15.3575393,60.8181785],[15.3575498,60.8181789],[15.3576394,60.8183588],[15.3577663,60.8184846],[15.3579649,60.8185791],[15.3580666,60.818613],[15.3581181,60.8186255],[15.3584583,60.8186904],[15.3588,60.8187268]]}', 0, 20, '2023-11-11T17:17:02.616+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', '2278083cbaa76a98a17b7d4afb45cac4');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1692, '6d1cf7b6-f5bd-4066-aba6-fb1ea3ce8c75', 'L2000:8802', 'Stora Kopparberg 172:1', 'stora kopparberg 172:1', 'Hyttområde', 'Fornlämning', NULL, 'Hyttområde, delundersökt. Ca 940x10-340 m (VNV-ÖSÖ) stort, bestående av kanalsystem, 2 hyttruiner, 2 rostungnar, grundrester och slaggområde. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1695, '6d302a3d-73ee-4ac5-9584-e81076746ca3', 'L2023:6293', NULL, NULL, 'Kvarn', 'Fornlämning', 'På 1828 års karta är en kvarnplats redovisad här.', 'Kvarnlämning, inom ett område av ca 50 x 20 m (NNV-SSÖ) bestående av 1 ränna och 1 kvarngrund. Rännan är ca 21 m l (NNV-SSÖ), 1,5 m br och 0,2-0,5 m dj. Utmed NNÖ långsidan är en vall, ca 1,5-3 m br och 0,3-1 m h, övertorvad. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1699, '6d6a3d75-796f-4809-8ff1-3e5f37d8fca6', 'L2001:1768', 'Bjursås 101:1', 'bjursås 101:1', 'Gruvområde', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Gruvområde, 35x25 m st (VNV-ÖSÖ), bestående av 1 gruvhål och 1 skrotstenshög.Gruvhålet, är 3 m diam och 2 m dj till vattenyta.I ÖSÖ kanten är:Skrotstenshög, 10 m diam och 1 m h. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Ö krönkanten av moränjhöjd med berg i dagen. Skogsmark (halvvuxenblandskog).', 'Ca 43 m V om och ovan stig (N-S) på en punkt 10 m S om stigdelning.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7252729, 15.3121737, 517029.8, 6732228.1, 517006, 6732209, 517052, 6732249, 0, 'GeometryCollection', '{"type":"GeometryCollection","geometries":[{"type":"LineString","coordinates":[[15.3121133,60.7252535],[15.3120688,60.7252784],[15.3120757,60.7253036],[15.3121269,60.725311],[15.3121783,60.725304],[15.312208,60.7252826],[15.312212,60.7252611],[15.3121792,60.725252],[15.3121426,60.7252518],[15.3121133,60.7252535]]},{"type":"Polygon","coordinates":[[[15.3118474,60.7251572],[15.3119099,60.7251467],[15.3120018,60.7251328],[15.312112,60.7251189],[15.3122037,60.7251103],[15.3122807,60.7251052],[15.3123942,60.7251111],[15.3125037,60.7251367],[15.3125582,60.7251621],[15.3125722,60.7252034],[15.3125751,60.7252465],[15.312552,60.7253056],[15.3124849,60.7253735],[15.3123963,60.7254109],[15.3123373,60.7254304],[15.312216,60.725455],[15.3120586,60.7254453],[15.3119126,60.7254106],[15.3118036,60.7253599],[15.3117679,60.7253059],[15.3117543,60.7252466],[15.3118067,60.725184],[15.3118474,60.7251572]]]}]}', 0, 25, '2018-10-01T09:41:12+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'f0368f720244b619b8efcdbe5ff4fe53');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1704, '6dac5ef6-9705-4804-8fe9-ffe051af3012', 'L2024:513', NULL, NULL, 'Gruvområde', 'Fornlämning', 'Äldre brytning i området', 'Gruvområde, 42 x 24 m (O-V), bestående av tre st skärpningar och ett gråbergsvarp. Två av skärpningarna är runda, 3-3,5 m diam, en är oval 3,5x2,5 m och 0,2 m dj. Skärpningarna är vattenfyllda, med 0,2-1,0 m dj till vattenytan. En skärpning kantas av skrotstenshög 3-6 m br och 1,5 m h.', 'Svacka på moränhöjd.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.723205, 15.3118409, 517012.7, 6731997.7, 516993, 6731982, 517035, 6732010, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.3115172,60.7232571],[15.3116464,60.7232843],[15.3118716,60.7233022],[15.3120357,60.7233099],[15.3121342,60.7233119],[15.3121738,60.7232877],[15.3122321,60.7232543],[15.3122223,60.7232118],[15.3121868,60.7231717],[15.3120107,60.72314],[15.3116631,60.7230696],[15.3114904,60.7231492],[15.3114817,60.7232216],[15.3115172,60.7232571]]]}', 0, 10, '2024-02-16T09:32:38.955+01:00', 'länsstyrelsen', '2026-11-17', 'beb95ff22105fecf340ca1612d70af56');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1717, '6e8d0d8f-bb31-4947-88c5-456dbe594699', 'L2001:1414', 'Bjursås 80:6', 'bjursås 80:6', 'Område med fossil åkermark', 'Övrig kulturhistorisk lämning', NULL, 'Område med fossil åkermark, ca 55 x 35 m (ÖNÖ-VSV) bestående av 1 fossil åker och 4 röjningsrösen. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1737, '6ff250c1-0736-4b6e-a1e3-965a08f46b1f', 'L1998:2530', 'Stora Kopparberg 595', 'stora kopparberg 595', 'Fossil åker', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fossil åker, oregelbunden, ca 60x15-55 m (Ö-V) st. Avgränsad mot omgivande mark av diken/hak samt i V av vägbank. Slybeväxt. Odlingsytan finns med på storskifteskarta (RAÄ dnr 321-4220-2009).', 'Svagt V-sluttande moränmark. Delvis öppen odlingsmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6786517, 15.5070086, 527698.4, 6727101.8, 527675, 6727080, 527735, 6727134, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5065935,60.6784987],[15.5066202,60.678495],[15.5068296,60.6784641],[15.5071237,60.6784918],[15.5074056,60.6784943],[15.5076633,60.6785237],[15.5076208,60.6786558],[15.507277,60.6785751],[15.5072074,60.6786554],[15.5070826,60.6787418],[15.5070469,60.6789389],[15.5067478,60.6789149],[15.5065935,60.6784987]]]}', 0, 10, '2018-10-01T12:19:53+02:00', 'Riksantikvarieämbetet', '2026-11-17', '8e5e2715ab90b5ecc5ff203f398a1175');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1738, '6ffbdf15-8a1d-4034-ade9-c4286cb2700a', 'L2023:5617', NULL, NULL, 'Kolningsanläggning', 'Övrig kulturhistorisk lämning', NULL, 'Kolbotten efter liggmila, kvadratisk, 7 x 7 m (NNÖ-SSV) och intill 0,3 m h med flack yta. Omgiven av dike, ca 0,8-1,3 m br och intill 0,4 m dj.', 'Kuperad moränmark. Skogsmark (barrskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Åverkan', 'Ej undersökt', 'Synlig ovan mark', 60.7332552, 15.3568989, 519464.8, 6733129.6, 519464, 6733129, 519465, 6733130, 0, 'Point', '{"type":"Point","coordinates":[15.3568989,60.7332552]}', 0, 25, '2023-10-11T16:56:35.329+02:00', 'Länsstyrelsen Dalarna', '2026-11-17', '4574b8ae4f6ffb491bc896a268c9897a');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1753, '71344db2-7258-4d71-b2e3-c92bd6d79e08', 'L2024:3466', NULL, NULL, 'Grav markerad av sten/block', 'Fornlämning', NULL, 'Uppallad sten (liggande höna), närmast oval, 3,5 x 2,5 m (SV-NO), och 2 m h, bestående av ett block,3,5 x 2,5 m och 1,5 m h, vilande på tre mindre stenar och block 0,5 - 1,2 m st. I N och SV närmast röseliknande stensamling av 0,2-0,6 m st stenar. Omedelbart O om stiga kallad "Trollstigen".', 'Skogsmark (blandskog).', NULL, 'Stigen intill kallas "Trollstigen"', NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7469354, 15.3937116, 521463.3, 6734664.7, 521463, 6734664, 521464, 6734665, 0, 'Point', '{"type":"Point","coordinates":[15.3937116,60.7469354]}', 0, 15, '2024-07-11T14:39:44.760+02:00', 'länsstyrelsen', '2026-11-17', 'fd4c73544efb9e318606c7d81d64f107');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1756, '714bc9ab-128b-4426-9b84-0b0a843c3bab', 'L2023:6282', NULL, NULL, 'Dammvall', 'Möjlig fornlämning', 'Belägen vid äldre kvarn/sågplats markerad på karta från år 1828.', 'Dammvall?, ca 5 m l (NNÖ-SSV), 1,5 m br och 0,3-0,8 m h. Helt överväxt.', 'SSÖ-sluttande stenig och blockig moränmark. Skogsmark (blandskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.745654, 15.3815101, 520799, 6734518.1, 520797, 6734516, 520801, 6734521, 0, 'LineString', '{"type":"LineString","coordinates":[[15.3815309,60.7456723],[15.3814893,60.7456358]]}', 0, 15, '2023-10-30T11:52:35.131+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', '99dc93176f4c444e010aecb314044a7d');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1757, '714c2b9e-35ab-4a90-95a6-8fe742242264', 'L2023:6291', NULL, NULL, 'Område med skogsbrukslämningar', 'Övrig kulturhistorisk lämning', NULL, 'Område med skogsbrukslämningar 30 x 20 m (N-S) bestående av 1 kolbotten efter resmila och 1 husgrund efter kolarkoja. Kolbotten efter resmila, rund, 17 m diam och 0,2-0,6 m h med flack yta, delvis ingrävd i sluttning. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1760, '717ca3b8-c946-404b-8b36-659a77f9abc8', 'L2001:1848', 'Bjursås 98:1', 'bjursås 98:1', 'Gruvområde', 'Fornlämning', 'Spår av tillmakning.', 'Gruvområde, 25x21 m st (NV-SÖ), bestående av 1 gruvhål, 1 jordrymning samt 1 skrotstenshög. Gruvhålet, är 4 m diam och 4 m dj, ej vattenfyllt, spår av tillmakning. Jordrymningen är 2 x 1,5 m och 0,8 m dj Skrotstensvarp finns runt om gruvhålet, särskilt i NV, O och SO om gruvhålet, upp till 5 m diam och 1.7 m h. Övermossade, bevuxna med grantelningar. Oinhägnat.', 'Platå på bergs- och moränhöjd.', '7 m ÖSÖ om stig.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7350336, 15.3302943, 518012.8, 6733320.1, 517996, 6733308, 518026, 6733333, 0, 'GeometryCollection', '{"type":"GeometryCollection","geometries":[{"type":"Polygon","coordinates":[[[15.3305078,60.7349708],[15.3305353,60.7350352],[15.3304998,60.7350768],[15.3304204,60.7351168],[15.3303477,60.7351406],[15.330267,60.7351376],[15.330182,60.7351113],[15.3301363,60.7350524],[15.3301386,60.7350039],[15.3302254,60.7349656],[15.3303491,60.7349324],[15.3304484,60.7349461],[15.3305078,60.7349708]]]},{"type":"LineString","coordinates":[[15.3302855,60.7350154],[15.3303297,60.7350241],[15.3303451,60.7350491],[15.3303296,60.7350773],[15.3302985,60.7350853],[15.3302582,60.7350874],[15.330225,60.7350787],[15.3302061,60.7350591],[15.3302095,60.7350483],[15.3302306,60.7350194],[15.3302855,60.7350154]]},{"type":"Polygon","coordinates":[[[15.3303486,60.7351403],[15.3304226,60.7351153],[15.3305026,60.7350746],[15.330534,60.7350344],[15.3305091,60.7349751],[15.330449,60.7349485],[15.3303465,60.7349321],[15.3302388,60.7349301],[15.3301267,60.7349389],[15.3300617,60.734958],[15.3300128,60.7349938],[15.3300043,60.7350487],[15.3300357,60.7350813],[15.3300715,60.7351024],[15.3301871,60.735134],[15.3302652,60.7351387],[15.3303486,60.7351403]]]}]}', 0, 25, '2024-02-09T15:09:25.795+01:00', 'länsstyrelsen', '2026-11-17', 'b9c24c2987c86da29f4440a33993cb6f');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1770, '72256ab9-9d73-4b09-ac9a-537080039645', 'L2024:462', NULL, NULL, 'Gruvområde', 'Möjlig fornlämning', 'Äldre än befintligt kartmaterial.', 'Gruvområde, 42x33 m (NNV-SSO), bestående av fyra jordrymningar, en skärpning och en varphög. Jordrymningarna är 8-20 x 1,5-7 m sto cu 1,6 m dj. Skärpningen är 20 x 8 m och 2 m dj. Kring kanterna och i området är gråstensvarp och jordhögar upp till 30 m diam och intill 8 m h.', 'SO-sluttande moränmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7317948, 15.3271883, 517845.2, 6732958.5, 517826, 6732934, 517861, 6732980, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.3268925,60.7319158],[15.3273203,60.7319807],[15.3274462,60.7319106],[15.3274576,60.731866],[15.3274647,60.7317866],[15.3274003,60.7316705],[15.3273242,60.7315797],[15.327174,60.7315994],[15.3270678,60.73165],[15.3269694,60.7317065],[15.3268483,60.7318501],[15.3268925,60.7319158]]]}', 0, 10, '2024-02-12T16:13:42.184+01:00', 'länsstyrelsen', '2026-11-17', '01dd0e0163810ef6390b68feea4cffea');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1778, '72c61477-3b1a-4a15-aa9c-1cbc7b2be5e2', 'L2001:1882', 'Bjursås 91:2', 'bjursås 91:2', 'Gruvområde', 'Fornlämning', NULL, '1) Gruvområde, 190x40-60 m st (VNV-ÖSÖ), bestående av 3 gruvhål,2 skärpningar, 4skrotstenshögar, 2 husgrunder samt 1 dike.Gruvhålen, är 8-20x5-8 m st och 1.5-3 m dj till vattenyta.Skärpningarna, är 6-10 m diam och 3-4 m dj.Skrotstenshögarna, är 8-20 m diam och 1.5-3 m h.Av husgrunderna, har en oklar utsträckning, ca 5-6 m st (N-S) ochspisröse, 1-5x1-5 m st och0.9 m h. Ligger i områdets Ö del. Den andra är delvis inbyggd i skrotstenshögen, 10x5 st(VNV-ÖSÖ) och 2 m h, av skrotsten, i kallmur.Diket, i områdets Ö del, är 20 m l (NNÖ-SSV), 1 m br och intill 1m dj. Oklar funktion.2) Gruvområde, 100x40 m st (VNV-ÖSÖ), bestående av 2 gruvhål, 1 skärpning, 2skrotstenshögar samt 1 husgrund.Av gruvhålen, är det ena 5x5 m st, med bevarad timmerfodring upp tio 8 stockvarv. Från håletleder ett dike åt Ö till en grund damm, ca 20x40 m st (NNV-SSÖ).Det andra gruvhålet, är 13x9 m st (ÖNÖ-VSV) och 4 m dj till vattenyta.Skärpningen, är 9 m diam och 3 m dj.Skrotstenshögarna, är 10-20 m diam och 1-4 m h.Husgrunden, har oklar utsträckning, ca 7x7 m, med spisröse, 3x3 mst och 0.9 m h.Brytningen ska ha nedlagts redan 1803. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Ö-sluttning av bergs- och moränhöjd. Nr 1 på mindre höjdrygg. Skogsmark (övervägandebarrskog). Hygge.', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7996981, 15.4916929, 526760.7, 6740577.4, 526717, 6740556, 526814, 6740600, 0, 'GeometryCollection', '{"type":"GeometryCollection","geometries":[{"type":"LineString","coordinates":[[15.4918395,60.799616],[15.4918727,60.7996339],[15.4919131,60.7996374],[15.4919643,60.7996212],[15.4919787,60.7995871],[15.4919528,60.7995728],[15.4918941,60.7995675],[15.4918318,60.7995748],[15.4918245,60.799582],[15.4918173,60.7996017],[15.4918395,60.799616]]},{"type":"Polygon","coordinates":[[[15.4913539,60.7998896],[15.4911375,60.7999008],[15.491009,60.7998939],[15.4909463,60.7998617],[15.4909092,60.7998187],[15.4909271,60.7997667],[15.4910146,60.7997019],[15.4911204,60.7996443],[15.4913656,60.7995685],[15.4917724,60.7995121],[15.491989,60.7995153],[15.4922242,60.7995489],[15.4924776,60.7995735],[15.4926321,60.7996073],[15.4926543,60.7996288],[15.4925665,60.7996648],[15.4921674,60.7997607],[15.4919148,60.7998275],[15.4917351,60.7998422],[15.4915335,60.7998659],[15.4913539,60.7998896]]]},{"type":"LineString","coordinates":[[15.4912456,60.7996907],[15.4912898,60.7996996],[15.4913448,60.7996977],[15.4913851,60.7996869],[15.4913885,60.7996582],[15.4913588,60.7996259],[15.4912853,60.7996153],[15.4912194,60.799628],[15.4912012,60.7996478],[15.4912125,60.7996764],[15.4912456,60.7996907]]}]}', 0, 25, '2018-10-01T09:41:50+02:00', 'Riksantikvarieämbetet', '2026-11-17', '454007fdb634d81eb14b804e62cc6a33');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1783, '735073d9-29f6-4cba-836f-0b905f3c0246', 'L2023:6743', NULL, NULL, 'Färdväg', 'Fornlämning', 'Välbevarad sträcka av äldre landsväg/kärrväg.  Används ej längre för sitt ursprungliga syfte (landsväg).  
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1784, '73524cb4-1487-4ad0-b435-83aa5c698015', 'L2001:1711', 'Bjursås 81:1', 'bjursås 81:1', 'Fäbod', 'Fornlämning', 'Ej påträffad på några historiska kartor år 1819 och senare. Kan troligen ha övergetts före storskiftet.', 'Fäbodlämning, ca 125 x 105 m (VNV-ÖSÖ), bestående av 2 husgrunder, 1 brunn, 8 röjningsrösen och 1 röjd (?) yta.  
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1787, '73615ee5-ecf6-4640-b1c9-2db0b99fe5ac', 'L1998:2288', 'Stora Kopparberg 578', 'stora kopparberg 578', 'Färdväg', 'Övrig kulturhistorisk lämning', NULL, 'Vägbank, delundersökt, ca 120 m l (NNV-SSÖ), 6 m br och intill 0,5 m h. Uppbyggd av sten och grus. Äldre sträckning av riksvägen (RAÄ dnr 321-4220-2009).', 'Flack moränmark. Skogsmark, yngre blandskog.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Delundersökt', 'Synlig ovan mark', 60.6777911, 15.5089692, 527806.2, 6727006.8, 527775, 6726950, 527827, 6727058, 0, 'LineString', '{"type":"LineString","coordinates":[[15.5093251,60.6772851],[15.5092603,60.6774441],[15.5092566,60.6774523],[15.5091385,60.6776118],[15.5091017,60.6776799],[15.5090776,60.6777252],[15.5090436,60.6777884],[15.5090119,60.677821],[15.5089451,60.6778897],[15.5088715,60.6779654],[15.5088423,60.6779862],[15.5086316,60.6781369],[15.5085284,60.6781906],[15.5084558,60.6782282],[15.5084169,60.6782487]]}', 0, 25, '2018-10-01T12:18:48+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'e75e30b0b94542526e734c45bb47056f');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1788, '737483d4-2543-48fb-90c1-238ed6938ac5', 'L2000:9419', 'Stora Kopparberg 37:1', 'stora kopparberg 37:1', 'Lägenhetsbebyggelse', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Torplämning bestående av 1 husgrund och 1 jordkällare. Husgrundenär delvis överlagrad av sten och jord som lagds upp vidbreddning av vägen, I anslutning till husgrunden finnsstengårdsgårdar och gamla odlingsytor. Enligt inventeringengjord av Dalarnas museum fanns en stengårdsgård V om husgrundenmen denna förstördes vid vägbreddningen Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Svag SSÖ-sluttning i moränmark. Skogsmark (barrskog).', NULL, NULL, 'Anna-Kajsas backe', 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6666508, 15.5602712, 530619.5, 6725788.8, 530603, 6725745, 530633, 6725827, 0, 'GeometryCollection', '{"type":"GeometryCollection","geometries":[{"type":"Point","coordinates":[15.560093,60.6667375]},{"type":"Polygon","coordinates":[[[15.5599864,60.6667211],[15.5600674,60.6665475],[15.560141,60.6663953],[15.56024,60.6663041],[15.5603132,60.6662612],[15.5604119,60.6662686],[15.5604812,60.6663261],[15.5605064,60.6664696],[15.5604654,60.6666917],[15.5604979,60.6668155],[15.5604794,60.6669122],[15.5604097,60.6669676],[15.560289,60.6669889],[15.5601538,60.6669742],[15.5600296,60.6669202],[15.5599864,60.6667211]]]}]}', 0, 30, '2018-10-01T11:12:49+02:00', 'Riksantikvarieämbetet', '2026-11-17', '0d67f555d0b39c010ef0d296d3f19a1d');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1791, '73ca80bb-b831-4591-9f36-f06d2ded114b', 'L2001:1017', 'Bjursås 127:4', 'bjursås 127:4', 'Fäbod', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fäbodlämningar, uppgift om, där det år 1811 fanns 1 byggnad, troligen en stuga och därför troligen finns flera husgrunder. Ej eftersökta 1994.', 'Krön av moränrygg (NÖ-SV) mellan mosse och tjärn. Skogsmark (högbarrskog. I NÖdelen av nr 2 är hög blandskog intill igenväxande åker).', 'Nr 2 är intill och NV om väg.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Ej undersökt', 'Synlig ovan mark', 60.7191413, 15.4326926, 523608.8, 6731582.4, 523608, 6731582, 523609, 6731583, 0, 'Point', '{"type":"Point","coordinates":[15.4326926,60.7191413]}', 0, 30, '2018-10-01T09:36:55+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'cef83aef52c5e1a36941fe2c2cdcb172');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1819, '754c845d-8e66-4a12-97df-f7410f327cc9', 'L2024:393', NULL, NULL, 'Fångstgrop', 'Fornlämning', NULL, 'Fångstgrop (?), rund, 1,5 m diam och 0,3 m dj, omgiven av en vall 1,2-1,8 m br och intill 0,2 m h. Runt bottenplan. Övermossad. I N skadad av skogstraktorväg Vid provstick framkom blekjordsskikt.', 'Krön av åsliknande förhöjning mot sjö i V.', NULL, NULL, NULL, 'Bekräftad i fält', 'Åverkan', 'Ej undersökt', 'Synlig ovan mark', 60.7207818, 15.2827831, 515428.6, 6731720.6, 515428, 6731720, 515429, 6731721, 0, 'Point', '{"type":"Point","coordinates":[15.2827831,60.7207818]}', 0, 30, '2024-02-05T17:18:51.877+01:00', 'länsstyrelsen', '2026-11-17', '12a598e7c869c815937a07f6b7fc40a4');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1845, '7759b495-a5a5-430d-924e-0818a788d4af', 'L2001:870', 'Bjursås 104:1', 'bjursås 104:1', 'Gruvhål', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Gruvområde, 30x20 m (ÖNÖ-VSV), bestående av 1 gruvhål, 10x1-4 mst (ÖNÖ-VSV) och 1-3 m dj till grunt vatten. Skrotsten saknas. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Svagt V-sluttnade moränmark. Skogsmark (ung blandskogsdunge på "halvhygge").', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7272693, 15.3099689, 516908.4, 6732449.9, 516886, 6732436, 516929, 6732465, 0, 'GeometryCollection', '{"type":"GeometryCollection","geometries":[{"type":"Polygon","coordinates":[[[15.3097787,60.7271497],[15.3099033,60.727152],[15.3100058,60.727156],[15.3101412,60.7271674],[15.310254,60.7272109],[15.3103299,60.7272705],[15.3103031,60.7273386],[15.3102143,60.7273849],[15.3100931,60.7274005],[15.3099174,60.7273872],[15.309764,60.7273578],[15.3096626,60.7272928],[15.3095723,60.7272188],[15.3096795,60.7271636],[15.3097787,60.7271497]]]},{"type":"LineString","coordinates":[[15.3099562,60.7272653],[15.3099012,60.7272669],[15.3098314,60.7272791],[15.3098787,60.7273009],[15.3099556,60.727303],[15.3100288,60.7273033],[15.3100731,60.7272855],[15.3100514,60.7272711],[15.3100038,60.7272691],[15.3099562,60.7272653]]}]}', 0, 25, '2018-10-01T09:36:03+02:00', 'Riksantikvarieämbetet', '2026-11-17', '4df7d1299dac98fd467c7034f49