INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1874, '791570d1-7116-4d85-bf70-e5d520eede4d', 'L2024:611', NULL, NULL, 'Kolningsanläggning', 'Övrig kulturhistorisk lämning', NULL, 'Kolbotten efter resmila, rund, 12 m diam och intill 0,3 m h. Kring kanterna en vall. Bevuxen med två björkar och sälg.', 'SO-sluttande moränmark på höjdsträckning.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.8686758, 15.6025713, 532724.7, 6748310.3, 532724, 6748310, 532725, 6748311, 0, 'Point', '{"type":"Point","coordinates":[15.6025713,60.8686758]}', 0, 30, '2024-02-28T14:29:09.190+01:00', 'länsstyrelsen', '2026-11-17', '042d625d99f6dee63e006ba28826f3d5');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1894, '7a2e4fbc-bb2e-4bb5-97ef-2a798a300546', 'L2023:5696', NULL, NULL, 'Husgrund, förhistorisk/medeltida', 'Möjlig fornlämning', 'Oklart om det verkligen är en husgrundsterrass, då dessa inte tidigare påträffats i Dalarna.', 'Husgrundsterass?, bestående av inom en ca 20 x 10 m (ÖNÖ-VSV) st yta med sten. Anlagd N om övergivet äldre åkerområde med tydliga terrasseringar.', 'Avsats S och SSÖ-sluttande moränmark. Skogsmark', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.728104, 15.3416931, 518638.5, 6732551.4, 518638, 6732551, 518639, 6732552, 0, 'Point', '{"type":"Point","coordinates":[15.3416931,60.728104]}', 0, 30, '2023-10-12T14:15:55.781+02:00', 'Länsstyrelsen Dalarna', '2026-11-17', 'b6d2869cbe9833a32b13542b7ff85b8a');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1911, '7add5cd5-0a5c-4db4-b4cb-9261630ee2ee', 'L2024:506', NULL, NULL, 'Gruvhål', 'Möjlig fornlämning', 'Gruva saknas på platsen i befintligt kartmaterial från Storskifte och framåt.', 'Skärpning 6 x 3 m (NV-SO), vattenfylld, och 0.4 m dj till vattenytan.', 'O-sluttande moränmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7246424, 15.3189513, 517399.8, 6732159.6, 517399, 6732159, 517400, 6732160, 0, 'Point', '{"type":"Point","coordinates":[15.3189513,60.7246424]}', 0, 30, '2024-02-15T10:42:54.187+01:00', 'länsstyrelsen', '2026-11-17', 'd8d0c96a9e5659742e5e272be674bcbb');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1915, '7b2015f2-3897-4b8b-aca2-b3d272d5e381', 'L2001:1635', 'Bjursås 77:1', 'bjursås 77:1', 'Boplats', 'Fornlämning', NULL, 'Boplats, ca 30x10 m st (NV-SÖ). På sandstranden påträffades rikligt med skarpkantad kvarts, varav 2 säkra avslag samt 1 mikrospån. I strandvallen iakttogs dessutom skärvig och eldpåverkad sten. Skiss i inventeringshandlingarna.', 'Liten sandstrand exponerad mot SV vid större skogssjö, ca 150 m från åmynning. Röjdlägerplats med gapskjul och bänk.', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Ej synlig ovan mark', 60.7310959, 15.2758615, 515046.1, 6732867.8, 515035, 6732856, 515057, 6732879, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.2760058,60.7309949],[15.2760468,60.7310197],[15.2760441,60.7310556],[15.2760048,60.7310954],[15.2759109,60.7311462],[15.2758419,60.73117],[15.2757398,60.7311886],[15.2756846,60.7311764],[15.275662,60.731155],[15.2756831,60.7311226],[15.2757443,60.7310827],[15.275842,60.7310354],[15.2760058,60.7309949]]]}', 0, 10, '2018-10-01T09:40:22+02:00', 'Riksantikvarieämbetet', '2026-11-17', '09702e6708a35dc18e19971b44e9c3c1');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1918, '7b457e2b-a67a-43da-bf85-d6bbb9fed25d', 'L1998:2614', 'Stora Kopparberg 593', 'stora kopparberg 593', 'Färdväg', 'Övrig kulturhistorisk lämning', NULL, 'Körväg ca 330 m l (NNV-SSÖ) och 2 m br. Synlig som en svag försänkning i omgivande mark. I SSÖ bestående av en uppbyggd vägbank intill 0,5 m h. Hör troligen samman med odlingslämningarna i närområdet (RAÄ dnr 321-4220-2009).', 'V-sluttande stenig moränmark. Skogsmark, granskog.', NULL, NULL, NULL, 'Bekräftad i fält', 'Åverkan', 'Ej undersökt', 'Synlig ovan mark', 60.6758341, 15.5095621, 527840.3, 6726789.1, 527810, 6726713, 527892, 6726873, 0, 'LineString', '{"type":"LineString","coordinates":[[15.5091366,60.6765884],[15.5090318,60.6764385],[15.5090401,60.6763151],[15.5092134,60.6760685],[15.5091935,60.6759935],[15.5093381,60.6759371],[15.50958,60.6758652],[15.5096918,60.6755802],[15.5097483,60.6755321],[15.5098706,60.6754605],[15.5098968,60.6754452],[15.5100436,60.6753867],[15.5102198,60.6753037],[15.5104868,60.6751553]]}', 0, 25, '2018-10-01T12:20:14+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'de09f9cec44c20be18edbc7d772c5c98');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1928, '7c197197-f964-4e14-81e5-b85d7ede738a', 'L2023:6360', NULL, NULL, 'Kolningsanläggning', 'Övrig kulturhistorisk lämning', NULL, 'Kolbotten efter liggmila, kvadratisk 8 x 8 m (NÖ-SV) och 0,1-0,6 m h med ojämn, delvis utgrävd yta. Omgiven av stybbdiken, 1-2 m br och 0,3-0,7 m dj.', 'SV-sluttande moränmark. Skogsmark (barrskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7758142, 15.3668561, 519981.3, 6737872.8, 519981, 6737872, 519982, 6737873, 0, 'Point', '{"type":"Point","coordinates":[15.3668561,60.7758142]}', 0, 25, '2023-10-31T15:48:29.326+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', 'fa9a8e1166725f3ce4ef69da0b0f7db4');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1940, '7cf99322-b8c9-4aca-aaf2-5b2eb2fc4b7e', 'L2023:5621', NULL, NULL, 'Område med skogsbrukslämningar', 'Övrig kulturhistorisk lämning', NULL, 'Område med skogsbrukslämningar, ca 25 m st, bestående av 1 kolbotten efter resmila och 1 husgrund efter kolarkoja. Kolbotten efter resmila, rund, 18 m diam och 0,3-1,2 m h med ojämn yta med gropar. NÖ om kolbotten är en husgrund efter kolarkoja, bestående av ett spisröse, ca 2 x 1 m st och 0,6 m h.', 'ÖNÖ sluttande moränmark. Skogsmark (barrskog med inslag av björk).', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7101938, 15.2763732, 515083.8, 6730539.9, 515083, 6730539, 515084, 6730540, 0, 'Point', '{"type":"Point","coordinates":[15.2763732,60.7101938]}', 0, 25, '2023-10-11T17:54:03.824+02:00', 'Länsstyrelsen Dalarna', '2026-11-17', 'ec6a74ed29adb2c89d8b86d8b1b99aee');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1941, '7d16bc8c-ffa9-4608-9223-61b4713a735f', 'L2023:5685', NULL, NULL, 'Bytomt/gårdstomt', 'Fornlämning', 'Belagd på karta före år 1850. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1969, '7f3975db-a83c-43ea-a7d2-2fa2eda8b9eb', 'L2001:1555', 'Bjursås 14:1', 'bjursås 14:1', 'Husgrund, historisk tid', 'Övrig kulturhistorisk lämning', NULL, 'Husgrund, 13x6 m st (NNÖ-SSV). Forna? bostadshuset i Hansesgården. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Måttligt SSÖ-sluttande moränmark. Skogsklätt impediment mellan smååkrar.', '3 m 280 gon om ladas NV hör och 1 m 360 gon om ladas N kant.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7486016, 15.451186, 524595.3, 6734870.5, 524595, 6734870, 524596, 6734871, 0, 'Point', '{"type":"Point","coordinates":[15.451186,60.7486016]}', 0, 30, '2018-10-01T09:39:53+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'ad62e9ca6f604bff6f27e08b34d15c53');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1983, '8041ad00-5a81-4c36-92d1-7f1257a33556', 'L2000:8976', 'Stora Kopparberg 136:2', 'stora kopparberg 136:2', 'Smideslämning', 'Övrig kulturhistorisk lämning', NULL, 'Fångstgrop, närmast rund, 2.5 m diam och ca 3.5 m dj. Gropen ärcylinderformad med kallmurad vägg, av 0.2-0.5 m st stenar.Gropen är omgiven av en jordvall, 2.5-3.5 m br och intill 0.3 mh. Gropens botten delvis fylld med ris. Bevuxen med en björk, enunggran samt ca 40 tallplantor. Tre stubbar.20 m SSÖ m fångstgropen är en husgrund, 5x5x4 m och 0.5 m h.Smedja 70 m SSÖ om fångstgropen är en mindre gruva, stenbrott?,inom markerat områdex, 5 m SV om den är en varphög. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Blockig moränmark på krön av liten, flack höjd. Skogsmark(Kalhygge).', '75 m ÖNÖ om åkerhörn och ca 75 m SÖ om åkerhörn.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6716377, 15.5912215, 532306, 6726359.1, 532305, 6726359, 532306, 6726360, 0, 'Point', '{"type":"Point","coordinates":[15.5912215,60.6716377]}', 0, 30, '2018-10-01T11:10:38+02:00', 'Riksantikvarieämbetet', '2026-11-17', '506cf9e06595f2eb8bb274ef76ef4687');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1984, '8043a9d0-6057-4f7b-9653-dd407830f8ce', 'L2023:6663', NULL, NULL, 'Bytomt/gårdstomt', 'Ingen antikvarisk bedömning', NULL, 'Uppgift om gårdstomt. Enligt muntlig uppgift ska det här ha funnits en gård som övergavs före storskiftet. På platsen är idag ett ca 15 m st röjningsröse som kan eventuellt övertäcka husgrunder.', 'Svacka mellan två åkerryggar i SÖ-sluttande moränmark med berg i dagen. Småbrutet odlingslandskap med impediment (lövskog).', NULL, NULL, NULL, 'Uppgift om lämning, ej bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Ej synlig ovan mark', 60.7730426, 15.3809902, 520753, 6737568.5, 520752, 6737568, 520753, 6737569, 0, 'Point', '{"type":"Point","coordinates":[15.3809902,60.7730426]}', 0, 25, '2023-11-06T15:56:29.207+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', '7d249b67ee5cc959bc50f097e0cccd8e');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1994, '816c344e-4de6-4c2e-824a-4e6d1fc51af9', 'L2001:1557', 'Bjursås 16:1', 'bjursås 16:1', 'Minnesmärke', 'Övrig kulturhistorisk lämning', NULL, 'Minnessten, liggande, av huggen gråsten, 1 m h, 0.7 m br och 0.3m tj.På ovansidan är inom en krönt sköld:Två korslagda Dalpilar och texten: 1913 - 1921.Minnesstenen är nedknuffad från Ö kanten av ovansida av block, 45m st och 2 m h.Skiss i inventeringshandlingarna. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Vägkant intill skogsmark.', 'Intill och V om väg, på en punkt 10 m N om infartsväg mot SSV.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.762618, 15.4619565, 525171.4, 6736435.7, 525171, 6736435, 525172, 6736436, 0, 'Point', '{"type":"Point","coordinates":[15.4619565,60.762618]}', 0, 13, '2018-10-01T09:39:54+02:00', 'Riksantikvarieämbetet', '2026-11-17', '55c69efe5c8d8c7b6953c88bd182fa31');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1997, '81a516fb-d125-4630-ac87-29afcfed89b1', 'L2001:2064', 'Bjursås 128:1', 'bjursås 128:1', 'Fäbod', 'Ingen antikvarisk bedömning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fäbodlämning, uppgift om. Enligt karta 1811, men borta 1912. Ingagrundlämningarhittades 1994. Markytan på platsen är nyligen sönderschaktad. ÖNÖdärom har funnits enmindre odling med stenansamlingar. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Småkuperad moränmark. Skogsmark (hygge med sly).', NULL, NULL, NULL, 'Uppgift om lämning, ej bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.720832, 15.4336848, 523661.7, 6731771.1, 523661, 6731771, 523662, 6731772, 0, 'Point', '{"type":"Point","coordinates":[15.4336848,60.720832]}', 0, 30, '2018-10-01T09:42:50+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'c7ee4414984922d0f72efa9f35011dcc');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (1999, '81c06985-9ccf-489d-bdce-8a67b1039cdc', 'L2023:7051', NULL, NULL, 'Dike/ränna', 'Övrig kulturhistorisk lämning', NULL, 'Dike, ca 110 m l (NNÖ-SSV, NÖ-SV), 1-1,5 m br och 0,3-1 m dj, vattenfyllt. Vall utmed ena sidan som är 1-2,5 m br och 0,2-0,8 m h.', 'Flack samt SV-sluttande moränmark. Skogsmark (barrskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Ringa åverkan', 'Ej undersökt', 'Synlig ovan mark', 60.8114354, 15.4063991, 522110.5, 6741852.9, 522070, 6741822, 522135, 6741898, 0, 'LineString', '{"type":"LineString","coordinates":[[15.406826,60.811835],[15.4068407,60.8116807],[15.4067924,60.8116357],[15.4065302,60.8114583],[15.4064804,60.8114295],[15.4063398,60.8113789],[15.4062904,60.8112964],[15.4058381,60.8111705],[15.4058054,60.8111836],[15.405666,60.8111683]]}', 0, 10, '2023-11-11T16:32:27.570+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', '76103fd4d6062de8298c2c7ad78a2bd0');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2013, '827699c3-1082-4e5a-9bce-033557ecf181', 'L2001:2210', 'Bjursås 41:1', 'bjursås 41:1', 'Gränsmärke', 'Övrig kulturhistorisk lämning', NULL, 'Gränssten, gråsten, 1 m h, 0.4 m br (ÖNÖ-VSV) och 0.2 m tj. På den mot SSÖ vändasidan är en krona och årtalet:1767.Skiss i inventeringshandlingarna. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Moränavsats i svag NNV-sluttning mellan åker i SÖ och kraftledningsgatan i NV.Hagmark.', '2 m NNV om gammal väg (ÖNÖ-VSV) och 1.5 m om mindre uthus.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7092256, 15.2928551, 515983.9, 6730435.9, 515983, 6730435, 515984, 6730436, 0, 'Point', '{"type":"Point","coordinates":[15.2928551,60.7092256]}', 0, 15, '2018-10-01T09:43:39+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'a08456bc3eccd5c3eb5a1c6da3d879d0');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2014, '8279cc43-8d09-4be0-a068-514487327c41', 'L1998:2556', 'Stora Kopparberg 601', 'stora kopparberg 601', 'Fossil åker', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fossil åker, ca 55x5-20 m (NV-SÖ) st. I SV avgränsad mot omgivande mark av vägbank, i övrigt av oregelbundet dike/bäck. Odlingsytan finns med på storskifteskartan (RAÄ dnr 321-4220-09).', NULL, NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6782464, 15.5087187, 527792.1, 6727057.4, 527775, 6727032, 527813, 6727078, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5084289,60.6783217],[15.5085978,60.6782379],[15.5087077,60.6781816],[15.5088625,60.6780949],[15.5090183,60.6780232],[15.5090933,60.6780441],[15.5089525,60.6781499],[15.5089359,60.6781649],[15.5087948,60.6782908],[15.5086459,60.6783753],[15.5086762,60.6784024],[15.5085126,60.6784303],[15.5084084,60.6783742],[15.5084289,60.6783217]]]}', 0, 10, '2018-10-01T12:20:02+02:00', 'Riksantikvarieämbetet', '2026-11-17', '1c747da4d76c8a8d5fcac0fab7779c1c');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2041, '8453f67f-fdae-460a-a278-194e4b10aebe', 'L2001:2091', 'Bjursås 85:3', 'bjursås 85:3', 'Fäbod', 'Fornlämning', NULL, '1) Fäbodlämning, 70x70 m (NNÖ-SSV), bestående av minst 5 husgrunder. Dessa är 8x4 ?4x4 m st och intill 0.6 m h. Tre har spisrösen. I områdets S del är ett källdrag.2) Fäbodlämning, 230x230 m st (N-S), bestående av 15 husgrunder, 3åkertegar och 4röjningsrösen.Husgrunderna, är 3-9x3-6 m st och 0.2-1 m h. Två har spisrösen.Åkertegarna, är bandformiga, 15-20x30-50 m st. En avgränsas i SÖ av en intill 2 m hterrassering, en annan i SV av en 3 m br och 1.5 m h stenvall.Röjningsrösena, är 4 m diam och intill 1 m h.3) Fäbodlämning, 140x80 m (NÖ-SV), bestående av 8 husgrunder samt1 ruin.Husgrunderna, är 4-7x4-6 m st och 0.2-0.3 m h. Två har spisrösen.Ruinen, är 4x4 m st, med upp till 8 bevarade stockvarv.Inom nr 2 är:4) Gruvområde, bestående av 1 gruvhål, 1 skärpning och 1 skrotstenshög.Gruvhålet, är 3x3 m st och 1.5 m dj till vattenyta.Skrotstenshögen, belägen omedelbart S om gruvhålet. är 10x7 m st och 1.5 m h.Skärpningen, är 3x2 m st och 2 m dj.5) Fäbodområde, ca 700x60-440 m st (NNV-SSÖ). Inom området, som även går in i Leksandssocken, ligger 3 bebyggelseområden (nr 2-3 samt Leksand RAÄ-nr 977), varav ett (nr 2) äveninnehåller ett gruvområde. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'SV-sluttning av bergs- och moränhöjd. Skogsmark (blandskog och hyggen).', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Ej synlig ovan mark', 60.8300447, 15.5004165, 527209.7, 6743961, 527144, 6743901, 527267, 6744022, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.4996088,60.8300321],[15.4993978,60.8299163],[15.4992714,60.829799],[15.4992032,60.8297125],[15.4992376,60.8296444],[15.4992794,60.829571],[15.4993684,60.8295318],[15.4995194,60.8295181],[15.4996807,60.8295368],[15.4998599,60.8295861],[15.499998,60.8296675],[15.5000887,60.8297308],[15.5001724,60.829776],[15.5003042,60.8298018],[15.5004474,60.8298132],[15.500679,60.8298106],[15.5008704,60.8297953],[15.5011052,60.8298215],[15.5012477,60.8298634],[15.5013459,60.8299159],[15.5014364,60.8299936],[15.5014681,60.8300655],[15.5014664,60.8301553],[15.5014202,60.8302628],[15.5013603,60.8303236],[15.5011628,60.8304628],[15.5010219,60.8305287],[15.5008962,60.8305658],[15.5007084,60.8305829],[15.5005406,60.8305175],[15.5002638,60.8303816],[15.5000748,60.8302677],[15.4998565,60.8301536],[15.4996088,60.8300321]]]}', 0, 10, '2018-10-01T09:42:58+02:00', 'Riksantikvarieämbetet', '2026-11-17', '9ca23bb17241305d79b26f1b57873dd3');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2043, '84cedff6-917c-4f89-92f1-81e4d006cb46', 'L2001:663', 'Bjursås 71:1', 'bjursås 71:1', 'Övrigt', 'Övrig kulturhistorisk lämning', NULL, 'Kvartsförekomst. Inom ett 10x5 m st område förekommer kvartsbitar/avslag. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Strandkant.', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7914471, 15.5488017, 529876.6, 6739683, 529876, 6739683, 529877, 6739684, 0, 'Point', '{"type":"Point","coordinates":[15.5488017,60.7914471]}', 0, 30, '2018-10-01T09:34:49+02:00', 'Riksantikvarieämbetet', '2026-11-17', '8b530955379bbccbb8609106de328246');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2044, '84d8a093-8618-4416-b9ea-29fcefade365', 'L2024:406', NULL, NULL, 'Gruvområde', 'Övrig kulturhistorisk lämning', NULL, 'Skärpning, ca 15 x 5 m (O-V) i berg i dagen med skrotstenshögar nedanför. Bevuxet med kraftig örtvegetation.', 'S-sluttande berg i dagen', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.7297339, 15.2910639, 515876, 6732719.7, 515870, 6732715, 515882, 6732722, 0, 'LineString', '{"type":"LineString","coordinates":[[15.291138,60.7297525],[15.2911663,60.7297516],[15.2910874,60.7297513],[15.2909551,60.7296949]]}', 0, 25, '2024-02-08T17:03:09.957+01:00', 'länsstyrelsen', '2026-11-17', '8b526be2c6dd26fd6b778db45d301cc7');
