INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2086, '87dd3f89-3dca-46eb-a6a2-075efccaec9c', 'L2023:6889', NULL, NULL, 'Färdväg', 'Fornlämning', 'Går mellan fäbodar med belägg före år 1850. Stigen är övergiven och med på karta från år 1828.', 'Färdväg bestående av del av fäbodstig, ca 500 m l (V-Ö), 0,7-2 m br och intill 0,3 m dj. I kortare partier är den delvis terrasserad, ingrävd, 0,4 m h. Fäbodstigen går mellan två delar av fäboden Vatta och är del av en längre fäbodstig mellan Finnbo, fäbodarna Vatta och Fänriksbo för att gå vidare till Sörskog.', 'S och SÖ-sluttande moränmark. Skogsmark (barrskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Åverkan', 'Ej undersökt', 'Synlig ovan mark', 60.8304944, 15.4906686, 526679.3, 6744007, 526433, 6743965, 526931, 6744033, 0, 'LineString', '{"type":"LineString","coordinates":[[15.4952947,60.8307035],[15.4921503,60.8304611],[15.4917614,60.8304518],[15.4916271,60.830455],[15.4915065,60.8304534],[15.4912604,60.8304896],[15.4910944,60.8305304],[15.4907647,60.8305493],[15.4883926,60.830505],[15.4882394,60.8304955],[15.4879256,60.83045],[15.4876571,60.8304271],[15.4873525,60.8303915],[15.4869065,60.8303223],[15.4866343,60.8302689],[15.4864656,60.8302004],[15.4862966,60.8301615],[15.4861356,60.8301349]]}', 0, 25, '2023-11-09T15:09:20.737+01:00', 'Länsstyrelsen Dalarna', '2026-11-17', 'fc2d47b509eda5b5a0329f92fae6edd1');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2090, '8812a611-7fd1-40b9-ba26-bf560aec4912', 'L1999:272', 'Stora Kopparberg 245:2', 'stora kopparberg 245:2', 'Bytomt/gårdstomt', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', NULL, NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.670824, 15.6072652, 533183.5, 6726276.5, 533183, 6726276, 533184, 6726277, 0, 'Point', '{"type":"Point","coordinates":[15.6072652,60.670824]}', 0, 30, '2018-10-01T11:19:58+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'd6a01c4decdfb45585da3d5c23fa595a');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2092, '882b85ae-4a06-4ee3-8441-41c602b3d50a', 'L2023:6358', NULL, NULL, 'Naturföremål/-bildning med bruk, tradition eller namn', 'Övrig kulturhistorisk lämning', NULL, 'Bläcka, på en tall, ca 0,7-0,9 m ovan marknivå är 2 bläckor på vardera N och S sidan av stammen. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2094, '883c5561-09ce-4f49-ae4d-a7cdd2d91aed', 'L2023:7076', NULL, NULL, 'Färdväg', 'Fornlämning', 'Övergiven och av äldre karaktär, redovisad på karta från år 1828.', 'Färdväg i form av fäbodstig, övergiven, ca 50 m l (V-Ö, ÖNÖ-VSV), 1 m br, 0,2-0,4 m dj, delvis med hålvägskaraktär samt även vägbankskaraktär, där den är upptill 0,4 m h. Avslutas i V vid skogsbilväg och i ÖNÖ vid stenigare/blockigare parti. 
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2100, '88adf2a6-3be8-4c8b-b6f1-d0cd9ad404eb', 'L1998:2558', 'Stora Kopparberg 603', 'stora kopparberg 603', 'Fossil åker', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fossil åker, oregelbunden, 45x15-30 m (NÖ-SV) st. Bestående av 2 odlingsytor åtskilda av stort dike, 1,5 m br och intill 1 m dj. Avgränsade mot omgivande mark av diken och hak samt enstaka mindre röjningsrösen. Odlingsytan finns med på storskifteskartan. Ytterligare odlingsytor finns NÖ om det här registrerade området (RAÄ dnr 321-4220-2009).', 'Flackt parti i SV-sluttande stenig moränmark. Skogsmark, gran- och blandskog.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Delundersökt', 'Synlig ovan mark', 60.6736767, 15.5133623, 528049.8, 6726550.4, 528016, 6726527, 528081, 6726569, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5127476,60.6737306],[15.5131849,60.6734759],[15.5132715,60.6735878],[15.5134314,60.6736597],[15.513702,60.6736081],[15.5138427,60.6735439],[15.5139157,60.6737102],[15.5136299,60.6738342],[15.5133447,60.6737276],[15.5131679,60.6737415],[15.5128509,60.6737709],[15.5127476,60.6737306]]]}', 0, 10, '2018-10-01T12:20:03+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'b3dfe0a4cf1c2ce3c0b277b3d0e4295f');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2114, '89979e43-1c45-4ca9-a5f7-b39b7194f3bd', 'L2001:1846', 'Bjursås 19:1', 'bjursås 19:1', 'Fyndplats', 'Övrig kulturhistorisk lämning', NULL, '1) Fyndplats för stenyxa. Funnen av Rapp Olov Olsson omkring 1890-1900 vidarbete på åkern. Stenyxan, som är en enkel skafthålsyxa, är av mörkgrå bergart medskrovlig, nött yta och med ca 1 cm bortslagen av eggdelen. Den ärnumera 8.5 cm l, intill4.2 cm br och intill 3.3 cm tj, vid mittpartiet båda måtten. Håletär 2 cm diam. Visad 1994av upphittarens sonson Ragnvald, som bekräftade den ungefärliga fyndplatsen, en planåkertäppa, numera igenväxande av sly och granplantor.Yxan förvaras hos Rapp Olga Olsson, Gopa Näset, Sågmyra.35 m VSV om nr 1 är:2) Husgrund, ca 13x8 m (Ö-V), delvis med meterstora grundstenar, vilken kan vara frånden gård som omtalas här i början på 1500-talet. Enligt ägarna Olssons, är detta denäldsta gårdsplatsen, föregångare till den "nya" kringbyggda gårdenfrån 1701 SV därom,där även den Ö längan har sexkantiga timmerknutar.Mitt på husgrunden står en till gäststuga ombyggd bod (Ö-V), vilken är senast från 1600-talet. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Flack morän- och sedimentudde mot N i sjö. Igenväxande åkermark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7128096, 15.3274589, 517870.5, 6730844, 517870, 6730844, 517871, 6730845, 0, 'Point', '{"type":"Point","coordinates":[15.3274589,60.7128096]}', 0, 30, '2018-10-01T09:41:37+02:00', 'Riksantikvarieämbetet', '2026-11-17', '66f0a7b92477556f87ce597fb7e9ea80');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2123, '8a5a622b-82b9-455d-b5be-b2a28ade6cf9', 'L1999:120', 'Stora Kopparberg 194:1', 'stora kopparberg 194:1', 'Gruvområde', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Gruvområde, ca 40x30 m (N-S), bestående av 1 gruvhål samt 1skotstensvarp.Gruvhål, oregelbundet närmast runt, ca 10-12 m i diam, ca 4 m djtill vattenytan. 1 kanternarna är nedrasade block, jord ochskrotsten. S om gruvhålet är ett skrotstensvarp(magnetitförarande). Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Flack SV-sluttning av blockig moränavlagring. Skogsmark,(barrskog).', 'Ca 7 m V om skogskörväg.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6695856, 15.5856599, 532004.1, 6726127.8, 531986, 6726104, 532021, 6726148, 0, 'GeometryCollection', '{"type":"GeometryCollection","geometries":[{"type":"LineString","coordinates":[[15.5857361,60.6696357],[15.5857104,60.6696411],[15.5856774,60.6696572],[15.5856993,60.6696769],[15.5857358,60.669686],[15.5857834,60.6696842],[15.5858018,60.6696699],[15.5857872,60.6696501],[15.5857361,60.6696357]]},{"type":"Polygon","coordinates":[[[15.5853391,60.6695613],[15.5854088,60.6694647],[15.5855406,60.6693968],[15.5856138,60.6693773],[15.5857781,60.6694475],[15.5859314,60.6695571],[15.5859532,60.6696414],[15.585931,60.669731],[15.5858542,60.6697649],[15.5856677,60.6697627],[15.5854667,60.6696924],[15.5853682,60.6695955],[15.5853391,60.6695613]]]}]}', 0, 25, '2018-10-01T11:19:11+02:00', 'Riksantikvarieämbetet', '2026-11-17', '46c4a94c0ececf3daa22960c6acccd49');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2145, '8b74cabe-7e96-4517-8257-76978735c6c0', 'L1998:2198', 'Stora Kopparberg 581', 'stora kopparberg 581', 'Hägnad', 'Övrig kulturhistorisk lämning', NULL, 'Hägnad bestående av stengärdsgård, rest av, ca 30 m l (NÖ-SV) 0,3-0,8 m br och 0,2- 0,5 m h. Bestående av ett flertal 0,3-1,0 m st stenar på rad. Troligen skadad av infart till hästhage (RAÄ dnr 321-4220-2009).', 'Svagt SV-sluttande moränmark. Hagmark, beteshage för hästar.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.668267, 15.5406528, 529545.9, 6725959.9, 529537, 6725950, 529555, 6725970, 0, 'LineString', '{"type":"LineString","coordinates":[[15.540489,60.6681805],[15.5408165,60.6683536]]}', 0, 15, '2018-10-01T12:18:26+02:00', 'Riksantikvarieämbetet', '2026-11-17', '47fb873ecba2c34e9f8ee22ccdf4c4ff');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2146, '8b7cb23b-09bf-42b7-8cbb-0066ad933a22', 'L1998:2197', 'Stora Kopparberg 580', 'stora kopparberg 580', 'Brott/täkt', 'Övrig kulturhistorisk lämning', NULL, 'Stenbrott, 10x7 (NV-SÖ) st, bestående av en grop 4x2 m st och 0,5 m dj omgiven av skarpkantade stenar, varav vissa med spår av borrning (RAÄ dnr 321-4220-2009).', 'NV-slutning av stenig mindre moränhöjd. Skogsmark, blandskog.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6742236, 15.5106151, 527899.2, 6726610.2, 527899, 6726610, 527900, 6726611, 0, 'Point', '{"type":"Point","coordinates":[15.5106151,60.6742236]}', 0, 30, '2018-10-01T12:18:25+02:00', 'Riksantikvarieämbetet', '2026-11-17', '1cedb8120f8e227b975ad331222d5a26');
