INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2279, '94e8484e-2ee6-42de-9937-a49dee9e78b9', 'L1999:528', 'Stora Kopparberg 350:1', 'stora kopparberg 350:1', 'Kvarn', 'Ingen antikvarisk bedömning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', NULL, NULL, NULL, NULL, 'Uppgift om lämning, ej bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6621753, 15.5487155, 529992.2, 6725285, 529978, 6725266, 530006, 6725303, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5484745,60.6621519],[15.5485369,60.662084],[15.5485992,60.6620465],[15.5487053,60.6620109],[15.5487821,60.6620182],[15.5488697,60.6620453],[15.548939,60.6621136],[15.5489642,60.6622158],[15.5489055,60.6622748],[15.548792,60.6623211],[15.5487188,60.6623317],[15.5485618,60.6622991],[15.5484632,60.6622487],[15.5484745,60.6621519]]]}', 0, 10, '2018-10-01T11:21:33+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'f572363a19faf71a13086d1092d2adfe');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2283, '953258d0-0db5-44d8-aec9-b4f40c826e1c', 'L1998:2200', 'Stora Kopparberg 583', 'stora kopparberg 583', 'Bytomt/gårdstomt', 'Fornlämning', NULL, 'Gårdstomt, ca 105x100 m (NÖ-SV), utsträckning enligt lantmäterikarta och provgrävning. Lämningen består av kulturlager, främst i SV, och ev. grundstenar vilka framkom vid provgrävning för arkeologisk utredning. Smedsarvets gamla tomt enligt karta från 1690 (RAÄ dnr 321-4220-2009).', 'Relativt flack morän- och sedimentmark. Hagmark, beteshage för hästar.', NULL, NULL, 'Smedsarvets gamla tomt', 'Bekräftad i fält', 'Ej skadad', 'Delundersökt', 'Ej synlig ovan mark', 60.668862, 15.5396938, 529492.9, 6726025.7, 529438, 6725958, 529537, 6726078, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5397694,60.6682591],[15.5399722,60.6683038],[15.5402034,60.6685404],[15.5404203,60.6686941],[15.5404761,60.6687661],[15.5404834,60.6687994],[15.5404773,60.6690836],[15.540472,60.6692626],[15.5402873,60.6693213],[15.5400202,60.6693226],[15.5398062,60.6692668],[15.539212,60.6692564],[15.5390399,60.6691508],[15.5389798,60.6691415],[15.5387811,60.6690636],[15.5387813,60.6690285],[15.5387002,60.6688383],[15.5397694,60.6682591]]]}', 0, 10, '2018-10-01T12:18:27+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'b395dd591710540fbe8cbd3a178ade7e');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2286, '95787f4d-0b7c-4e8a-98c4-a89a19c2c9e4', 'L2000:9506', 'Stora Kopparberg 195:1', 'stora kopparberg 195:1', 'Bytomt/gårdstomt', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Gårdstomt, ca 50x20 m (N-S), bestående av 1 husgrund medspismursröse, 1 jordkällare, samt terrasseringar sannolikt medplats för ekonomibyggnader.Enligt uppgift av Lars Danielsson. Uggelviken, är dettalämningarna efter gården Slättmyra, försv omkr 1920.Äldstra belägg: Slättmyra 1463 DD2, (Ståhl, H. 1960. Ortnamnen iKopparbergslagen, s 66). Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'SV-sluttande moränhöjd. Skogsmark (tät lövskog & lövsly).', 'Husgrunden är ca 20 m NNÖ om vägkorsning och i områdets V -del.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6680097, 15.58026, 531710.6, 6725949.7, 531697, 6725924, 531725, 6725975, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5801367,60.6677926],[15.5802574,60.6677803],[15.5803561,60.6677894],[15.5803926,60.66782],[15.5803668,60.667906],[15.5804323,60.6679993],[15.5805124,60.6681661],[15.5804939,60.6682235],[15.5804464,60.6682359],[15.5803038,60.6682069],[15.5801212,60.6681474],[15.5800226,60.6681006],[15.5800669,60.6679394],[15.5800745,60.6678086],[15.5801367,60.6677926]]]}', 0, 10, '2018-10-01T11:14:19+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'c50aa0eceb4e4e67f3f0bdcf4b7c077c');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2352, '998af92b-1037-473e-965c-6929df625e67', 'L1998:120', 'Stora Kopparberg 561', 'stora kopparberg 561', 'Gränsmärke', 'Övrig kulturhistorisk lämning', NULL, 'Gränsröse, oregelbundet, 11,2 m diam och 0,6 m h, bestående av 0,3-0,5 m st stenar. Hjärtsten, 0,4 m h, 0,2 m br och 0,2 m tj. På hjärtstenens flata ovansida är inhugget en kvadrat, 8x8 cm st. En aluminiumstolpe står i röset. (RAÄ dnr 326-214-2005)', 'SSV-sluttande blockig moränmark. Skogsmark (tall och hygge).', 'I rågångshörn.', NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6354116, 15.5407611, 529581.9, 6722300.6, 529581, 6722300, 529582, 6722301, 0, 'Point', '{"type":"Point","coordinates":[15.5407611,60.6354116]}', 0, 15, '2018-10-01T12:09:17+02:00', 'Riksantikvarieämbetet', '2026-11-17', '51d313ea57381867a2af5825dd428bd5');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2423, '9e3085f4-3802-451e-8fdf-a529977223e6', 'L1998:2663', 'Stora Kopparberg 585', 'stora kopparberg 585', 'Brott/täkt', 'Övrig kulturhistorisk lämning', NULL, 'Stenbrott? 10x6 m (N-S) bestående av en grop i N 3x3 m och 0,5 m dj samt i S en stentipp 5 m diam och 1 m h bestående av 0,01-0,4 m st skarpkant stenar (RAÄ dnr 321-4220-2009).', 'SÖ-sluttande blockmoränmark. Skogsmark, blandskog.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6714502, 15.5269784, 528795.8, 6726308.3, 528795, 6726308, 528796, 6726309, 0, 'Point', '{"type":"Point","coordinates":[15.5269784,60.6714502]}', 0, 30, '2018-10-01T12:20:26+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'dd55ffa0ba7365fe9d34bd4740809018');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2447, '9fd8e136-dbf3-4ca8-9b27-a10f88283c5d', 'L1998:2201', 'Stora Kopparberg 584', 'stora kopparberg 584', 'Fossil åker', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fossil åker, oregelbunden, ca 85x35-65 m (NÖ-SV) st. Avgränsad mot omgivande mark av kraftiga diken, 0,4-0,7 m br och 0,4 dj. Stenigt impediment mitt i området. Hjulspår från skogsmaskin i NÖ kanten. Odlingsytan finns med på storskifteskartan (RAÄ dnr 321-4220-2009).', 'SV-sluttande stenig moränmark. Skogsmark, granskog.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.67482, 15.510265, 527879.6, 6726676.4, 527836, 6726635, 527915, 6726730, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5099498,60.6744565],[15.5101659,60.6745712],[15.5103022,60.6746023],[15.5109046,60.6746069],[15.5107181,60.6749229],[15.5106717,60.6750964],[15.5106637,60.6752348],[15.5105467,60.6752938],[15.510445,60.6751563],[15.510083,60.6750687],[15.5097517,60.6748032],[15.5094793,60.6747246],[15.5099498,60.6744565]]]}', 0, 10, '2018-10-01T12:18:27+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'dbd9a9536ddbf7be0aa9a274b8bb0055');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2481, 'a275bdaa-d627-40bf-8669-6760087490ae', 'L1998:2615', 'Stora Kopparberg 594', 'stora kopparberg 594', 'Fossil åker', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fossil åker, oregelbunden, 30x20 m (NV-SÖ) st. Avgränsad mot omgivande mark av hak i NV och SV samt vägbank i NÖ. Odlingsytan är delvis öppen (RAÄ dnr 321-4220-2009).', 'Flack moränmark. Igenväxande odlingsmark, blandskog.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6675302, 15.5422105, 529631.7, 6725878.5, 529615, 6725865, 529649, 6725893, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5425196,60.6674871],[15.542236,60.6676539],[15.5420497,60.6676303],[15.5419181,60.6675172],[15.5421461,60.6674422],[15.5422797,60.6674104],[15.5425196,60.6674871]]]}', 0, 10, '2018-10-01T12:20:14+02:00', 'Riksantikvarieämbetet', '2026-11-17', '2a56d7be802cb181ed76096da882fa27');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2613, 'abab24cd-fff4-4e72-8f34-874f1dfea705', 'L2000:9958', 'Stora Kopparberg 151:1', 'stora kopparberg 151:1', 'Vägmärke', 'Fornlämning', NULL, 'Milstolpe, gjutjärn med sköldplatta, 0.65 m h (total höjd 0.88 m),0.3 m br och 0.04 m tj. Milstolpen är fastsatt på en brostolpe0.6 m över marken. Inskrift på platta under skölden:\1873\.Skiss i inv hand.Enligt uppgift av Bengt Israelsson, Bergsgården, en milstolpe somtidigare varit placerad utefter en äldre vägsträckning ca 40 mVNV om nuvarande plats.Postmentet revs vid vägomläggning och slaggtäkt varvid milstolpenflyttades och fastsattes på sin nuvarande plats, 3-4 m från denursprungliga. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', NULL, '17 m NV om fyrvägskorsning och 0.5 N om gammal väg samt i NVbrofästet.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6624393, 15.5578136, 530489.2, 6725318.6, 530489, 6725318, 530490, 6725319, 0, 'Point', '{"type":"Point","coordinates":[15.5578136,60.6624393]}', 0, 13, '2018-10-01T11:18:15+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'c6aa3752f1970f647d691eb2605044c6');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2648, 'adc490ba-871a-45bd-8e3d-0a27761b3b6c', 'L2001:646', 'Bjursås 27:1', 'bjursås 27:1', 'Källa med tradition', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Trefaldighetskälla, oval, 1.5x1 m (NNÖ-SSV) och 0.14 m dj. Stensatt, med 0.3-0.4 mst stenar. Utlopp mot Ö-NÖ. På 1930-talet besöktes källan av enstaka personer.Nämns av Karl-Erik Forsslund. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Måttlig NÖ-sluttning. Moränmark. Skogsmark (blandskog).', 'Omedelbart Ö om stig (N-S) och 28 m 30 gon om N hörnet av uthus.', 'Fru Lax Greta Holm har använt källan som önskekälla.', NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.7336816, 15.4564288, 524892.6, 6733210.7, 524892, 6733210, 524893, 6733211, 0, 'Point', '{"type":"Point","coordinates":[15.4564288,60.7336816]}', 0, 15, '2018-10-01T09:34:41+02:00', 'Riksantikvarieämbetet', '2026-11-17', '68db88041425d0c9e2569730465875c2');
