INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2670, 'af08a28d-4aaf-44c3-b638-666f53136fc1', 'L1998:2666', 'Stora Kopparberg 588', 'stora kopparberg 588', 'Fossil åker', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fossil åker, 25x13-25 m (NNV-SSÖ), avgränsad av svaga hak och ett dike. Odlingsytan tangerar ett större odlingsområde på 1690 års karta (RAÄ dnr 321-4220-2009).', 'Flack stenig moränmark. Skogsmark, granskog.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.670537, 15.525069, 528692.2, 6726205.8, 528676, 6726190, 528704, 6726222, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.525016,60.6704087],[15.5252806,60.6703991],[15.5252237,60.6706254],[15.5247899,60.6706776],[15.525016,60.6704087]]]}', 0, 10, '2018-10-01T12:20:27+02:00', 'Riksantikvarieämbetet', '2026-11-17', '0371f1b39bc563a4266d512231e25e99');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2680, 'af70c894-319d-4f9c-b36b-404d965b8902', 'L1998:2555', 'Stora Kopparberg 600', 'stora kopparberg 600', 'Fossil åker', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fossil åker, oregelbunden, 80x15-30 m (NV-SÖ) st. Bestående av 5 odlingsytor inbördes åtskilda av diken. Avgränsad mot omgivande mark av stora maskingrävda diken, samt enstaka röjningsrösen i N. S delen av odlingsytan finns upptagen som en del av ett större odlingsområde på 1690 års karta (RAÄ dnr 321-4220-2009).', 'Flack något sank moränmark. Skogsmark, granskog.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6715443, 15.5241047, 528638.7, 6726317.6, 528613, 6726286, 528669, 6726354, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5237563,60.6715472],[15.524173,60.6712962],[15.5246063,60.6712657],[15.5246491,60.6713144],[15.5243395,60.6715869],[15.524155,60.6716988],[15.5238876,60.6718671],[15.5236549,60.6718262],[15.5237016,60.6716796],[15.5237563,60.6715472]]]}', 0, 10, '2018-10-01T12:20:01+02:00', 'Riksantikvarieämbetet', '2026-11-17', '1b2560d9156bd42a8ccfb56964c2311b');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2685, 'af92b434-fc31-4d8b-ba6b-e3d43a287ee3', 'L1998:2534', 'Stora Kopparberg 599', 'stora kopparberg 599', 'Fossil åker', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fossil åker, oregelbunden, ca 70x20-55 m (NV-SÖ) st. Avgränsad mot omgivande mark av dike, hak, röjningsrösen och röjningssten. Odlingsytan finns med på storskifteskartan (RAÄ dnr 321-4220-2009).', 'SV-sluttande stenig moränmark. Skogsmark, gles granskog.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6752039, 15.5092925, 527826.1, 6726718.8, 527791, 6726678, 527858, 6726752, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5087355,60.6751777],[15.5089873,60.6753272],[15.5093074,60.6752275],[15.5092662,60.6751831],[15.5091267,60.6750748],[15.5091584,60.6750263],[15.5090851,60.6748781],[15.5092451,60.6748385],[15.5094283,60.6749036],[15.5098652,60.675113],[15.5098263,60.6752022],[15.5095647,60.6753531],[15.5094029,60.6754013],[15.5091853,60.6754944],[15.5088384,60.6754859],[15.508773,60.6754339],[15.5086648,60.6753145],[15.5086778,60.6752303],[15.5087355,60.6751777]]]}', 0, 10, '2018-10-01T12:19:55+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'eac0ddeeed6a18e04d755780524423d8');
