INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2743, 'b2a24aa7-68ab-45f7-9889-bb5821058d8d', 'L1998:2557', 'Stora Kopparberg 602', 'stora kopparberg 602', 'Färdväg', 'Övrig kulturhistorisk lämning', NULL, 'Färdväg bestående av vägbank, ca 330 m l (VNV-OSO) 5 m br och intill 1 m h, uppbyggd av grus. Ställvis kantad av röjningssten. Äldre sträckning av riksvägen (RAÄ dnr 321-4220-2009).', 'Flack stenig moränmark. Skogsmark, blandskog.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.672503, 15.5142371, 528098.6, 6726420.1, 527993, 6726358, 528242, 6726538, 0, 'LineString', '{"type":"LineString","coordinates":[[15.5123301,60.6735603],[15.5126597,60.673288],[15.5126668,60.673282],[15.5127957,60.6731623],[15.5128696,60.6730937],[15.5128768,60.6730868],[15.5128886,60.673074],[15.5129735,60.6729829],[15.5130801,60.6728685],[15.5137366,60.6724153],[15.5140451,60.6723065],[15.5141254,60.672289],[15.5144332,60.672222],[15.5145388,60.6722084],[15.5145541,60.6722064],[15.5146859,60.6721895],[15.5148618,60.6721669],[15.5151833,60.6720602],[15.515373,60.67204],[15.5154538,60.6720314],[15.5155583,60.6720202],[15.5155936,60.6720219],[15.5159602,60.6719903],[15.5164036,60.6719752],[15.5167455,60.6719485],[15.5168517,60.6719403]]}', 0, 25, '2018-10-01T12:20:02+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'ea9db8e1081099c25a5132cbca46f951');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2763, 'b41af973-a11d-4d8b-bf63-045c0ca73126', 'L1998:183', 'Stora Kopparberg 551', 'stora kopparberg 551', 'Område med skogsbrukslämningar', 'Övrig kulturhistorisk lämning', NULL, 'Område med skogsbrukslämningar, 30x15 m (NÖ-SV), bestående av 1 kolbotten efter resmila och 1 grund efter kolarkoja.
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2799, 'b6683790-90c8-4cc3-a171-ee4d379af55f', 'L2000:9956', 'Stora Kopparberg 149:1', 'stora kopparberg 149:1', 'Naturföremål/-bildning med bruk, tradition eller namn', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Flyttblock med tradition, 3.5x2.5 m (ÖNÖ-VSV) och ca 2.8 m h. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Flack sänka. Skogsmark, (barrskog).', '0.5 m NNV om körväg (ÖNÖ-VSV).', 'Flyttblock skall enligt traditionen vända sig oxh snurra runtvissa nätter. Uppgiften lämnad av fru Selma Gren, f 1890,Bondberg, Falun.', 'Snuskvarnen', 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6836576, 15.5362768, 529292.8, 6727672.1, 529292, 6727672, 529293, 6727673, 0, 'Point', '{"type":"Point","coordinates":[15.5362768,60.6836576]}', 0, 30, '2018-10-01T11:18:14+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'f3911752953016f1c9c3f1ee877ecd5e');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2800, 'b66a044c-3c33-47a1-9df4-4ef53dfd89ac', 'L1998:2613', 'Stora Kopparberg 592', 'stora kopparberg 592', 'Fossil åker', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Fossil åker, oregelbunden, ca 30x25 m (NV-SÖ). Bestående av en flack stenröjd yta utan distinkta avgränsningar. Odlingsytan finns med 1690 års karta (RAÄ dnr 321-4220-2009).', 'Flack moränmark. Skogsmark, blandskog.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6700206, 15.5365806, 529321.8, 6726153.4, 529311, 6726135, 529336, 6726172, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5363948,60.6700319],[15.5365267,60.6698622],[15.5366687,60.6698972],[15.5368412,60.6700371],[15.5364248,60.6701884],[15.5363948,60.6700319]]]}', 0, 10, '2018-10-01T12:20:14+02:00', 'Riksantikvarieämbetet', '2026-11-17', '58a86b5c587425e0d9a0d62fa6f6bac4');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2802, 'b6856279-871d-4c86-acca-25ce950a8d39', 'L2000:8973', 'Stora Kopparberg 136:3', 'stora kopparberg 136:3', 'Brott/täkt', 'Övrig kulturhistorisk lämning', NULL, 'Fångstgrop, närmast rund, 2.5 m diam och ca 3.5 m dj. Gropen ärcylinderformad med kallmurad vägg, av 0.2-0.5 m st stenar.Gropen är omgiven av en jordvall, 2.5-3.5 m br och intill 0.3 mh. Gropens botten delvis fylld med ris. Bevuxen med en björk, enunggran samt ca 40 tallplantor. Tre stubbar.20 m SSÖ m fångstgropen är en husgrund, 5x5x4 m och 0.5 m h.Smedja 70 m SSÖ om fångstgropen är en mindre gruva, stenbrott?,inom markerat områdex, 5 m SV om den är en varphög. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Blockig moränmark på krön av liten, flack höjd. Skogsmark(Kalhygge).', '75 m ÖNÖ om åkerhörn och ca 75 m SÖ om åkerhörn.', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6713183, 15.5919272, 532344.8, 6726323.9, 532315, 6726292, 532379, 6726351, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5913979,60.6712402],[15.591442,60.6711381],[15.5915226,60.6710576],[15.5916909,60.67104],[15.5919138,60.6710978],[15.5921476,60.6711986],[15.5923924,60.6713192],[15.5925347,60.6714378],[15.5925492,60.6715184],[15.5923955,60.6715558],[15.5921907,60.6715428],[15.5917959,60.6714972],[15.5915547,60.6714251],[15.5914416,60.6713442],[15.5913979,60.6712402]]]}', 0, 10, '2018-10-01T11:10:37+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'b46f8ce84ef88b6f497bd7283a28539d');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2832, 'b8c141ce-cc48-4b6d-8029-41146fbd0d03', 'L1998:174', 'Stora Kopparberg 560', 'stora kopparberg 560', 'Gränsmärke', 'Övrig kulturhistorisk lämning', NULL, 'Gränsröse, oval, 1,3x1,1 m st och 0,7 m h, kallmurad av 0,15-0,4 m st stenar. Två visarstenar, 0,3 m h, 0,4 m br (ÖNÖ-VSV) och 0,05 m tj respektive 0,2 m h, 0,3 m br (N-S) och 0,05 m tj.
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2884, 'bca5b38a-5245-45c9-926e-1967ae4dfff4', 'L2000:9959', 'Stora Kopparberg 152:1', 'stora kopparberg 152:1', 'Bytomt/gårdstomt', 'Fornlämning', NULL, 'Bebyggelselämningar ca 40x40 m (NÖ-SV).Husgrund, 16x8 m (Ö-V) och intill 0.4 m h. Övertorvad och bevuxenmed tio lövträd och lövbuskar. I ytan är grop.2-3 m SÖ om husgrunden ärKällarec ca 8 m diam och 0.6 m h. Stensatt invändigt. Ingång motV, delvis raserad. Övertorvad. Bevuxen med några lövbuskar. HrJohan Vikman, f 1888-11-19, Bergsgården pl med tradition m fl.uppger att enligt traditionen skall för länge sedan en kyrka halegat på den plats, där husgrunden finns. Ett pestgravfält ??skall också ha funnits på den udde, som numera avskärs avriksvägen.Ca 20 m SSÖ om lämningarna finns ett större , timrat uthus medsexkantutor (10x6).Lantbrukare E. Gullberg, f 1905, Studsarvet, uppger at han hörtav en barnvakt Strand att pestgravfältet skall ha legat inärheten av järnvägsbron, troligen på V sidan om ån.Bebyggelselämningarnas lägeöverstämmer med läget för gårdenPilarvet enl LMV Gävle akt u/22 5:2, karta 1739-62. Nuvarandegården Piltarvet är belägen ett stycke SÖ om bebyggelämningarna. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Avsatskant mot NÖ-sluttning mot sjö, moränmark. Skogsmark,(blandskog).', 'Ca 11 m NNV om V hörnet av mindre, timrat uthus (garage).', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Ej synlig ovan mark', 60.6588784, 15.5655068, 530913.1, 6724925.6, 530887, 6724900, 530941, 6724949, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5650337,60.6589374],[15.5650448,60.6588747],[15.5651401,60.6587906],[15.5653049,60.6587014],[15.5654659,60.6586498],[15.5656193,60.6586949],[15.5659259,60.6588174],[15.5660171,60.6588911],[15.5659182,60.6589715],[15.565695,60.6590481],[15.5655048,60.6590818],[15.565282,60.6590365],[15.5650702,60.658959],[15.5650337,60.6589374]]]}', 0, 10, '2018-10-01T11:18:15+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'e783e4961b74969a94d6184786fe5b0a');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (2886, 'bce91f7a-bf15-444e-87af-fe759b3a9fef', 'L2000:8813', 'Stora Kopparberg 34:1', 'stora kopparberg 34:1', 'Bytomt/gårdstomt', 'Möjlig fornlämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Gårdtomt (?), bestående av 2 husgrunder och 1 jordkällare medkallmurat valv av natursten. Ingen av husgrunderna har någotsäkert spismursröse.I anslutning till lhusgrunderna finns stengårdesgårdar och gammalodlingsmark. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'S-sluttning i moränmark. Skogsmark (barrskog).', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6754218, 15.5472729, 529901, 6726759.7, 529890, 6726745, 529909, 6726788, 0, 'MultiPoint', '{"type":"MultiPoint","coordinates":[[15.5470856,60.6753043],[15.547316,60.675294],[15.5474171,60.6756671]]}', 0, 30, '2018-10-01T11:09:49+02:00', 'Riksantikvarieämbetet', '2026-11-17', '7466f9d2b2d3ba7c754539227bc46b4b');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (3005, 'c4bd7019-9e89-42cc-becd-d3a3777ecb5e', 'L2000:9828', 'Stora Kopparberg 128:1', 'stora kopparberg 128:1', 'Bytomt/gårdstomt', 'Fornlämning', NULL, 'Bebyggelselämningar, ca 40x35 m (NNV-SSÖ) bestående av 2husgrunder och 1 källarruin.Husgrund, närmast kvadratik, 7.5 m sida och 0.5 m h. Övertorvad.I mitten en mindre kulle med tegelfragment.Ca 3 m N därom ärHusgrund, 6x5 m (Ö-V) och 0.6 m h. I mitten en liten upphöjningmed tegelfragment.Ca 2 m S om den S husgrunden ärKällarruin, 8x5 m NNV-SSÖ) och intill 1 m h. Öppning mot N. SVBhörnet starkt raserat. Synlig rest av valvning. Hagen, därgårdslämningarna ligger, kallas av flera ortsbor för Koernershage. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'N delen av höjdsträckning (Ö-V). Hagmark.', NULL, 'Enligt K-E Forsslund (1934:87f) är detta lämningarna efter dengård där Erik i Varbo skall ha bott på 1300-talet. JacobsIngelsson knyter 1719 Erik i Valbo till en gård där det enda somfinns kvar är en stor hwal (f) der kiällare.', NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Ej synlig ovan mark', 60.6565631, 15.5700097, 531161.5, 6724669.9, 531138, 6724648, 531183, 6724691, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5697892,60.6564329],[15.5699831,60.656376],[15.5701988,60.6563675],[15.5703338,60.6564341],[15.5703956,60.6565525],[15.5703442,60.6566366],[15.570216,60.6567224],[15.5700624,60.6567454],[15.5697628,60.6567161],[15.5696094,60.6566799],[15.5695914,60.6565885],[15.5697892,60.6564329]]]}', 0, 10, '2018-10-01T11:16:45+02:00', 'Riksantikvarieämbetet', '2026-11-17', '7a688725bee9857bb36df5f041832d53');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (3012, 'c573f370-b4ba-4719-b34d-2a02553b416b', 'L1998:2094', 'Stora Kopparberg 611', 'stora kopparberg 611', 'Minnesmärke', 'Övrig kulturhistorisk lämning', NULL, 'Minnessten 1,1 m h, 1,0 m br (NNV-SSÖ) och 0,3 m dj. På den åt ÖNÖ vända sidan är en metallplatta, 0,4x0,25 m, med texten:
