INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (3115, 'cb76f475-04c9-4398-b65a-ca26126a5430', 'L2000:8972', 'Stora Kopparberg 81:2', 'stora kopparberg 81:2', 'Gränsmärke', 'Övrig kulturhistorisk lämning', NULL, 'Gruvområde, ca 80x55 m (ÖNÖ-VSV), bestående av 3 gruvhål,skrotstensvarp och 1 kojruin,separat beskrivna.Gruvhål, närmast ovalt, ca 8x7 m (Ö-V), ca 3 m dj. I botten ärnedrasad sten och skrotsten. Ö resp NÖ därom är skrotstensvarp.16 m SV om gruvhålet är:Gruvhål, närmast runt, ca 8 m i diam, ca 3 m dj. I botten ärnedrasad sten och skrotsten. Omkring gruvhålet ärskrotstensvarp.2 m SV om gruvhålet är:Gruvhål, närmast ca 8x7 m (NÖ-SV), ca 2 m dj. I botten ärnedrasad sten och skrotsten. I Nö kanten är ett större block.SV om gruvhålet är ett större skrotstensvarp.10 m VNV om det NÖ gruvhålet är en kojruin med välbevaradspismur.27 m NV om det NÖ gruvhålet och inom området är2) Gränsröse (ej nuvarande gräns), rektangulärt, 1.5x1.2 m(SÖ-NV) 0.4 m h av huggen gråsten i kallmur. På toppen är enupprättstående visarsten. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Flack SSÖ-sluttning av blockig moränmark. Skogsmark (hygge medrikligt med utsparade tallar).', 'Nr q är ca 100 m VSV om väg (NNV-SSÖ).', NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6739538, 15.5960692, 532568.5, 6726619.4, 532568, 6726619, 532569, 6726620, 0, 'Point', '{"type":"Point","coordinates":[15.5960692,60.6739538]}', 0, 15, '2018-10-01T11:10:37+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'd2ae32fe5a9c0e39a2f7a4e4bd4a199b');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (3213, 'd1e11477-72c0-48c6-a397-34c8c0d3adb4', 'L2000:9957', 'Stora Kopparberg 150:1', 'stora kopparberg 150:1', 'Vägmärke', 'Ingen antikvarisk bedömning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Postament till milstolpe, kallmurat, kvadratisk, 1.6 m sida och0.6 m h, av otuktade gråstenar, 0.3-0.85 m st.Postamentet borttaget vid vägarbeten. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'N-delen av höjd. Skogsmark.', '2 m VSV om gammal landsväg (NNV-SSÖ).', NULL, NULL, 'Bekräftad i fält', 'Förstörd', 'Okänd', 'Synlig ovan mark', 60.6799823, 15.5340802, 529176.1, 6727261.7, 529176, 6727261, 529177, 6727262, 0, 'Point', '{"type":"Point","coordinates":[15.5340802,60.6799823]}', 0, 13, '2018-10-01T11:18:14+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'a3c08cc9735fa08a5fce7145a5b62f75');
