INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (3365, 'db67cc12-7b13-44e9-a039-f1f8d98a6da9', 'L2000:9195', 'Stora Kopparberg 216:1', 'stora kopparberg 216:1', 'Bytomt/gårdstomt', 'Fornlämning', NULL, 'Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', NULL, NULL, NULL, 'Klubbtäkts gamla tomt', 'Bekräftad i fält', 'Okänd', 'Okänd', 'Ej synlig ovan mark', 60.6564755, 15.5340233, 529194.3, 6724643.6, 529146, 6724618, 529239, 6724669, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5331915,60.6563325],[15.5334915,60.656274],[15.533729,60.6562854],[15.5341494,60.6562648],[15.5345917,60.6562516],[15.5348036,60.6562825],[15.5348327,60.6563274],[15.5348322,60.6564583],[15.5347987,60.6566016],[15.5347034,60.6566748],[15.5343488,60.6566901],[15.5339722,60.6567],[15.5336543,60.6566849],[15.5332306,60.6566319],[15.5331506,60.6565223],[15.5331915,60.6563325]]]}', 0, 10, '2018-10-01T11:11:41+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'd580fbfe4800dd249c10e47916ed79c7');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (3408, 'de8e84d5-c749-4747-aac2-4a69c67c9682', 'L1999:593', 'Stora Kopparberg 160:1', 'stora kopparberg 160:1', 'Hyttområde', 'Fornlämning', NULL, 'Hyttområde, bestående av  rest av ett slaggvarp. Det är beläget15-20 m ÖSÖ om bäckfåra (NNÖ-SSV) och ca 15 m SÖ om damm(Bengstsarvsdammen), 90x20 m m (N-S) och är beläget iV-sluttningen av höjd. Delvis intill 1.5 m h men nästanborttaget. S om mitten är på varpet en husgrund.Varpet är i sin N del urschaktat, av planat och bebyggt med tvåhus.15 m mot VSV är en i huvudsak recent fördämningsvall, 20x3-4 m(Ö-V) och 1 m h, av jord, sten och cement, övertorvad och 15 mVNV därom en husgrund med okänd funktion.Slaggvarpet innehåller mörkbrun, fluten kopparslagg.Slaggklumparna är vanligen 0.05-0.2 m st.15 m VNV om slaggvarpet finns en V bäckfåra och en mindre, delvisunderjordiskt ränna, Ö om denna en stor uthusbyggnad. Enluppgift drev vattenhjulet ett tröskverk i logen.! Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'V foten av hög moränhöjd Ö om bäck. Skogsmark och tomtmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6772156, 15.5057313, 527629.8, 6726941.3, 527613, 6726898, 527648, 6726983, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5057709,60.6768284],[15.5058516,60.676848],[15.5059188,60.6769717],[15.5059598,60.677047],[15.5059715,60.6771152],[15.5059321,60.6771854],[15.5058849,60.6772214],[15.5058377,60.6772466],[15.5058342,60.6772664],[15.5059079,60.6773129],[15.5059961,60.677354],[15.5060662,60.6774059],[15.5060521,60.6774526],[15.5060088,60.677512],[15.5059252,60.6775535],[15.5057938,60.6775808],[15.5057243,60.6775809],[15.5056689,60.6775344],[15.5056062,60.6774825],[15.5055357,60.6773965],[15.50548,60.6773212],[15.5054572,60.6772368],[15.5054379,60.6771471],[15.5054296,60.6770537],[15.5054874,60.6769889],[15.5056071,60.6768989],[15.5057163,60.6768537],[15.5057709,60.6768284]]]}', 0, 10, '2018-10-01T11:21:58+02:00', 'Riksantikvarieämbetet', '2026-11-17', '51a88d360c3d9f5b9a0ec69ff61fac61');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (3418, 'def070cb-db5d-4b35-a7d4-67ee19440557', 'L1998:6504', 'Stora Kopparberg 619', 'stora kopparberg 619', 'Färdväg', 'Övrig kulturhistorisk lämning', NULL, 'Vägbank, ca 70 m l (Ö-V) och 3 m br, svagt bågformad. Vägbanken är något uppbyggd utmed S kanten och nedgrävd utmed N kanten. Diken på båda sidor, 0,3 m br och 0,1-0,2 m dj, vilka ställvis kantas av röjningssten. Fyra olika konstruktionsdetaljer med 0,1 m dj skålformade hjulspår kunde konstateras. Vägbanken ligger inom NÖ delen av en gårdstomt, RAÄ nr. Stora Kopparberg 583. Vägbanken utgör sannolikt en rest av den väg som finns på kartmaterial från 1700- och 1800-talen. Påträffad vid arkeologisk förundersökning 2014 (RAÄ dnr 3.4.2-406-2015).', NULL, NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Delundersökt', 'Synlig ovan mark', 60.6692429, 15.5406805, 529546.5, 6726068.6, 529512, 6726059, 529580, 6726073, 0, 'LineString', '{"type":"LineString","coordinates":[[15.5400531,60.6692577],[15.5402046,60.6692648],[15.5403592,60.6692734],[15.5404349,60.6692762],[15.5404948,60.6692729],[15.540561,60.6692695],[15.5406744,60.6692629],[15.5408003,60.66925],[15.5409638,60.6692261],[15.5411084,60.6692008],[15.5412875,60.6691614]]}', 0, 25, '2018-10-01T12:37:20+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'a9345f0d4962078cd293aa15bb825f95');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (3424, 'df30cf5f-c065-4a00-9779-a1493cf1c50a', 'L1998:162', 'Stora Kopparberg 552', 'stora kopparberg 552', 'Gruvhål', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Skärpning, 4x2 m (N-S) och 1,2 m dj. I SV är ett gråbergsvarp, 4x1,5 m st och 0,3-0,5 m h, bestående av kantiga stenar. (RAÄ dnr 326-214-2005)', 'Ö-sluttande blockig moränmark. Skogsmark (hygge).', '7 m ÖSÖ om hyggeskant/rågång.', NULL, NULL, 'Bekräftad i fält', 'Åverkan', 'Ej undersökt', 'Synlig ovan mark', 60.6350909, 15.5477612, 529965.1, 6722268.1, 529965, 6722268, 529966, 6722269, 0, 'Point', '{"type":"Point","coordinates":[15.5477612,60.6350909]}', 0, 30, '2018-10-01T12:09:30+02:00', 'Riksantikvarieämbetet', '2026-11-17', '43c7feb308438bf0c74f5b254150f6ec');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (3580, 'e967c987-ad36-4579-a073-d1032302d713', 'L1998:2095', 'Stora Kopparberg 612', 'stora kopparberg 612', 'Område med fossil åkermark', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Område med fossil åkermark, ca 65x50 m (NNÖ-SSV). Bestående av 2 odlingsytor, 1 stenmur och 1 röjningsröse. Odlingsytorna är ca 40 m l (NV-SÖ) och 10-20 m br med ett mellanliggande impediment. I NÖ delen av området är ett röjningsröse 20x5 m (Ö-V) och intill 1,3 m h, bestående av ca 0,2-0,5 m st stenar, något utrasat. Sidorna är kallmurade. Ungefär mitt i området är en stenmur, 40 m l (VNV-ÖSÖ), 1,5 m br och intill 1,5 m h. Kallmurad av 0,1-0,8 m st mestades rundade stenar (RAÄ dnr 326-361-2011).', 'Flack moränmark. Skogsmark, igenväxt odlingsmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6711967, 15.5847296, 531951.7, 6726306.8, 531920, 6726263, 531983, 6726348, 0, 'Polygon', '{"type":"Polygon","coordinates":[[[15.5846925,60.6715601],[15.5844373,60.6714676],[15.5843026,60.671204],[15.5841565,60.6711224],[15.5843219,60.6709984],[15.5846318,60.6708737],[15.5848757,60.6708047],[15.585144,60.6711562],[15.5853036,60.6712932],[15.5850632,60.67143],[15.5848572,60.6715182],[15.5846925,60.6715601]]]}', 0, 10, '2018-10-01T12:17:48+02:00', 'Riksantikvarieämbetet', '2026-11-17', '3524c17f3af588a9eb0fcf6a5c5802c6');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (3682, 'efe9d12c-3824-4ab1-8ac4-ef69d76a1875', 'L1999:527', 'Stora Kopparberg 349:1', 'stora kopparberg 349:1', 'Plats med tradition', 'Övrig kulturhistorisk lämning', NULL, 'Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', NULL, NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6544007, 15.5733074, 531343.8, 6724430.6, 531343, 6724430, 531344, 6724431, 0, 'Point', '{"type":"Point","coordinates":[15.5733074,60.6544007]}', 0, 30, '2018-10-01T11:21:32+02:00', 'Riksantikvarieämbetet', '2026-11-17', '3c1ff6199bccb4b825ac07e98bd2db6e');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (3779, 'f6dc1f92-9370-4194-87e6-5ba55ed8ea7a', 'L1998:2199', 'Stora Kopparberg 582', 'stora kopparberg 582', 'Färdväg', 'Övrig kulturhistorisk lämning', NULL, 'Färdväg bestående av vägbank 15 m l (NNV-SSÖ) 6 m br och i VSV intill 1 m h. Uppbyggd av sten och grus. VSV kanten består av 0,2-0,8 m st stenar i kallmur. Äldre sträckning av riksvägen (RAÄ dnr 321-4220-2009).', 'V-sluttande moränmark. Skogsmark, yngre blandskog.', NULL, '13F5g NÖ', NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6789146, 15.5072923, 527713.6, 6727131.2, 527708, 6727125, 527720, 6727138, 0, 'LineString', '{"type":"LineString","coordinates":[[15.5073931,60.6788605],[15.5071915,60.6789686]]}', 0, 25, '2018-10-01T12:18:26+02:00', 'Riksantikvarieämbetet', '2026-11-17', '099d96f3f33baadcf321abaea070eb7a');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (3818, 'fa96b2c5-d546-46e1-8d64-e5e431fef8fe', 'L1998:113', 'Stora Kopparberg 556', 'stora kopparberg 556', 'Område med skogsbrukslämningar', 'Övrig kulturhistorisk lämning', NULL, 'Område med skogsbrukslämningar. ca 45x30 m (N-S), bestående av 2 kolbotten efter resmila och 1 grund efter kolarkoja.
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (3843, 'fba838ac-a26c-4a89-af57-4c8308721911', 'L1999:446', 'Stora Kopparberg 134:1', 'stora kopparberg 134:1', 'Gruvområde', 'Övrig kulturhistorisk lämning', 'Den antikvariska bedömningen är migrerad från äldre databas.  Motivering av den antikvariska bedömningen kan eventuellt finnas under antikvarisk kommentar.', 'Gruvområde, bestående av2 gruvhål samt skrotstensvarp.Gruvhål avlångst ca 35 x14 m (Ö-V) och ca 4 m? dj tillvattenytan. Delvis fylld med skräp. Vatten i botten 15 resp 20 mS om gruvan finns två varphögar, 10 resp 30 m NÖ om gruvhålet ärtvå varphögar.5 m SÖ om gruvan är en husgrund med källarliknandetillbyggnader.Längst i S och 18 m SSV om landsväg VNV-ÖSÖ ärGruvhål, oregelbundet närmast runt, ca 6-8 m i diam, 0.3-1.5 m djtill vattenytan.V-SV-S därom är skrotstensvarp Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Falck S-sluttning av mindre moränhöjd. Skogsmark (övöervägandetät lövskog, lövsly).', 'Det största gruvhålet är ca 35 m NNÖ om väg (VNV-ÖSÖ) och ca 4 mÖ gammal väg N-S.', NULL, 'Slättmyregruvan', 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6678682, 15.5812779, 531766.3, 6725934.4, 531721, 6725862, 531819, 6725991, 0, 'GeometryCollection', '{"type":"GeometryCollection","geometries":[{"type":"LineString","coordinates":[[15.5810512,60.6673037],[15.5810255,60.6673162],[15.5810144,60.6673378],[15.5810436,60.6673629],[15.5811021,60.6673684],[15.5811314,60.6673559],[15.5811424,60.6673343],[15.5811097,60.6673128],[15.5810512,60.6673037]]},{"type":"Polygon","coordinates":[[[15.5808965,60.668097],[15.5807356,60.6680752],[15.5805639,60.6680408],[15.5804616,60.6679958],[15.5804654,60.6679528],[15.5805643,60.6678813],[15.5806742,60.667799],[15.5806891,60.667679],[15.5807772,60.6675376],[15.5808727,60.6673783],[15.580968,60.6672709],[15.5810522,60.6672209],[15.5811692,60.6672355],[15.5812605,60.6673002],[15.5812529,60.6673844],[15.5812272,60.6674507],[15.5813038,60.66751],[15.5815122,60.6675194],[15.5815961,60.6675876],[15.5816652,60.6677294],[15.5816685,60.6678638],[15.5817049,60.6679338],[15.5818254,60.6680039],[15.5820481,60.6681298],[15.5822306,60.6682646],[15.5822195,60.6683058],[15.5821683,60.668338],[15.5820439,60.6683628],[15.5819415,60.6683662],[15.5818173,60.6683409],[15.5816455,60.6682939],[15.5814737,60.6682756],[15.5813202,60.6682466],[15.5810463,60.6681242],[15.5808965,60.668097]]]},{"type":"LineString","coordinates":[[15.5809004,60.667968],[15.5809259,60.6680182],[15.5810136,60.6680435],[15.5811123,60.6680329],[15.5812879,60.668019],[15.5814561,60.6680229],[15.5815768,60.668007],[15.5816171,60.6679748],[15.581566,60.6679496],[15.58146,60.6679189],[15.5812589,60.6679042],[15.5811053,60.6679254],[15.5809004,60.667968]]}]}', 0, 25, '2018-10-01T11:21:02+02:00', 'Riksantikvarieämbetet', '2026-11-17', '4011ad5d5f700bc968a325c5b2bda35e');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (3850, 'fc024e39-d8c4-4688-99a0-bf3399f54de0', 'L1998:2611', 'Stora Kopparberg 590', 'stora kopparberg 590', 'Färdväg', 'Övrig kulturhistorisk lämning', NULL, 'Färdväg bestående av vägbank ca 80 m l (Ö-V), 5 m br och intill 0 5 m h. Uppbyggd av grus och sten. Äldre sträckning av riksvägen (RAÄ dnr 321-4220-2009).', 'S-sluttande stenig moränmark. Skogsmark, gles blandskog.', NULL, NULL, NULL, 'Bekräftad i fält', 'Ej skadad', 'Ej undersökt', 'Synlig ovan mark', 60.6708949, 15.52588, 528736.2, 6726246, 528697, 6726244, 528775, 6726252, 0, 'LineString', '{"type":"LineString","coordinates":[[15.5251701,60.6708935],[15.5258751,60.6708805],[15.525912,60.6708806],[15.5262231,60.6708957],[15.526582,60.6709387]]}', 0, 25, '2018-10-01T12:20:13+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'c74916100cc33fb8f41c0d408742f0fd');
INSERT INTO lamning (id, uuid, lamningsnummer, raa_nummer, raa_sok, lamningstyp, bedomning, bedomning_motivering, beskrivning, terrang, orientering, tradition, namn, aktualitet, skada, undersokning, placering, lat, lon, e, n, min_e, min_n, max_e, max_n, rumsklass, geometrityp, geometri, geometri_forenklad, osakerhet_m, publicerad, publicerad_av, uttagsdatum, hash) VALUES (3865, 'fccb77d5-96d4-4ed7-95b7-928edd94fa63', 'L2000:8744', 'Stora Kopparberg 39:1', 'stora kopparberg 39:1', 'Husgrund, historisk tid', 'Övrig kulturhistorisk lämning', NULL, 'Bebyggelselämning bestående av 3 husgrunder. Husgrunderna liggertätt och är 7-12x5-6 m . Husgrunden i mitten har spismursröse.Beväxta med enstaka björkar och tallar. Beskrivningen är inte kvalitetssäkrad. Information kan saknas, vara felaktig eller inaktuell. Se även Inventeringsbok.', 'Impediment i moränmark. Hagmark.', NULL, NULL, NULL, 'Bekräftad i fält', 'Okänd', 'Okänd', 'Synlig ovan mark', 60.6727054, 15.5684415, 531060.2, 6726467, 531049, 6726461, 531067, 6726474, 0, 'MultiPoint', '{"type":"MultiPoint","coordinates":[[15.5682501,60.6726948],[15.5685135,60.6726577],[15.5685608,60.6727636]]}', 0, 30, '2018-10-01T11:09:28+02:00', 'Riksantikvarieämbetet', '2026-11-17', 'fcb793f73754c7618cf6608777826cb5');
